TN.defSec("infectious-immunologic",{"chlamydia-gonorrhea":{"id":"chlamydia-gonorrhea","variants":[{"id":"sti-chlamydia-gonorrhea-uncomplicated","o":{"L":[{"t":"NAAT (cervical, vaginal, urethral or first-catch urine specimens); pregnancy test; consider HIV, syphilis and hepatitis screening"}],"A":[{"t":"Chlamydia: Azithromycin 1 g PO single dose, or Doxycycline 100 mg PO twice daily for 7 days (alternatives: Erythromycin base 500 mg PO four times daily, Ofloxacin 300 mg PO twice daily or Levofloxacin 500 mg PO daily for 7 days)"},{"t":"Gonorrhea: Ceftriaxone 250 mg IM AND Azithromycin 1 g PO single dose or Doxycycline 100 mg PO twice daily for 7 days; alternative: Cefixime 400 mg PO single dose AND azithromycin 1 g PO or doxycycline 100 mg PO twice daily for 7 days, and test-of-cure in 1 week"}],"T":[{"t":"Treat all recent sexual partners; avoid sexual contact for 7 days after completing antibiotic treatment and symptoms have resolved"}]},"name":"Uncomplicated urethritis / cervicitis (chlamydia, gonorrhea)","level":"III","imp":"Urethritis / cervicitis (chlamydia / gonorrhea)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۴ ساله با ترشح چرکی مجرا و دیزوری.","why":"درمان تک‌دوز دوگانه؛ شرکای جنسی هم درمان شوند."},{"id":"sti-gonococcemia-disseminated","o":{"L":[{"t":"NAAT; cultures of cervix, rectum and pharynx (blood, skin lesions and joint fluid yield positive in only 20% to 50%)"}],"A":[{"t":"Ceftriaxone 1 g daily IM/IV AND Azithromycin 1 g PO single dose; duration of parenteral therapy in consultation with an infectious disease specialist"}],"Co":[{"t":"Infectious disease consultation; avoid sexual contact for 7 days after treatment"}]},"name":"Disseminated gonococcal infection","level":"II","imp":"Disseminated gonococcal infection","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۲ ساله با تب، پوستول‌های حساس روی اندام، تنوسینوویت مچ.","why":"منتشر: ceftriaxone تزریقی و آزیترومایسین؛ کشت چند محل."}],"ch":"87","name":"Chlamydial and gonococcal infections (urethritis, cervicitis, disseminated gonococcemia)","name_fa":"عفونت‌های کلامیدیایی و گنوکوکی (اورتریت، سرویسیت، گنوکوکسمی منتشر)","cc":["genital-complaint","urinary-symptoms"],"keywords":"chlamydia, gonorrhea, azithromycin, doxycycline, ceftriaxone, cefixime, NAAT, disseminated gonococcal infection, STI, کلامیدیا, سوزاک","status":"draft","features":["STI یک مشکل مهم سلامت عمومی؛ عوارض: ناباروری، سرطان و مشکلات اوروژنیتال؛ به‌علت مشکل پیگیری، رژیم تک‌دوز ترجیح دارد؛ عفونت‌ها اغلب همزمان: HIV، سیفلیس و هپاتیت را هم غربال کن؛ تست حاملگی؛ درمان همه شرکای اخیر؛ توصیه زمان شروع مجدد رابطه؛ رژیم‌ها برای بزرگسال غیرحامله (راهنمای CDC برای کودکان و حاملگی)","کلامیدیا (C. trachomatis): مردان: اورتریت، اپیدیدیمیت، ارکیت، پروکتیت یا Reiter؛ زنان: سرویسیت اغلب بی‌علامت یا ترشح، spotting، دیزوری؛ پیوری استریل؛ عوارض: PID، حاملگی نابجا، ناباروری؛ تشخیص با NAAT (سواب واژینال یا ادرار اول‌جریان مردان)؛ ELISA/DNA probe حساسیت 75٪ تا 90٪","گنوکوک (N. gonorrhoeae): مردان: اورتریت، اپیدیدیمیت، ارکیت، پروستاتیت؛ زنان: اورتریت، سرویسیت، PID، ناباروری؛ بسیاری بی‌علامت و همزمان با کلامیدیا؛ مردان: دیزوری و ترشح چرکی","منتشر: تب، راش (پوستول‌های حساس روی پایه قرمز، اندام ± کف دست/پا)، تنوسینوویت یا آرتریت سپتیک؛ کشت خون، ضایعه پوستی و مایع مفصل تنها در 20٪ تا 50٪ مثبت؛ کشت سرویکس، رکتوم و حلق می‌تواند بازده را بالا ببرد"],"ddx":[{"n":"Pelvic inflammatory disease |","cm":1},{"n":"Disseminated gonococcal infection (septic arthritis) |","cm":1},{"n":"Epididymitis / prostatitis |"},{"n":"Trichomoniasis / herpes simplex |"},{"n":"Urinary tract infection |"}],"redflags":["تب با راش پوستول‌دار و آرتریت (گنوکوک منتشر)، درد لگن (PID)"],"guide":"# کلامیدیا\nazithromycin 1 g PO تک‌دوز یا doxycycline 100 mg PO دو بار روزانه 7 روز (اورتریت/سرویسیت ساده)؛ جایگزین 7 روزه: erythromycin base 500 mg PO چهار بار روزانه، ofloxacin 300 mg PO دو بار روزانه یا levofloxacin 500 mg PO روزانه؛ 7 روز پرهیز از تماس جنسی بعد از اتمام درمان و رفع علائم.\n# گنوکوک\nساده: درمان دوگانه: ceftriaxone 250 mg IM و azithromycin 1 g PO تک‌دوز یا doxycycline 100 mg PO دو بار روزانه 7 روز؛ جایگزین: cefixime 400 mg PO تک‌دوز و azithromycin 1 g یا doxycycline 7 روز و test-of-cure ظرف 1 هفته. منتشر: ابتدا ceftriaxone 1 g روزانه IM/IV و azithromycin 1 g PO تک‌دوز؛ مدت تزریقی با مشاور عفونی.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 87: Sexually Transmitted Infections, pp. 473–479"},"syphilis":{"id":"syphilis","variants":[{"id":"syphilis-primary-secondary","o":{"L":[{"t":"Nontreponemal test (VDRL/RPR) confirmed by treponemal antibody immunoassay; darkfield microscopy; HIV and hepatitis screening; pregnancy test"}],"A":[{"t":"Benzathine penicillin G 2.4 million units IM single dose (be aware of Jarisch-Herxheimer reaction within the first 24 hours); alternatives for primary, secondary and early latent: Doxycycline 100 mg PO twice daily for 14 days, or Tetracycline 500 mg PO four times daily for 28 days"}],"Co":[{"t":"Treat sexual partners; follow-up"}]},"name":"Primary or secondary syphilis","level":"III","imp":"Primary or secondary syphilis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله با زخم بدون درد روی آلت و لنفادنوپاتی اینگوینال.","why":"یک دوز پنی‌سیلین بنزاتین؛ آگاهی از Jarisch-Herxheimer."},{"id":"syphilis-tertiary","o":{"I":[{"t":"Chest radiograph (thoracic aneurysm); neurologic evaluation as indicated","fl":[{"k":"note","v":"lumbar puncture not specified in this chapter"}]}],"A":[{"t":"Benzathine penicillin G 2.4 million units IM weekly for 3 weeks"}],"Co":[{"t":"Infectious disease / neurology / cardiology as indicated"}]},"name":"Tertiary / latent syphilis","level":"II","imp":"Tertiary syphilis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مردی ۶۰ ساله با دمانس پیشرونده، آتاکسی و آنوریسم آئورت توراسیک؛ سرولوژی مثبت.","why":"سیفلیس ثالثیه با پنی‌سیلین بنزاتین هفتگی؛ ارزیابی عصبی/قلبی."}],"ch":"87","name":"Syphilis","name_fa":"سیفلیس","cc":["genital-complaint","rash"],"keywords":"syphilis, chancre, secondary syphilis, benzathine penicillin G, RPR, VDRL, Jarisch-Herxheimer, سیفلیس","status":"draft","features":["Treponema pallidum؛ سه مرحله؛ اولیه: chancre تنها زخم بدون درد با لبه سفت روی آلت/ولوا؛ بهبود پس از 3 تا 6 هفته؛ ثانویه: چند هفته بعد: راش و لنفادنوپاتی (پاپول‌های صورتی/قرمز بدون خارش روی تنه و سطوح فلکسور، سپس کف دست/پا)؛ تب، ناخوشی، سردرد، گلودرد؛ ثالثیه/نهفته: یک‌سوم، 3 تا 20 سال بعد: درگیری عصبی (مننژیت، دمانس، tabes dorsalis)، قلبی-عروقی (آنوریسم توراسیک) و gumma","تست: غیرترپونمی (VDRL، RPR) 1 تا 4 هفته پس از chancre مثبت؛ باید با تست ترپونمی اختصاصی تأیید شود؛ مشاهده مستقیم با darkfield microscopy در اولیه/ثانویه/مادرزادی زودرس تشخیصی"],"ddx":[{"n":"Neurosyphilis / cardiovascular syphilis |","cm":1},{"n":"Genital herpes |"},{"n":"Chancroid |"},{"n":"Secondary syphilis rash mimics (drug eruption, pityriasis rosea) |"}],"redflags":["علائم عصبی یا قلبی-عروقی (ثالثیه)، حاملگی"],"guide":"اولیه و ثانویه: benzathine penicillin G 2.4 میلیون واحد IM تک‌دوز؛ مراقب واکنش Jarisch–Herxheimer (تب، سردرد، میالژی) ظرف 24 ساعت. جایگزین (اولیه/ثانویه/نهفته زودرس): doxycycline 100 mg PO دو بار روزانه 14 روز یا tetracycline 500 mg PO چهار بار روزانه 28 روز. ثالثیه: benzathine penicillin G 2.4 میلیون واحد IM هفتگی × 3 هفته.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 87: Sexually Transmitted Infections, pp. 473–479"},"genital-ulcers-hsv-chancroid":{"id":"genital-ulcers-hsv-chancroid","variants":[{"id":"hsv-genital-first","o":{"L":[{"t":"Viral culture from vesicles or early ulcers (more reliable than Tzanck smear)"}],"A":[{"t":"Acyclovir 400 mg PO three times daily, or Valacyclovir 1 g PO twice daily, or Famciclovir 250 mg PO three times daily for 7 to 10 days (hastens recovery but does not cure)"},{"t":"Proctitis or oral infection: Acyclovir 400 mg five times daily for 7 to 10 days"},{"t":"Severe disease requiring hospitalization: Acyclovir IV 5 to 10 mg/kg body weight every 8 hours"},{"t":"Recurrent episodes: Valacyclovir 1 g PO daily or Acyclovir 400 mg PO three times daily for 5 days (initiate when symptoms begin)"}]},"name":"Genital herpes (first episode)","level":"III","imp":"Genital herpes simplex infection","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۵ ساله با وزیکول دردناک لابیا، تب و لنفادنوپاتی اینگوینال.","why":"اولین اپیزود: ضدویروس 7 تا 10 روز؛ شدید: acyclovir وریدی."},{"id":"chancroid-main","o":{"L":[{"t":"Test for other sexually transmitted infections such as HSV, syphilis and HIV; culture from ulcer or bubo (special culture medium)"}],"A":[{"t":"Azithromycin 1 g PO single dose, or Ceftriaxone 250 mg IM single dose, or Erythromycin base 500 mg PO three times daily for 7 days, or Ciprofloxacin 500 mg PO twice daily for 3 days"}],"T":[{"t":"Incision and drainage of buboes can be considered for symptomatic relief"}],"Co":[{"t":"Treat all sexual partners in the 10 days prior to diagnosis regardless of symptoms"}]},"name":"Chancroid","level":"III","imp":"Chancroid","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله با زخم دردناک آلت و لنفادنوپاتی حساس.","why":"تک‌دوز azithromycin یا ceftriaxone؛ تست سایر STI."}],"ch":"87","name":"Genital herpes simplex and chancroid","name_fa":"هرپس تناسلی و شانکروئید","cc":["genital-complaint"],"keywords":"genital herpes, HSV, acyclovir, valacyclovir, famciclovir, chancroid, Haemophilus ducreyi, bubo, هرپس تناسلی, شانکروئید","status":"draft","features":["HSV اولیه: پرودروم 2 تا 24 ساعت (درد، گزگز، سوزش)؛ سپس سردرد، تب، لنفادنوپاتی اینگوینال دردناک، بی‌اشتهایی، ناخوشی؛ پاپول و وزیکول روی پایه اریتماتو و فرسایش؛ مردان: زخم دردناک روی ساقه یا glans؛ زنان: introitus، میتوس، لابیا و پرینه؛ دفع ویروس 10 تا 12 روز و بهبود ≤ 3 هفته؛ تشخیص بالینی؛ کشت ویروسی از وزیکول یا زخم اولیه قابل‌اعتمادتر از Tzanck","شانکروئید (H. ducreyi): پاپول اریتماتوی دردناک → زخم و پوستول طی 2 روز؛ تا 50٪ چند ضایعه («kissing lesions»)؛ لنفادنوپاتی دردناک 1 تا 2 هفته بعد → bubo نکروتیک؛ تشخیص بالینی (افتراق از سیفلیس و HSV)؛ کشت نیازمند محیط خاص"],"ddx":[{"n":"Syphilis |","cm":1},{"n":"HIV / other STI |","cm":1},{"n":"Herpes simplex |"},{"n":"Chancroid |"}],"redflags":["بیماری شدید نیازمند بستری، ایمنوساپرس"],"guide":"HSV اولین اپیزود: 7 تا 10 روز acyclovir 400 mg PO سه بار روزانه، valacyclovir 1 g PO دو بار روزانه یا famciclovir 250 mg PO سه بار روزانه (بهبود را تسریع می‌کند ولی درمان قطعی نیست). پروکتیت یا دهانی: acyclovir 400 mg پنج بار روزانه 7 تا 10 روز. بستری شدید: acyclovir IV 5 تا 10 mg/kg هر 8 ساعت. عود: 5 روز valacyclovir 1 g PO روزانه یا acyclovir 400 mg PO سه بار روزانه (در شروع علائم). شانکروئید: azithromycin 1 g PO تک‌دوز، ceftriaxone 250 mg IM تک‌دوز، erythromycin base 500 mg PO سه بار روزانه 7 روز یا ciprofloxacin 500 mg PO دو بار روزانه 3 روز؛ I&D bubo برای تسکین؛ تست HSV، سیفلیس و HIV؛ درمان شرکای 10 روز قبل از تشخیص.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 87: Sexually Transmitted Infections, pp. 473–479"},"staphylococcal-toxic-shock":{"id":"staphylococcal-toxic-shock","variants":[{"id":"tss-staph-shock","o":{"I":[{"t":"Chest radiograph; surgical consultation for debridement of infected tissue"}],"L":[{"t":"CBC, comprehensive metabolic panel, coagulation studies, creatine phosphokinase, urinalysis, blood gas, cultures of blood and other potential sources of infection"}],"S":[{"t":"Aggressive IV crystalloid (normal saline) for hypotension and shock","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"A":[{"t":"Suspected MRSA: Vancomycin 15 mg/kg IV every 12 hours (maximum dose 2.25 g), or Linezolid 600 mg IV plus Clindamycin 900 mg IV every 8 hours"},{"t":"Suspected MSSA: Nafcillin or Oxacillin 2 g IV every 4 hours plus Clindamycin 900 mg IV every 8 hours"}],"T":[{"t":"Vasopressors for persistent hypotension; drain abscesses; remove foreign bodies (tampon)"},{"t":"Consider IV immunoglobulin after consultation with infectious disease or critical care when no clinical improvement after 6 hours of aggressive treatment"}],"Co":[{"t":"Infectious disease / critical care; surgery if infected tissue; ICU"}]},"name":"Staphylococcal toxic shock syndrome","level":"I","imp":"Staphylococcal toxic shock syndrome","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"زنی ۲۴ ساله با تامپون، تب 40، اریترودرم، فشار 70/40 و استفراغ.","why":"TSS: احیای تهاجمی، برداشتن منبع (تامپون)، vancomycin + clindamycin."}],"ch":"88","name":"Staphylococcal toxic shock syndrome","name_fa":"سندرم شوک توکسیک استافیلوکوکی","cc":["hypotension-shock","fever","rash"],"keywords":"toxic shock syndrome, TSS, Staphylococcus aureus, tampon, vancomycin, clindamycin, linezolid, IV immunoglobulin, شوک توکسیک","status":"draft","features":["عفونت شدید تهدیدکننده حیات S. aureus با پیشرفت سریع به اختلال چندارگانی، اختلال شدید الکترولیت، نارسایی کلیه و شوک؛ عوامل خطر: جسم خارجی باقیمانده (تامپون، وسایل ضدبارداری بریر)، عفونت پوست و نسج نرم (آبسه، سلولیت، ماستیت)، واریسلا، سینوزیت، جراحی، تروما، زایمان، آنفلوانزا","تب بالا، افت فشار عمیق، راش ماکولار منتشر («سوختگی آفتاب بدون درد» که طی 3 روز محو و با پوسته‌ریزی تمام‌ضخامت دنبال می‌شود؛ 1 تا 2 هفته)، اختلال چندارگانی؛ اوایل: تب، لرز، ناخوشی، میالژی، سردرد، گلودرد، استفراغ، اسهال یا درد شکم","تعریف (جدول 88-1): تب ≥ 38.9°C، راش اریترودرمی منتشر، پوسته‌ریزی، SBP ≤ 90 (بزرگسال) و درگیری ≥ 3 سیستم (GI، عضلانی: میالژی یا CPK ≥ 2×، مخاطی: هیپرمی، کلیه: BUN/Cr ≥ 2× یا پیوری، کبدی: بیلی‌روبین/ALT/AST ≥ 2×، خونی: پلاکت < 100000، CNS: گیجی)؛ آزمایش منفی: کشت خون/CSF (ممکن است S. aureus مثبت)، سرولوژی RMSF، لپتوسپیروز، سرخک؛ محتمل: ≥ 4 معیار؛ قطعی: 5 معیار شامل پوسته‌ریزی","آزمایش: CBC، CMP، انعقاد، CPK، UA، CXR، ECG، گاز خون، کشت خون و منابع دیگر","افتراق: STSS، میونکروز کلستریدیال، TSS با C. sordellii، SSSS، سپسیس سایر باکتری‌ها، RMSF، لپتوسپیروز، منینگوکوکسمی، SJS/TEN، Kawasaki"],"ddx":[{"n":"Streptococcal toxic shock syndrome / necrotizing fasciitis |","cm":1},{"n":"Meningococcemia / sepsis |","cm":1},{"n":"Rocky Mountain spotted fever / leptospirosis |"},{"n":"Staphylococcal scalded skin syndrome / Stevens-Johnson syndrome |"},{"n":"Kawasaki disease |"}],"redflags":["افت فشار، اریترودرمی، اختلال چندارگانی، تامپون باقیمانده"],"guide":"واسطه: اگزوتوکسین‌های پیروژنیک؛ احیای تهاجمی شوک و درمان منبع: تخلیه آبسه، خارج کردن جسم خارجی (تامپون)، مشاوره جراحی برای دبریدمان و آنتی‌بیوتیک وسیع‌الطیف. 1) کریستالوئید تهاجمی (NS) و وازوپرسور در هیپوتانسیون پایدار. 2) MRSA مشکوک: vancomycin 15 mg/kg IV هر 12 ساعت (حداکثر 2.25 g) یا linezolid 600 mg IV + clindamycin 900 mg IV هر 8 ساعت. 3) MSSA مشکوک: nafcillin یا oxacillin 2 g IV هر 4 ساعت + clindamycin 900 mg IV هر 8 ساعت. 4) IVIG در صورت عدم بهبود پس از 6 ساعت درمان تهاجمی با مشاوره عفونی یا مراقبت ویژه.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 88: Toxic Shock Syndromes, pp. 480–483"},"streptococcal-toxic-shock":{"id":"streptococcal-toxic-shock","variants":[{"id":"stss-main","o":{"I":[{"t":"Chest radiograph; imaging for necrotizing soft tissue infection as indicated","fl":[{"k":"note","v":"not specified"}]}],"L":[{"t":"Blood and wound cultures before antibiotics when possible (majority have positive blood cultures); CBC, comprehensive metabolic panel, coagulation studies, creatine phosphokinase, urinalysis, blood gas"}],"S":[{"t":"Aggressive isotonic fluid resuscitation (large volumes of crystalloid, 10 to 20 L/day may be required)","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"A":[{"t":"Piperacillin-tazobactam 4.5 g IV or Meropenem 1 g IV plus IV Clindamycin 900 mg; add Vancomycin 15 mg/kg IV (maximum dose 2.25 g) when MRSA infection suspected"}],"T":[{"t":"Vasopressors or inotropic agents for persistent hypotension; assess airway (more than half develop ARDS and require intubation)"},{"t":"IV immunoglobulin controversial: obtain consultation before initiating"}],"Co":[{"t":"Emergent surgical consultation for suspected necrotizing soft tissue infection (debridement, fasciotomy or amputation); ICU"}]},"name":"Streptococcal toxic shock syndrome","level":"I","imp":"Streptococcal toxic shock syndrome (necrotizing soft tissue infection)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مردی ۵۵ ساله دیابتی با تب 40، درد شدید ران چپ نامتناسب با معاینه و فشار 75/45.","why":"STSS با فاشئیت نکروزان: احیای تهاجمی، آنتی‌بیوتیک و جراحی فوری."}],"ch":"88","name":"Streptococcal toxic shock syndrome","name_fa":"سندرم شوک توکسیک استرپتوکوکی","cc":["hypotension-shock","fever","wound-bite"],"keywords":"streptococcal toxic shock syndrome, STSS, group A Streptococcus, necrotizing fasciitis, piperacillin-tazobactam, meropenem, clindamycin, شوک استرپتوکوکی","status":"draft","features":["شوک و نارسایی چندارگانی از عفونت تهاجمی GAS (S. pyogenes) و سایر استرپتوکوک‌ها؛ عوامل خطر: بیماری قلب/کبد/کلیه، دیابت، الکل، سوءمصرف مواد، جراحی، تروما، زایمان، واریسلا، آنفلوانزا","مشابه TSS: علائم غیراختصاصی قبلی (تب، لرز، تعریق، ناخوشی، آرترالژی، سرفه، گلودرد، آبریزش، بی‌اشتهایی، تهوع، استفراغ، درد شکم، اسهال)؛ راش در اقلیت؛ درد موضعی نامتناسب با معاینه (اندام یا شکم): ارتباط قوی با عفونت نسج نرم نکروزان","تعریف (جدول 88-2): SBP ≤ 90 (یا < صدک 5 در کودک) و درگیری ≥ 2 سیستم: کلیه (Cr ≥ 2 mg/dL)، انعقاد (پلاکت ≤ 100000 یا DIC)، کبد، ARDS، پوست (راش اریتماتو)، نکروز نسج نرم (فاشئیت/میوزیت/گانگرن)؛ آزمایش: جداسازی GAS؛ محتمل: غیرسترون محل؛ قطعی: از محل استریل"],"ddx":[{"n":"Necrotizing fasciitis / myonecrosis |","cm":1},{"n":"Staphylococcal toxic shock syndrome |","cm":1},{"n":"Sepsis from other bacteria |"},{"n":"Meningococcemia |"}],"redflags":["درد نامتناسب با معاینه، افت فشار، ARDS، نکروز نسج نرم"],"guide":"مایع ایزوتونیک تهاجمی (ممکن است 10 تا 20 L/day لازم باشد) و وازوپرسور/اینوتروپ برای هیپوتانسیون پایدار؛ بیش از نیمی ARDS و نیاز به اینتوباسیون؛ کشت خون و زخم قبل از آنتی‌بیوتیک (اکثراً کشت خون مثبت). آنتی‌بیوتیک وسیع‌الطیف: piperacillin-tazobactam 4.5 g IV یا meropenem 1 g IV + clindamycin 900 mg IV؛ MRSA: vancomycin 15 mg/kg IV (حداکثر 2.25 g). IVIG جنجالی؛ مشاوره قبل. مشاوره اورژانس جراحی در شک فاشئیت نکروزان (دبریدمان، فاسیوتومی یا قطع عضو).","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 88: Toxic Shock Syndromes, pp. 480–483"},"sepsis-adult":{"id":"sepsis-adult","variants":[{"id":"sepsis-septic-shock","o":{"I":[{"t":"Chest radiograph (pneumonia source); additional radiographs, CT scans or ultrasound based on suspected source; lumbar puncture if meningitis suspected"}],"L":[{"t":"Lactic acid (repeat after 1 to 2 hours), CBC with differential and platelet count, serum electrolytes, liver function panel, renal function panel, arterial blood gas, blood cultures (before antibiotics but do not delay), urinalysis and urine culture; type and crossmatch for acute anemia or refractory hypotension; C-reactive protein and procalcitonin may be considered"}],"S":[{"t":"Initial bolus of crystalloid IV fluid 20 to 30 mL/kg","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"A":[{"t":"No obvious source (nonneutropenic adult): Imipenem 500 mg every 6 h to 1 g IV every 8 h, or Meropenem 1 g IV every 8 h, or Doripenem 500 mg IV every 8 h, or Ertapenem 1 g IV every 24 h, plus Vancomycin 15 mg/kg loading dose (some authorities recommend 25 to 30 mg/kg; Linezolid 600 mg IV if vancomycin allergy)"}],"T":[{"t":"Norepinephrine 0.5 to 30 µg/min with a goal mean arterial pressure of 65 mm Hg (central venous line preferred; large peripheral lines temporarily); consider Vasopressin 0.03 or 0.04 U/min as second-line agent"},{"t":"Remove suspected sources of infection: remove indwelling catheters if possible; incision and drainage of abscesses"}],"Co":[{"t":"ICU admission"}]},"name":"Septic shock","level":"I","imp":"Septic shock","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"O2 therapy: F.M 6–10 L/min to keep oxygen saturation > 90%; endotracheal intubation if necessary","sc":"مردی ۷۰ ساله با تب 39، تاکی‌کاردی 130، فشار 70/40، لاکتات 5 و منبع نامشخص.","why":"شوک سپتیک: مایع 30 mL/kg، norepinephrine و آنتی‌بیوتیک وسیع‌الطیف ظرف ساعت اول."},{"id":"sepsis-source-directed","o":{"I":[{"t":"Chest radiograph; CT / ultrasound as per suspected source"}],"L":[{"t":"Lactic acid, CBC, electrolytes, liver function panel, renal function panel, arterial blood gas, blood cultures, urinalysis and urine culture"}],"S":[{"t":"Crystalloid 20 to 30 mL/kg initial bolus","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"A":[{"t":"Pneumonia: Ceftriaxone 1–2 g IV every 12 h plus Azithromycin 500 mg IV then 250 mg IV every 24 h plus Levofloxacin 750 mg IV every 24 h (or Moxifloxacin 400 mg IV every 24 h) plus Vancomycin 15 mg/kg loading dose"},{"t":"Biliary source: Ampicillin/sulbactam 3 g IV every 6 h, or Piperacillin/tazobactam 4.5 g IV every 6 h, or Ticarcillin/clavulanate 3.1 g IV every 4 h"},{"t":"Intra-abdominal source: Imipenem, Meropenem 1 g IV every 8 h, Doripenem 500 mg IV every 8 h, Ertapenem 1 g IV every 24 h, Ampicillin/sulbactam 3 g IV every 6 h or Piperacillin/tazobactam 4.5 g IV every 6 h"},{"t":"Urinary source (hospitalized pyelonephritis): Levofloxacin 750 mg IV every 24 h, or Piperacillin/tazobactam 4.5 g IV every 6 h, or Ceftriaxone 1–2 g IV every 12–24 h, or Ampicillin 1–2 g IV every 4–6 h plus Gentamicin 1.0–1.5 mg/kg every 8 h","fl":[{"k":"renal","v":"aminoglycoside"}]},{"t":"Petechial rash (N. meningitidis, RMSF): Ceftriaxone 2 g IV every 12 h or Cefotaxime 2 g IV every 4-6 h; consider adding Doxycycline 100 mg IV every 12 h for possible RMSF"},{"t":"Suspected illicit IV drug use: Vancomycin 15 mg/kg loading dose"}],"T":[{"t":"Remove indwelling catheters; incision and drainage of abscess; Metronidazole 15 mg/kg IV load then 7.5 mg/kg every 8 h or Clindamycin 600–900 mg IV every 8 h for anaerobic sources"}],"Co":[{"t":"Admit"}]},"name":"Sepsis with a defined source (pneumonia, biliary, intra-abdominal, urinary, petechial rash, IV drug use)","level":"II","imp":"Sepsis with identified source","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: F.M 6–10 L/min or N.C 3–5 L/min to keep oxygen saturation > 90%","sc":"زنی ۶۵ ساله با تب، تاکی‌پنه و انفیلتره لوب تحتانی راست؛ فشار 95/55 و لاکتات 3.","why":"سپسیس شدید: آنتی‌بیوتیک منطبق بر منبع و مایع."},{"id":"sepsis-neutropenic-special-host","o":{"L":[{"t":"CBC with differential, lactate, blood cultures, urinalysis and urine culture, chest radiograph"}],"S":[{"t":"Crystalloid 20 to 30 mL/kg","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"A":[{"t":"Neutropenic adults: Ceftazidime 2 g IV every 8 h, or Cefepime 2 g IV every 8 h, or Imipenem 500 mg IV every 6 h to 1 g IV every 8 h, or Meropenem 1 g IV every 8 h, or Piperacillin/tazobactam 4.5 g IV every 6 h; plus Levofloxacin 750 mg IV every 24 h or Moxifloxacin 400 mg IV every 24 h; plus Vancomycin 15 mg/kg loading dose; consider Fluconazole 400 mg IV every 24 h or Micafungin 100 mg every 24 h"},{"t":"Indwelling vascular devices: Vancomycin 15 mg/kg loading dose; Legionella potential: add Azithromycin 500 mg IV then 250 mg IV every 24 h or Erythromycin 800 mg IV every 6 h; asplenic: Ceftriaxone 1 g IV every 24 h up to 2 g IV every 12 h if meningitis"}],"T":[{"t":"Norepinephrine 0.5 to 30 µg/min (MAP goal 65 mm Hg) if hypotension unresponsive to fluid"}],"Co":[{"t":"ICU admission; oncology"}]},"name":"Sepsis in a neutropenic patient or special host (indwelling devices, asplenia, Legionella risk)","level":"I","imp":"Sepsis in neutropenic / special host","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: F.M 6–10 L/min or N.C 3–5 L/min to keep oxygen saturation > 90%","sc":"مرد ۵۰ ساله پس از شیمی‌درمانی با تب 39.5، ANC 200 و فشار 85/50.","why":"نوتروپنیک: پوشش ضد-Pseudomonas و در صورت لزوم ضدقارچ."}],"ch":"89","name":"Sepsis, severe sepsis and septic shock","name_fa":"سپسیس، سپسیس شدید و شوک سپتیک","cc":["hypotension-shock","fever","altered-mental-status"],"keywords":"sepsis, severe sepsis, septic shock, SIRS, lactate, norepinephrine, vasopressin, empiric antibiotics, 30 mL/kg, meropenem, vancomycin, سپسیس, شوک سپتیک","status":"draft","features":["سپسیس: عفونت مشکوک/تأییدشده با شواهد التهاب سیستمیک؛ سپسیس شدید: همراه اختلال عضوی جدید از هیپوپرفیوژن؛ شوک سپتیک: نارسایی قلبی-عروقی (هیپوتانسیون پایدار یا نیاز به وازوپرسور با وجود احیای کافی مایع)","بیشتر باکتری گرم‌منفی و گرم‌مثبت؛ هر میکروارگانیسم (قارچ، مایکوباکتریوم، ویروس، ریکتزیا، تک‌یاخته)؛ شایع‌ترین منابع: پنومونی، شکمی، ادراری، پوست/نسج نرم","علائم: هیپر/هیپوترمی، تاکی‌کاردی، هیپوتانسیون، تاکی‌پنه؛ تا 40٪ هیپوتانسیون نامشخص بعداً شوک سپتیک تشخیص داده می‌شوند","سنتی: شوک توزیعی با وازودیلاتاسیون و اندام گرم؛ ولی «cold shock» نیز دیده می‌شود (کاهش حجم و کاردیومیوپاتی سپتیک)","اختلال عضو: ARDS (علت اصلی)؛ کلیه: AKI، الیگوری، آنوری؛ کبد: یرقان کلستاتیک؛ خون: نوتروپنی/نوتروفیلی، ترومبوسیتوپنی، DIC؛ هیپرگلیسمی کنترل‌نشده خطر","پوست (5 دسته): عفونت مستقیم، seeding هماتوژن (پتشی، پوستول، ecthyma gangrenosum)، هیپوتانسیون/DIC (acrocyanosis، نکروز)، آمبولی/واسکولیت، سموم (TSS)","SIRS (جدول 89-1): دما > 38.3 یا < 36؛ نبض > 90؛ تاکی‌پنه RR > 20؛ WBC > 12000 یا < 4000 یا > 10٪ فرم نارس؛ سپسیس شدید: هیپوتانسیون، لاکتات بالا، اختلال کلیه، هیپوکسی، هیپربیلی‌روبینمی، ترومبوسیتوپنی یا کواگولوپاتی؛ شوک سپتیک: هیپوتانسیون مقاوم به حداقل 1.5 تا 3 L کریستالوئید (20 تا 30 mL/kg در کودکان)","آزمایش: CBC با دیفرانسیل و پلاکت، لاکتات، الکترولیت، LFT، عملکرد کلیه، ABG، کشت خون، UA و کشت ادرار؛ type and crossmatch در آنمی حاد یا هیپوتانسیون مقاوم؛ CXR؛ CT، سونوگرافی، LP بر اساس شک؛ CRP و procalcitonin"],"ddx":[{"n":"Septic shock from an undrained source |","cm":1},{"n":"Meningococcemia / toxic shock syndrome |","cm":1},{"n":"Hemorrhagic / cardiogenic / anaphylactic shock |","cm":1},{"n":"Adrenal crisis / pulmonary embolism |"},{"n":"Drug overdose / DKA |"}],"redflags":["فشار پایین، لاکتات بالا، تغییر هوشیاری، اولیگوری، پتشی"],"guide":"ستون‌های درمان: شناخت زودهنگام، برگرداندن زودهنگام اختلال همودینامیک و آنتی‌بیوتیک تجربی زودهنگام؛ هدف: بهبود پیش‌بار، پرفیوژن و اکسیژن‌رسانی. 1) اکسیژن برای SpO2 > 90٪ و اینتوباسیون در صورت لزوم. 2) بولوس کریستالوئید 20 تا 30 mL/kg. 3) وازوپرسور در شوک مقاوم به مایع: norepinephrine 0.5 تا 30 µg/min با هدف MAP 65؛ vasopressin 0.03 یا 0.04 U/min لاین دوم؛ CVC ترجیح و لاین بزرگ محیطی موقتاً. 4) لاکتات مجدد بعد از 1 تا 2 ساعت. 5) آنتی‌بیوتیک وسیع‌الطیف بر اساس منبع (جدول 89-2) ترجیحاً بعد از کشت ولی بدون تأخیر. 6) برداشتن منبع: کاتتر قابل خروج، I&D آبسه.\n# آنتی‌بیوتیک بر اساس میزبان (جدول 89-2)\n- بزرگسال غیرنوتروپنیک بدون منبع واضح: imipenem 500 mg هر 6 ساعت تا 1 g هر 8 ساعت، یا meropenem 1 g IV هر 8 ساعت، یا doripenem 500 mg هر 8 ساعت، یا ertapenem 1 g هر 24 ساعت + vancomycin بار 15 mg/kg.\n- صفراوی: ampicillin/sulbactam 3 g هر 6 ساعت، piperacillin/tazobactam 4.5 g هر 6 ساعت یا ticarcillin/clavulanate 3.1 g هر 4 ساعت.\n- پنومونی: ceftriaxone 1–2 g هر 12 ساعت + azithromycin 500 mg IV سپس 250 mg هر 24 ساعت + levofloxacin 750 mg هر 24 ساعت یا moxifloxacin 400 mg هر 24 ساعت + vancomycin بار 15 mg/kg.\n- مصرف IV مواد: vancomycin بار 15 mg/kg.\n- راش پتشیال (N. meningitidis، RMSF): ceftriaxone 2 g IV هر 12 ساعت یا cefotaxime 2 g هر 4–6 ساعت؛ افزودن doxycycline 100 mg IV هر 12 ساعت برای RMSF.\n- شکمی: imipenem، meropenem، doripenem، ertapenem، ampicillin/sulbactam یا piperacillin/tazobactam مثل بالا.\n- ادراری (پیلونفریت بستری): levofloxacin 750 mg، moxifloxacin 400 mg، piperacillin/tazobactam 4.5 g هر 6 ساعت، ceftriaxone 1–2 g هر 12–24 ساعت یا ampicillin 1–2 g هر 4–6 ساعت + gentamicin 1.0–1.5 mg/kg هر 8 ساعت (یا بار 2 mg/kg سپس 1.7 mg/kg هر 8 ساعت).\n- ادراری عارضه‌دار/کاتتر: piperacillin/tazobactam، imipenem، meropenem، doripenem یا ampicillin + gentamicin.\n- نوتروپنیک: ceftazidime 2 g هر 8 ساعت یا cefepime 2 g هر 8 ساعت یا imipenem یا meropenem یا piperacillin/tazobactam 4.5 g هر 6 ساعت + levofloxacin 750 mg یا moxifloxacin 400 mg + vancomycin بار 15 mg/kg؛ و fluconazole 400 mg IV هر 24 ساعت یا micafungin 100 mg هر 24 ساعت.\n- بی‌هوازی: metronidazole 15 mg/kg IV بار سپس 7.5 mg/kg هر 8 ساعت یا clindamycin 600–900 mg هر 8 ساعت.\n- دستگاه عروقی دائم: vancomycin؛ Legionella: azithromycin یا erythromycin 800 mg هر 6 ساعت؛ آسپلنی: ceftriaxone 1 g هر 24 ساعت تا 2 g هر 12 ساعت در مننژیت.\n- یادداشت: MRSA کولونیزاسیون بالا؛ vancomycin بار 25 تا 30 mg/kg توسط برخی پیشنهاد؛ آلرژی: linezolid 600 mg IV.","pearls":["هر هیپوتانسیون نامشخص را شوک سپتیک مشکوک بدان تا خلاف آن ثابت شود (40٪)."],"section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 89: Sepsis, pp. 484–490"},"cellulitis-erysipelas":{"id":"cellulitis-erysipelas","variants":[{"id":"cellulitis-outpatient","o":{"I":[{"t":"Bedside ultrasound for occult abscess / DVT consideration if clinical uncertainty"}],"A":[{"t":"Cephalexin 500 mg PO four times daily, or Dicloxacillin 500 mg PO four times daily, or Clindamycin 300 mg PO four times daily"},{"t":"When local epidemiology supports a high likelihood of MRSA: Clindamycin 300 mg PO four times daily, or Trimethoprim/sulfamethoxazole double strength two tablets twice a day for 7 to 10 days (consider adding Cephalexin 500 mg four times daily to cover Streptococcus)"}],"T":[{"t":"Skin markers to mark the extent of cellulitis for serial evaluation"}],"Co":[{"t":"Follow-up within a few days"}]},"name":"Uncomplicated cellulitis / erysipelas (outpatient)","level":"III","imp":"Cellulitis / erysipelas","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۴۰ ساله با قرمزی، گرمی و تندرنس ساق بدون تب یا ضعف.","why":"بدون عارضه: آنتی‌بیوتیک خوراکی؛ پیگیری چند روزه."},{"id":"cellulitis-inpatient","o":{"I":[{"t":"Bedside ultrasound for occult abscess"}],"L":[{"t":"Blood cultures and cultures of other suspected areas of infection (systemic toxicity)"}],"A":[{"t":"Clindamycin 600 to 900 mg IV every 8 hours, or Cefazolin 1 to 2 g IV every 8 hours, or Nafcillin 1 to 2 g IV every 4 hours"},{"t":"Severe MRSA-suspected infection: Vancomycin 1 g IV every 12 hours"}],"T":[{"t":"Tetanus prophylaxis as indicated","fl":[{"k":"note","v":"see Chapter 94"}]}],"Co":[{"t":"Admit; surgery if bullae, crepitus, pain out of proportion"}]},"name":"Cellulitis with systemic toxicity or bacteremia (admission)","level":"II","imp":"Cellulitis with systemic toxicity","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۶۰ ساله دیابتی با سلولیت وسیع ساق، تب 39 و لنفانژیت.","why":"سمیت سیستمیک/دیابت: بستری و آنتی‌بیوتیک وریدی؛ رد آبسه و نکروزان."}],"ch":"90","name":"Cellulitis and erysipelas","name_fa":"سلولیت و اریزیپل","cc":["rash","wound-bite","fever"],"keywords":"cellulitis, erysipelas, cephalexin, dicloxacillin, clindamycin, cefazolin, nafcillin, lymphangitis, سلولیت, اریزیپل","status":"draft","features":["سلولیت: واکنش التهابی موضعی نسج نرم به تهاجم باکتریال پوست؛ شایع‌تر در سالمند، ایمنوساپرس و بیماری عروق محیطی؛ تندرنس، اریتم و ایندوراسیون موضعی؛ لنفانژیت/لنفادنیت = عفونت شدیدتر؛ تب و لرز ممکن","تشخیص بالینی؛ WBC و کشت خون به‌ندرت تغییر مدیریت می‌دهند؛ سلولیت اندام تحتانی می‌تواند DVT را تقلید کند یا با آن همراه شود؛ سمیت سیستمیک: سونوگرافی بالین/کشت برای آبسه مخفی","اریزیپل: سلولیت سطحی با درگیری لنفاتیک؛ عامل اصلی GAS؛ پورتال ورود؛ شروع حاد: تب بالا، لرز، ناخوشی، تهوع؛ ظرف 1 تا 2 روز اریتم کوچک سوزشی تیز مرزبندی‌شده، سفت و دردناک؛ لنفانژیت/لنفادنیت شایع","مشاوره جراحی: بول، کرپیتوس، درد نامتناسب یا اریتم سریع‌الگسترش با سمیت (فاشئیت نکروزان)؛ راهنماها درمان سلولیت غیرچرکی و اریزیپل را متمایز نمی‌کنند"],"ddx":[{"n":"Necrotizing soft tissue infection |","cm":1},{"n":"Deep venous thrombosis |","cm":1},{"n":"Abscess |"},{"n":"Contact dermatitis / stasis dermatitis |"},{"n":"Septic arthritis / osteomyelitis |"}],"redflags":["درد نامتناسب، بول، کرپیتوس، تاکی‌کاردی/سمیت سیستمیک، باکتریمی"],"guide":"بدون عارضه و بدون شک MRSA: cephalexin 500 mg PO چهار بار روزانه، dicloxacillin 500 mg PO چهار بار روزانه یا clindamycin 300 mg PO چهار بار روزانه. اگر اپیدمیولوژی MRSA بالا: داروهای مؤثر بر MRSA (clindamycin 300 mg PO چهار بار روزانه یا TMP/SMX DS دو قرص دو بار روزانه 7 تا 10 روز؛ افزودن cephalexin 500 mg چهار بار روزانه برای استرپتوکوک با TMP/SMX؛ شدید: vancomycin 1 g IV هر 12 ساعت). پیگیری ظرف چند روز؛ علامت‌گذاری پوست برای ارزیابی. بستری: سمیت سیستمیک یا باکتریمی؛ دیابت، الکل یا ایمنوساپرسیون؛ بستری: clindamycin 600 تا 900 mg IV هر 8 ساعت، cefazolin 1 تا 2 g IV هر 8 ساعت یا nafcillin 1 تا 2 g IV هر 4 ساعت.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 90: Soft Tissue Infections, pp. 491–496"},"abscess-mrsa-skin":{"id":"abscess-mrsa-skin","variants":[{"id":"abscess-simple-id","o":{"I":[{"t":"Bedside ultrasound when exam is equivocal (abscess vs cellulitis)"}],"T":[{"t":"Incision and drainage","fl":[{"k":"note","v":"local anesthesia agent per procedure; no routine antibiotics in healthy immunocompetent patients"}]},{"t":"Bartholin abscess: incision and drainage along the vaginal mucosal surface followed by Word catheter (up to 4 weeks), sitz baths after 2 days"},{"t":"Infected epidermoid/pilar cyst or pilonidal abscess: simple incision and drainage with recheck in 2 to 3 days (capsule excision later)"},{"t":"Folliculitis: warm compresses or topical antibiotics such as Bacitracin"}],"Co":[{"t":"Wound recheck as above; surgical referral for hidradenitis suppurativa (recurrent) or pilonidal definitive treatment; gynecology follow-up within 2 days (severe) or 1 week (mild) for Bartholin abscess"}]},"name":"Simple cutaneous abscess (incision and drainage)","level":"III","imp":"Cutaneous abscess","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله سالم با آبسه فلوکتوان ۳ cm روی باسن؛ بدون سلولیت وسیع یا تب.","why":"I&D کافی است؛ آنتی‌بیوتیک فقط با سلولیت، ایمنوساپرس یا بیماری شدید."},{"id":"abscess-mrsa-antibiotic","o":{"I":[{"t":"Bedside ultrasound for abscess collections"}],"A":[{"t":"Clindamycin 300 mg PO four times daily, or Trimethoprim/sulfamethoxazole double strength two tablets twice a day for 7 to 10 days; consider adding Cephalexin 500 mg four times daily to cover Streptococcus when using TMP/SMX"},{"t":"Severe infections: Vancomycin 1 g IV every 12 hours with inpatient admission"}],"T":[{"t":"Incision and drainage of the abscess"}],"Co":[{"t":"Admission for extremes of age, systemic signs of severe illness, significant comorbidities or large complicated lesions; surgical consultation as indicated"}]},"name":"MRSA abscess with cellulitis / immunocompromised / systemic illness","level":"II","imp":"Community-acquired MRSA skin and soft tissue infection","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۴۵ ساله دیابتی با آبسه و سلولیت وسیع و تب 38.5.","why":"ایمنوساپرس یا سلولیت اطراف: آنتی‌بیوتیک مؤثر بر MRSA؛ شدید: بستری و vancomycin."}],"ch":"90","name":"Cutaneous abscess and community-acquired MRSA skin infection","name_fa":"آبسه جلدی و عفونت پوستی MRSA اکتسابی از جامعه","cc":["wound-bite","rash"],"keywords":"skin abscess, incision and drainage, MRSA, hidradenitis suppurativa, epidermoid cyst, pilonidal abscess, Bartholin abscess, folliculitis, آبسه پوستی, MRSA","status":"draft","features":["MRSA اکتسابی از جامعه: ضایعات پوستی گرم، قرمز، دردناک، اغلب با آبسه (ممکن است خودبه‌خود تخلیه شود)؛ اغلب با گزش عنکبوت اشتباه می‌شود؛ تشخیص بالینی؛ سونوگرافی بالین برای آبسه در معاینه مبهم","آبسه پوستی: شکست سد پوستی و عفونت کانونی فلور ساکن؛ تورم، تندرنس، اریتم، اغلب فلوکتوان؛ ممکن است در ایمنوساپرس سمیت سیستمیک؛ دنبال جسم خارجی یا آسیب مستعدکننده بگرد؛ آسپیراسیون سوزنی/سونوگرافی برای افتراق از سلولیت","بارتولن: تورم یک‌طرفه دردناک لابیا با توده فلوکتوان 1 تا 2 cm","هیدرادنیت چرکی: عفونت مزمن راجعه غدد آپوکرین (زیربغل و کشاله)","کیست اپیدرموئید و pilar عفونی: ندول اریتماتو، دردناک و اغلب فلوکتوان؛ کپسول باید برداشته شود؛ آبسه پیلونیدال: توده تندر و فلوکتوان در شیار باسن فوقانی","فولیکولیت: ضایعات خارش‌دار اریتماتو < 5 mm با پوستول مرکزی؛ S. aureus"],"ddx":[{"n":"Necrotizing soft tissue infection |","cm":1},{"n":"Systemic toxicity in immunosuppressed patient |","cm":1},{"n":"Spider bite (misdiagnosis) |"},{"n":"Cellulitis |"},{"n":"Foreign body |"}],"redflags":["ایمنوساپرس، سمیت سیستمیک، سلولیت وسیع اطراف"],"guide":"اغلب فقط I&D کافی است؛ در افراد سالم بدون سلولیت اطراف یا بیماری شدید آنتی‌بیوتیک روتین لازم نیست. ایمنوساپرس، سیستمیک، سلولیت اطراف: داروی مؤثر بر MRSA: clindamycin 300 mg PO چهار بار روزانه یا TMP/SMX DS دو قرص دو بار روزانه 7 تا 10 روز (± cephalexin 500 mg چهار بار روزانه)؛ شدید: vancomycin 1 g IV هر 12 ساعت و بستری. بارتولن: I&D در سطح مخاط واژن و Word catheter (تا 4 هفته)؛ سیتز بعد از 2 روز؛ پیگیری زنان ≤ 2 روز (شدید) یا 1 هفته (خفیف)؛ آنتی‌بیوتیک روتین نه مگر شک STD. هیدرادنیت: I&D حاد؛ راجعه: جراح. کیست عفونی: I&D و چک 2 تا 3 روز؛ برداشتن کپسول بعداً. پیلونیدال: I&D، چک 2 تا 3 روز و ارجاع جراحی. فولیکولیت: کمپرس گرم یا آنتی‌بیوتیک موضعی (bacitracin)؛ دردناک یا وسیع: cephalexin، dicloxacillin یا azithromycin خوراکی.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 90: Soft Tissue Infections, pp. 491–496"},"necrotizing-soft-tissue-infection":{"id":"necrotizing-soft-tissue-infection","variants":[{"id":"nstis-main","o":{"I":[{"t":"Plain radiographs for gas within soft tissue (CT/imaging as indicated)","fl":[{"k":"note","v":"do not delay surgical consultation"}]}],"L":[{"t":"CBC, metabolic panel (metabolic acidosis, hyponatremia), coagulation studies, myoglobinuria / CK, renal and hepatic function"}],"S":[{"t":"Aggressive resuscitation with crystalloid IV fluids ; consider PRBC if significant anemia from hemolysis","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"A":[{"t":"Vancomycin 1 g IV every 12 hours plus Meropenem 500 to 1000 mg IV every 8 hours; alternatively Piperacillin/tazobactam 4.5 g IV every 6 hours; consider adding Clindamycin (inhibits toxin synthesis)"}],"T":[{"t":"Tetanus prophylaxis as indicated (see Chapter 94)"},{"t":"Hyperbaric oxygen or IV immunoglobulin controversial (consider with surgical colleagues)"}],"Co":[{"t":"Surgical consultation as soon as possible (debridement, fasciotomy, amputation); ICU"}]},"name":"Suspected necrotizing soft tissue infection","level":"I","imp":"Necrotizing soft tissue infection","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مردی ۵۸ ساله دیابتی با درد شدید ران، بول، کرپیتوس، تب 38.2، تاکی‌کاردی 130 و گیجی.","why":"تأخیر کشنده است؛ آنتی‌بیوتیک وسیع‌الطیف و جراحی فوری."}],"ch":"90","name":"Necrotizing soft tissue infection (necrotizing fasciitis, gas gangrene)","name_fa":"عفونت نسج نرم نکروزان (فاشئیت نکروزان، گانگرن گازی)","cc":["wound-bite","fever","rash"],"keywords":"necrotizing fasciitis, necrotizing soft tissue infection, gas gangrene, Clostridium, pain out of proportion, vancomycin, meropenem, clindamycin, فاشئیت نکروزان","status":"draft","features":["عفونت تهاجمی و تهدیدکننده حیات؛ شروع موذی و علائم اولیه ممکن است فریبنده خوش‌خیم باشد؛ طیف پلی‌میکروبیال یا مونومیکروبیال (GAS و S. aureus)؛ کلستریدیال اکنون نادر","درد نامتناسب با معاینه و احساس سنگینی؛ ادم، تغییر رنگ قهوه‌ای، بول، ترشح سروزی-خونی بدبو، کرپیتوس؛ تب خفیف و تاکی‌کاردی نامتناسب با تب؛ تغییر هوشیاری (دلیریوم، تحریک‌پذیری) = سمیت سیستمیک","یافته‌های مکمل: گاز در نسج نرم در رادیوگرافی ساده، اسیدوز متابولیک، کواگولوپاتی، هیپوناترمی، لکوسیتوز، آنمی، ترومبوسیتوپنی، میوگلوبینوری، اختلال کلیه/کبد"],"ddx":[{"n":"Necrotizing fasciitis / myonecrosis |","cm":1},{"n":"Toxic shock syndrome |","cm":1},{"n":"Cellulitis / erysipelas |"},{"n":"Deep venous thrombosis / compartment syndrome |"}],"redflags":["درد نامتناسب، کرپیتوس، بول، افت فشار، تغییر هوشیاری"],"guide":"IV آنتی‌بیوتیک در اسرع وقت: vancomycin 1 g IV هر 12 ساعت + meropenem 500 تا 1000 mg IV هر 8 ساعت؛ یا piperacillin/tazobactam 4.5 g IV هر 6 ساعت؛ clindamycin مهارکننده سنتز توکسین. احیای تهاجمی با کریستالوئید؛ PRBC در آنمی قابل‌توجه ناشی از همولیز؛ شوک سپتیک سریع؛ اگر اندام با پرفیوژن مختل و هیپوتانسیون: مشکل استفاده از وازوکانستریکتور. کزاز پروفیلاکسی بر اساس اندیکاسیون (فصل ۹۴). مشاوره فوری جراحی: دبریدمان، فاسیوتومی یا قطع عضو؛ هایپرباریک و IVIG جنجالی.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 90: Soft Tissue Infections, pp. 491–496"},"sporotrichosis":{"id":"sporotrichosis","variants":[{"id":"sporotrichosis-main","o":{"A":[{"t":"Itraconazole 100 to 200 mg/d PO for 3 to 6 months"},{"t":"Systemic symptoms or disseminated disease: Amphotericin B 0.5 mg/kg/d (admit)"}],"Co":[{"t":"Outpatient for most cutaneous cases; admit if systemic/disseminated"}]},"name":"Sporotrichosis","level":"III","imp":"Sporotrichosis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"باغبانی ۴۵ ساله با ندول‌های متوالی و مهاجر در امتداد ساعد پس از فرو رفتن خار.","why":"فرم لنفوکوتانئوس شایع‌ترین؛ itraconazole طولانی‌مدت."}],"ch":"90","name":"Sporotrichosis","name_fa":"اسپوروتریکوز","cc":["wound-bite","rash"],"keywords":"sporotrichosis, Sporothrix schenckii, itraconazole, amphotericin B, lymphocutaneous, اسپوروتریکوز","status":"draft","features":["عفونت قارچی Sporothrix schenckii پس از تلقیح تروماتیک (گیاه، خاک)؛ پس از نهفتگی 3 هفته: سه نوع: ثابت (زخم پوسته‌دار یا پلاک verrucous در محل)، موضعی (ندول/پوستول با اریتم)، لنفوکوتانئوس شایع‌ترین (ندول بی‌درد با ندول‌های زیرجلدی مهاجر در مسیر لنفاتیک)","تشخیص بالینی؛ کشت بیوپسی ارزش حاد محدود؛ افتراق: سل، تولارمی، cat-scratch، لیشمانیوز، نوکاردیوز، لنفانژیت استافیلوکوکی"],"ddx":[{"n":"Disseminated sporotrichosis |","cm":1},{"n":"Tuberculosis / tularemia |"},{"n":"Cat-scratch disease / leishmaniasis |"},{"n":"Nocardiosis / staphylococcal lymphangitis |"}],"redflags":["علائم سیستمیک، بیماری منتشر"],"guide":"itraconazole 100 تا 200 mg/d PO به مدت 3 تا 6 ماه برای موضعی یا سیستمیک بسیار مؤثر؛ اکثر موارد سرپایی؛ علامت‌دار سیستمیک یا منتشر: بستری و amphotericin B 0.5 mg/kg/d.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 90: Soft Tissue Infections, pp. 491–496"},"influenza":{"id":"influenza","variants":[{"id":"influenza-outpatient","o":{"L":[{"t":"Rapid antigen assay or molecular test only if high risk for complications within 5 days of symptom onset, or immunocompromised; no testing once influenza documented in the community for otherwise healthy outpatients"}],"T":[{"t":"Symptomatic care","fl":[{"k":"ci","v":"avoid aspirin (Reye syndrome)"}]},{"t":"Neuraminidase inhibitor if higher risk for complications (benefit limited to treatment within 48 hours): Oseltamivir 75 mg PO twice daily for 5 days","fl":[{"k":"ci","v":"avoid zanamivir in underlying pulmonary disease (bronchospasm)"}]}]},"name":"Influenza, uncomplicated","level":"III","imp":"Influenza","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله سالم با تب ناگهانی 39، میالژی و سرفه در فصل آنفلوانزا.","why":"اکثر سالم‌ها درمان علامتی؛ ضدویروس فقط پرخطر یا شدید."},{"id":"influenza-severe","o":{"I":[{"t":"Chest radiograph"}],"L":[{"t":"Molecular diagnostic test (more sensitive than rapid antigen); CBC, blood cultures as per pneumonia","fl":[{"k":"note","v":"per Chapter 30"}]}],"S":[{"t":"IV fluids","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"A":[{"t":"Oseltamivir 75 mg PO twice daily for 5 days (uncomplicated dosing), or Peramivir 600 mg IV"},{"t":"Secondary pneumonia: antibiotics that cover methicillin-resistant S. aureus","fl":[{"k":"note","v":"drug and dose not given in this chapter; see Chapter 30"}]}],"Co":[{"t":"Admit; ICU if respiratory failure"}]},"name":"Severe or complicated influenza (admission)","level":"II","imp":"Severe influenza / influenza pneumonia","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","o2":"O2 therapy: F.M 6–10 L/min or N.C 3–5 L/min if SpO2 < 94% (or COPD < 92%)","sc":"زنی ۷۰ ساله با COPD، تب، تنگی نفس و انفیلتره ریوی در فصل آنفلوانزا.","why":"شدید/پرخطر: مهارکننده نورآمینیداز و پوشش MRSA در پنومونی ثانویه."}],"ch":"91","name":"Influenza","name_fa":"آنفلوانزا","cc":["fever","cough-hemoptysis"],"keywords":"influenza, flu, oseltamivir, zanamivir, peramivir, neuraminidase inhibitor, rapid antigen, آنفلوانزا","status":"draft","features":["اوج فعالیت در مناطق معتدل اواخر دسامبر تا اوایل مارس؛ انتقال قطره/آئروسل یا تماس مستقیم؛ نهفتگی 1 تا 4 روز؛ دفع ویروس از 24 ساعت قبل علائم","شروع ناگهانی: تب با لرز، سردرد، میالژی و ناخوشی؛ سرفه، آبریزش، گلودرد، غدد گردنی حساس؛ سالمند ممکن است فقط تب، ناخوشی، گیجی و/یا احتقان بینی؛ تقریباً 50٪ کودکان علائم GI؛ تب 2 تا 4 روز؛ بهبود 3 تا 7 روز؛ سرفه و ناخوشی تا هفته‌ها","عوارض تنفسی: پنومونیت اولیه، پنومونی باکتریال ثانویه، کروپ، تشدید COPD؛ از آسپیرین پرهیز (Reye)؛ نادر: GBS، میوکاردیت، پریکاردیت","تشخیص بالینی در همه‌گیری؛ تست سریع آنتی‌ژن (15 دقیقه) حساسیت 10٪ تا 80٪ و ویژگی 90٪ تا 95٪؛ تست‌های مولکولی حساس‌تر و اختصاصی‌تر؛ آزمایش در فصل آنفلوانزا برای افراد ایمن پرخطر در 5 روز اول و ایمنوساپرس بدون توجه به زمان؛ پس از اثبات در جامعه برای بیمار سرپایی سالم لازم نیست"],"ddx":[{"n":"Pneumonia (primary influenza / secondary bacterial) |","cm":1},{"n":"Sepsis / meningitis |","cm":1},{"n":"Other viral respiratory infection (COVID-like, RSV) |"},{"n":"Myocarditis / exacerbation of COPD |"}],"redflags":["تنگی نفس، هیپوکسی، تشدید بیماری زمینه‌ای، تغییر هوشیاری"],"guide":"اکثر سالم‌ها خودمحدود: درمان علامتی سرپایی. شدید یا همراه بیماری زمینه‌ای: بستری با مایع وریدی، حمایت تنفس، مهارکننده نورآمینیداز و گاهی وازوپرسور. پنومونی ثانویه: آنتی‌بیوتیک پوشش‌دهنده MRSA. مهارکننده نورآمینیداز برای مشکوک بستری، شدید/عارضه‌دار/پیشرونده یا پرخطر؛ در سالم بحث؛ فایده احتمالاً فقط ظرف 48 ساعت از شروع علائم. oseltamivir 75 mg PO دو بار روزانه 5 روز؛ zanamivir استنشاقی (برونکواسپاسم؛ در بیماری ریوی پرهیز)؛ peramivir 600 mg IV تنها داروی وریدی تأییدشده.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 91: Serious Viral Infections, pp. 497–504"},"herpes-simplex-virus":{"id":"herpes-simplex-virus","variants":[{"id":"hsv-mucocutaneous","o":{"L":[{"t":"Viral culture from an unroofed vesicle, or PCR / direct fluorescent antibody on swabbed tissue (Tzanck test generally not useful)"}],"A":[{"t":"Acyclovir 400 mg PO three times a day, or Valacyclovir 1000 mg every 12 hours, or Famciclovir 250 mg three times a day for 7 to 10 days (most effective within 48 to 72 hours)"},{"t":"Recurrent: Acyclovir 400 mg three times a day for 5 days; Valacyclovir 2000 mg every 12 hours for 1 day (labialis) or 500 mg every 12 hours for 3 days (genital); Famciclovir 1500 mg single dose (orolabial) or 1000 mg single dose (genital); topical 5% acyclovir ointment six times per day for 7 days for less severe outbreaks"}]},"name":"Mild to moderate HSV (mucocutaneous), immunocompetent","level":"III","imp":"Herpes simplex virus infection (mucocutaneous)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۸ ساله با وزیکول لب و گزگز از ۲ روز پیش.","why":"شروع زودهنگام ضدویروس خوراکی؛ آزمایش فقط در شک."},{"id":"hsv-encephalitis","o":{"I":[{"t":"CT scan or MRI (temporal lobe lesions)"}],"L":[{"t":"Lumbar puncture: CSF lymphocytic pleocytosis and/or erythrocytosis; PCR of cerebrospinal fluid for HSV (testing modality of choice)"}],"A":[{"t":"Acyclovir 10 mg/kg IV every 8 hours (immunocompromised with severe mucocutaneous involvement: 5 mg/kg IV every 8 hours based on ideal body weight)"}],"Co":[{"t":"Admit; neurology / infectious disease"}]},"name":"Suspected HSV encephalitis / disseminated HSV","level":"I","imp":"Suspected HSV encephalitis (or disseminated HSV)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۳۵ ساله با تب، سردرد، رفتار عجیب و تشنج.","why":"مرگ > 70٪ بدون درمان؛ acyclovir را بدون انتظار PCR شروع کن."}],"ch":"91","name":"Herpes simplex virus infection (mucocutaneous, keratitis, encephalitis)","name_fa":"عفونت ویروس هرپس سیمپلکس (مخاطی-جلدی، کراتیت، آنسفالیت)","cc":["rash","fever","altered-mental-status"],"keywords":"HSV encephalitis, herpes labialis, herpetic whitlow, herpes gingivostomatitis, acyclovir, valacyclovir, famciclovir, هرپس, آنسفالیت هرپسی","status":"draft","features":["انتقال با تماس مخاط/پوست باز با مایعات آلوده؛ HSV-1: ضایعات اورولابیال؛ HSV-2: شایع‌ترین تناسلی (نسبت HSV-1 در حال افزایش)","اولیه: گسترده‌تر با علائم سیستمیک؛ HSV-1: ژنژیوواستوماتیت و فارنژیت 1 تا 2 هفته با وزیکول‌های نازک روی پایه اریتماتو؛ < 5 سال با تب و لنفادنوپاتی؛ عود: herpes labialis لب پایین؛ کمتر: herpetic whitlow، herpes gladiatorum، کراتیت هرپسی (چشم دردناک قرمز با ضایعات dendritic در فلورسئین)","آنسفالیت HSV: شایع‌ترین علت ویروسی آنسفالیت در ایالات متحده؛ 20 تا 50 سال؛ مرگ > 70٪ بدون درمان؛ تب و علائم عصبی: نقص حرکتی کانونی یا اعصاب کرانیال، آتاکسی، تشنج، تغییر هوشیاری، رفتار غیرعادی؛ مننژیت تا 25٪ زنان با HSV-2 اولیه (خوش‌خیم)","ایمنوساپرس: انتشار و درگیری چندارگانی","تشخیص و شروع درمان اغلب بالینی؛ کشت از وزیکول unroofed یا PCR/DFA؛ Tzanck مفید نیست؛ آنسفالیت: ضایعات لوب تمپورال در CT/MRI؛ CSF: پلئوسیتوز لنفوسیتی و/یا اریتروسیتوز؛ PCR مایع نخاع بهترین (ظرف 24 ساعت و تا یک هفته مثبت)"],"ddx":[{"n":"HSV encephalitis |","cm":1},{"n":"Herpetic keratitis |","cm":1},{"n":"Bacterial meningitis |"},{"n":"Herpes zoster / aphthous ulcers |"},{"n":"Herpetic whitlow vs paronychia |"}],"redflags":["تب با تغییر هوشیاری، تشنج، نقص عصبی کانونی؛ چشم دردناک"],"guide":"عفونت سیستمیک شدید شامل CNS یا منتشر: acyclovir 10 mg/kg IV هر 8 ساعت (ایمنوساپرس با درگیری مخاطی شدید: 5 mg/kg IV هر 8 ساعت بر اساس وزن ایده‌آل). خفیف تا متوسط در ایمن: acyclovir 400 mg PO سه بار روزانه، valacyclovir 1000 mg هر 12 ساعت یا famciclovir 250 mg سه بار روزانه؛ مؤثرترین اگر ظرف 48 تا 72 ساعت؛ 7 تا 10 روز. عود: acyclovir 400 mg سه بار روزانه 5 روز؛ valacyclovir 2000 mg هر 12 ساعت 1 روز (labialis) یا 500 mg هر 12 ساعت 3 روز (تناسلی)؛ famciclovir 1500 mg یک دوز (اورولابیال) یا 1000 mg یک دوز (تناسلی)؛ خفیف‌تر: پماد acyclovir 5٪ شش بار روزانه 7 روز.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 91: Serious Viral Infections, pp. 497–504"},"varicella-zoster":{"id":"varicella-zoster","variants":[{"id":"zoster-outpatient","o":{"L":[{"t":"Usually clinical diagnosis; viral culture, antigen testing or PCR of vesicle fluid if atypical or severe"}],"A":[{"t":"Herpes zoster: Acyclovir 800 mg PO five times per day, or Valacyclovir 1 g three times daily, or Famciclovir 500 mg three times daily for 7 to 10 days (ideally within 72 hours of rash onset)"},{"t":"Varicella in high-risk patients (> 12 years, adults, chronic skin or pulmonary disorders, long-term salicylates, immunocompromised): Acyclovir 20 mg/kg (maximum 800 mg) five times a day for 5 days"}],"T":[{"t":"Appropriate analgesia","fl":[{"k":"note","v":"drug and dose not given in the book"}]},{"t":"Zoster ophthalmicus (Hutchinson sign or facial lesions with eye symptoms): ophthalmology consultation"}]},"name":"Herpes zoster / varicella, immunocompetent","level":"III","imp":"Herpes zoster / varicella","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۶۵ ساله با راش وزیکولار دردناک یک‌طرفه توراسیک از ۲ روز پیش.","why":"شروع ضدویروس ظرف 72 ساعت؛ ضددرد."},{"id":"zoster-immunocompromised","o":{"I":[{"t":"Chest radiograph (pneumonitis); MRI brain, lumbar puncture and PCR if CNS infection suspected"}],"A":[{"t":"Acyclovir 10 mg/kg IV every 8 hours"}],"Co":[{"t":"Admit; infectious disease"}]},"name":"Disseminated zoster / varicella in immunocompromised patient","level":"II","imp":"Disseminated zoster / varicella in immunocompromised patient","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"بیمار ۵۵ ساله پیوند کلیه با راش وزیکولار منتشر چند درماتومی، تب و تنگی نفس.","why":"انتشار: acyclovir وریدی و بستری."}],"ch":"91","name":"Varicella and herpes zoster (shingles)","name_fa":"آبله‌مرغان و زونا","cc":["rash","fever","eye"],"keywords":"varicella, chickenpox, herpes zoster, shingles, zoster ophthalmicus, Hutchinson sign, postherpetic neuralgia, acyclovir, valacyclovir, famciclovir, زونا","status":"draft","features":["VZV عامل آبله‌مرغان و زونا؛ زونا: بازفعال‌سازی ویروس نهفته در گانگلیون ریشه خلفی با ضعف ایمنی (سن یا ایمنوساپرسیون)؛ زونا در جوان سالم ممکن است نشانه HIV یا ایمنوساپرس باشد","واریسلا اولیه: بیماری تب‌دار با راش وزیکولار سطحی دسته‌دسته و متمرکز روی تنه و صورت؛ مراحل متفاوت؛ سردرد، ناخوشی، بی‌اشتهایی؛ بیشتر خفیف و خودمحدود؛ مسری تا خشک شدن همه ضایعات؛ عوارض در خردسال/سالمند/ایمنوساپرس: عفونت باکتریال (GAS) با فاشئیت نکروزان، CNS (آتاکسی مخچه‌ای، مننژیت، مننگوآنسفالیت، واسکولوپاتی و سکته)، پنومونیت شدید (حاملگی)","زونا: ضایعات مشابه یک‌طرفه و درماتومی؛ پرودروم ناخوشی، سردرد، فتوفوبی و درد/خارش/پارستزی قبل از راش؛ شایع: تریژمینال یا توراسیک؛ zoster ophthalmicus با ضایعه نوک یا کنار بینی (Hutchinson): مشاوره چشم؛ ضایعات حدود 2 هفته (تا 1 ماه)؛ نورالژی پس از هرپس: درد > 30 روز؛ چند درماتوم یا عبور از خط وسط: انتشار در ایمنوساپرس (پنومونیت، هپاتیت، آنسفالیت)","تشخیص بالینی؛ کشت/آنتی‌ژن/PCR مایع وزیکول در موارد آتیپیک یا شدید؛ آبله (smallpox): ضایعات بزرگ‌تر، بیشتر اندام و همگی در یک مرحله؛ CXR در شک پنومونیت؛ MRI، LP، PCR در شک CNS"],"ddx":[{"n":"Herpes zoster ophthalmicus (vision threat) |","cm":1},{"n":"Disseminated zoster in an immunocompromised patient |","cm":1},{"n":"Necrotizing fasciitis (secondary bacterial) |","cm":1},{"n":"Smallpox / monkeypox-like illness |"},{"n":"HSV / contact dermatitis |"}],"redflags":["ضایعه نوک بینی (Hutchinson)، ایمنوساپرس، چند درماتوم، علائم CNS یا پنومونیت"],"guide":"واریسلا اولیه در کودک سالم: حمایتی؛ acyclovir 20 mg/kg (حداکثر 800 mg) پنج بار روزانه 5 روز برای پرخطر (> 12 سال، بزرگسال، بیماری مزمن پوست/ریه، سالیسیلات طولانی‌مدت، ایمنوساپرس). زونا: ضدویروس سرعت بهبود را زیاد می‌کند، ضایعات جدید، دفع ویروس و درد حاد را کم می‌کند؛ ترجیحاً ظرف 72 ساعت (یا بیشتر اگر وزیکول جدید): acyclovir 800 mg PO پنج بار روزانه، valacyclovir 1 g سه بار روزانه یا famciclovir 500 mg سه بار روزانه، 7 تا 10 روز؛ ضددرد مناسب. ایمنوساپرس با واریسلای حاد، زونای شدید، درگیری احشایی یا انتشار: acyclovir 10 mg/kg IV هر 8 ساعت.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 91: Serious Viral Infections, pp. 497–504"},"infectious-mononucleosis":{"id":"infectious-mononucleosis","variants":[{"id":"ebv-mono-main","o":{"L":[{"t":"CBC (lymphocytosis > 50% and atypical lymphocytes) and monospot test (may be negative early; repeat later if uncertain)"}],"T":[{"t":"Rest and analgesia","fl":[{"k":"ci","v":"corticosteroids only for severe disease (upper airway obstruction, neurologic disease, hemolytic anemia); avoid contact sports for a minimum of 3 weeks (splenic injury)"}]}]},"name":"Infectious mononucleosis","level":"III","imp":"Infectious mononucleosis (EBV)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"دانشجوی ۱۹ ساله با تب، گلودرد با اگزودای لوزه، لنفادنوپاتی خلفی و اسپلنومگالی.","why":"حمایتی؛ استروئید فقط در عارضه شدید؛ پرهیز از ورزش تماسی."}],"ch":"91","name":"Epstein-Barr virus infection (infectious mononucleosis)","name_fa":"عفونت ویروس اپشتین-بار (منونوکلئوز عفونی)","cc":["fever","ent"],"keywords":"infectious mononucleosis, EBV, monospot, splenic rupture, atypical lymphocytes, منونوکلئوز","status":"draft","features":["EBV عامل منونوکلئوز عفونی هتروفیل-مثبت؛ مرتبط با لنفوم B، هوچکین، Burkitt و کارسینوم نازوفارنکس؛ انتقال بزاقی با تماس نزدیک اغلب از فرد بی‌علامت؛ اوج کودکی و جوانی","شیرخوار/کودک: اغلب بی‌علامت یا فارنژیت خفیف؛ نوجوان/جوان: تب، لنفادنوپاتی و فارنژیت با اگزودای لوزه؛ اسپلنومگالی در > نیمی؛ علائم 2 تا 3 هفته","عوارض: آنسفالیت، مننژیت، GBS، هپاتیت، میوکاردیت، اختلالات خونی؛ نادراً مرگ: پارگی طحال، CNS، انسداد راه هوایی","تشخیص: CBC و monospot (ممکن است اوایل منفی باشد؛ تکرار)؛ لنفوسیتوز > 50٪ و لنفوسیت آتیپیک"],"ddx":[{"n":"Splenic rupture / airway obstruction |","cm":1},{"n":"Streptococcal pharyngitis / peritonsillar abscess |","cm":1},{"n":"Acute HIV / CMV / toxoplasmosis |"},{"n":"Hepatitis / lymphoma |"}],"redflags":["انسداد راه هوایی، درد شدید LUQ/شانه چپ، تغییر عصبی، همولیز"],"guide":"استراحت و ضددرد پایه درمان؛ استروئید با افزایش عوارض همراه است و فقط در بیماری شدید (انسداد راه هوایی فوقانی، نورولوژیک یا آنمی همولیتیک)؛ پرهیز از تماس ورزش‌ها حداقل 3 هفته از شروع بیماری (آسیب طحال).","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 91: Serious Viral Infections, pp. 497–504"},"measles-adult":{"id":"measles-adult","variants":[{"id":"measles-main","o":{"L":[{"t":"Immunoglobulin M antibodies for confirmation (if needed)"}],"T":[{"t":"Supportive care with attention to adequate nutrition, especially vitamin A intake","fl":[{"k":"note","v":"dose not given in this chapter"}]}],"Co":[{"t":"Report suspected measles to the local health department; coordinate post-exposure prophylaxis for unvaccinated contacts"}]},"name":"Measles","level":"III","imp":"Measles","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"نوجوان ۱۶ ساله واکسن‌نزده با تب، سرفه، ملتحمه و راش از صورت به تنه؛ Koplik spots.","why":"حمایتی و گزارش؛ ایزوله؛ ویتامین A."}],"ch":"91","name":"Measles","name_fa":"سرخک","cc":["rash","fever"],"keywords":"measles, Koplik spots, vitamin A, public health, post-exposure prophylaxis, سرخک","status":"draft","features":["ویروس RNA بسیار مسری؛ قبل از علائم مسری؛ طغیان در جوامع بدون واکسیناسیون مناسب","تب، ناخوشی، سرفه، آبریزش و ملتحمه؛ Koplik spots روی مخاط گونه اوایل بیماری سپس راش ماکولوپاپولار قرمز از سر به تمام بدن","تشخیص بالینی (Koplik پاتونومونیک و راش مشخص)؛ تأیید: IgM"],"ddx":[{"n":"Measles |","cm":1},{"n":"Rubella / scarlet fever |"},{"n":"Kawasaki disease / drug eruption |"},{"n":"Other viral exanthem |"}],"redflags":["پنومونی، آنسفالیت، دهیدراتاسیون"],"guide":"درمان حمایتی با توجه ویژه به تغذیه به‌ویژه ویتامین A؛ گزارش مورد مشکوک به بهداشت محلی؛ هماهنگی برای پروفیلاکسی پس از مواجهه در تماس‌های واکسن‌نزده.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 91: Serious Viral Infections, pp. 497–504"},"arboviral-ebola":{"id":"arboviral-ebola","variants":[{"id":"arbovirus-encephalitis","o":{"I":[{"t":"Neuroimaging (MRI more sensitive)"}],"L":[{"t":"Lumbar puncture (lymphocytic pleocytosis, slightly elevated protein); serologic testing (primary confirmation)"}],"A":[{"t":"Empiric antibiotics and Acyclovir (until confirmatory testing is complete)","fl":[{"k":"note","v":"doses not given in this chapter; see HSV encephalitis: Acyclovir 10 mg/kg IV every 8 hours"}]}],"T":[{"t":"Supportive and symptomatic therapy","fl":[{"k":"ci","v":"specific antiviral drugs, interferon and steroids not shown useful"}]}],"Co":[{"t":"Admit most patients with acute encephalitis"}]},"name":"Suspected arboviral encephalitis","level":"II","imp":"Suspected arboviral encephalitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۶۰ ساله در تابستان با تب، سردرد، گیجی و ضعف؛ نیش پشه.","why":"حمایتی؛ آنتی‌بیوتیک و acyclovir تجربی تا رد باکتریال/HSV."},{"id":"vhf-ebola-isolation","o":{"L":[{"t":"Acute serologic testing or reverse transcriptase PCR at a specialized laboratory (e.g., CDC); notify the hospital laboratory about precautions"}],"S":[{"t":"Supportive care with IV fluids","fl":[{"k":"ci","v":"caution in pulmonary edema"}]}],"T":[{"t":"Full contact and droplet precautions (gown, gloves, facemask with eye protection); isolate patient; proper donning and removal of protective equipment"},{"t":"Renal replacement and respiratory support as needed (experimental serologic treatments and vaccines under development)"}],"Co":[{"t":"Contact appropriate public health organizations; ICU"}]},"name":"Suspected Ebola / viral hemorrhagic fever","level":"I","imp":"Suspected viral hemorrhagic fever (Ebola)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مسافر ۴۰ ساله از منطقه آندمیک با تب، استفراغ و خونریزی لثه.","why":"ایزولاسیون و احتیاط کامل؛ اطلاع بهداشت؛ حمایتی."}],"ch":"91","name":"Arboviral encephalitis and viral hemorrhagic fevers (Ebola, Lassa, hantavirus)","name_fa":"آنسفالیت آربوویروسی و تب‌های هموراژیک ویروسی (ابولا، لاسا، هانتاویروس)","cc":["fever","altered-mental-status","bleeding-bruising"],"keywords":"West Nile virus, arbovirus, viral encephalitis, Ebola, viral hemorrhagic fever, Lassa fever, hantavirus, isolation, ابولا, تب هموراژیک","status":"draft","features":["آربوویروس: انتقال با پشه، کنه و مگس؛ بروز بیشتر در ماه‌های گرم؛ ویروس West Nile، La Crosse، St. Louis، EEE، WEE در آمریکای شمالی؛ اکثراً بی‌علامت یا بیماری خفیف غیراختصاصی؛ چهار سندروم: تب و میالژی، آرتریت و راش، آنسفالیت، تب هموراژیک؛ سردرد شایع؛ آنسفالیت کلاسیک: تب، سردرد، تغییر هوشیاری، بی‌حالی و گیجی و گاهی تشنج؛ تب هموراژیک: خونریزی لثه، پتشی و GI","تشخیص: شرح حال دقیق سفر و مواجهه؛ MRI حساس‌تر؛ CSF پلئوسیتوز لنفوسیتی و پروتئین کمی بالا (غیراختصاصی)؛ تأیید: سرولوژی","ابولا و سایر تب‌های هموراژیک (هانتاویروس، لاسا): علائم غیراختصاصی (تب، میالژی، ناخوشی) → GI و درگیری ارگان‌ها، افزایش نفوذپذیری عروقی: هیپوتانسیون، ادم ریه، نارسایی کلیه؛ اختلال انعقاد: خونریزی منتشر، اختلال عضو و شوک","سرنخ: سفر به منطقه آندمیک و/یا تماس با مسافر آلوده؛ تأیید: سرولوژی حاد یا RT-PCR در آزمایشگاه تخصصی (مثل CDC)"],"ddx":[{"n":"Viral hemorrhagic fever (Ebola) |","cm":1},{"n":"Bacterial meningitis / HSV encephalitis |","cm":1},{"n":"Malaria / dengue (travelers) |"},{"n":"West Nile / other arboviral encephalitis |"},{"n":"Sepsis |"}],"redflags":["سفر به منطقه آندمیک با تب، خونریزی، تغییر هوشیاری، ایزولاسیون لازم"],"guide":"آربوویروس: درمان حمایتی و علامتی؛ داروی ضدویروس اختصاصی، اینترفرون و استروئید مفید نشده‌اند؛ در آنسفالیت مشکوک اوایل: آنتی‌بیوتیک تجربی و acyclovir تا تأیید؛ بستری اکثر آنسفالیت حاد. ابولا/تب هموراژیک: غربالگری در تریاژ، ایزولاسیون مسافران اخیر با تب؛ احتیاط کامل تماس و قطره (گان، دستکش، ماسک با محافظ چشم)؛ آموزش پوشیدن و درآوردن تجهیزات؛ اطلاع به بهداشت عمومی و آزمایشگاه بیمارستان؛ درمان حمایتی با مایع وریدی، جایگزینی کلیه و حمایت تنفسی.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 91: Serious Viral Infections, pp. 497–504"},"hiv-acute-febrile":{"id":"hiv-acute-febrile","variants":[{"id":"hiv-acute-febrile-main","o":{"I":[{"t":"Chest radiograph; neuroimaging then lumbar puncture if CNS infection suspected"}],"L":[{"t":"Electrolytes, CBC, blood cultures, urinalysis and culture, liver function tests; syphilis, cryptococcal, toxoplasmosis, CMV and coccidioidomycosis serology where indicated; CD4 count and viral load (or total lymphocyte count < 1700 predicts CD4 < 200); acid-fast stain of stool / body fluids for MAC; HIV-1/2 antibody with p24 antigen test (acute HIV)"}],"T":[{"t":"Standard antibiotics for suspected bacterial sepsis and focal bacterial infections (see Chapter 89)"},{"t":"Disseminated MAC: Clarithromycin 500 mg PO twice a day and Ethambutol 15 mg/kg PO once a day and Rifabutin 300 mg PO once a day","fl":[{"k":"note","v":"printed as \"300 mg/kg\" in the book"}]},{"t":"CMV: Ganciclovir 5 mg/kg IV twice a day for 2 weeks, then 5 mg/kg/d; or Foscarnet 90 mg/kg every 12 h for 3 weeks, then 90 mg/kg once a day"}],"Co":[{"t":"Admit for new FUO, hypoxia, suspected PCP/TB, new CNS symptoms, intractable diarrhea, suspected CMV retinitis, zoster ophthalmicus or inability to self-care; infectious disease; discuss suspected immune reconstitution syndrome"}]},"name":"Fever in HIV patient / suspected acute HIV","level":"II","imp":"Febrile illness in HIV infection / suspected acute HIV","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مردی ۳۰ ساله HIV مثبت با CD4 120، تب 2 هفته‌ای، تعریق شبانه و کاهش وزن.","why":"CD4 < 200: PCP، MAC، TB؛ کشت و CXR؛ بستری در FUO جدید."}],"ch":"92","name":"HIV infection: acute HIV syndrome and febrile illness in HIV patients","name_fa":"عفونت HIV: سندرم حاد HIV و بیماری تب‌دار در بیماران HIV","cc":["fever","rash"],"keywords":"acute HIV, seroconversion, p24 antigen, CD4 count, AIDS, febrile illness, MAC, CMV, immune reconstitution, ایدز, HIV","status":"draft","features":["ویروس سیتوپاتیک رتروویروس که سلول‌های CD4+ را هدف می‌گیرد؛ نقص ایمنی سلولی پایدار → عفونت‌های فرصت‌طلب و نئوپلاسم","عفونت حاد (تا 90٪ علامت‌دار): علائم غیراختصاصی شبه‌آنفلوانزا، 2 تا 4 هفته پس از مواجهه، 2 تا 10 هفته: تب (> 90٪)، خستگی (70% تا 90%)، گلودرد (> 70%)، راش (40% تا 80%)، سردرد (30% تا 80%)، لنفادنوپاتی (40% تا 70%)؛ سروکنورژن 3 تا 8 هفته (تا 11 ماه)","علامت‌دار زودرس (CD4 200 تا 500): برفک، کاندیدیازیس راجعه، نوروپاتی، دیسپلازی سرویکس، زونای راجعه، ITP؛ CD4 < 200: فراوانی عفونت فرصت‌طلب؛ AIDS: هر بیماری شاخص (جدول 92-1) یا CD4 < 200؛ پیشرفته: CD4 < 50 (MAC یا CMV منتشر)","تشخیص: RNA، p24 آنتی‌ژن، آنتی‌بادی، کشت؛ زمان تا تشخیص: بار ویروسی 17 روز، p24 22 روز، ELISA 25 روز، Western blot 31 روز؛ توصیه فعلی: آنتی‌بادی HIV-1/2 همراه با p24؛ تا 75٪ عفونت حاد تشخیص داده نمی‌شود","بیمار شناخته‌شده: CD4 اخیر و بار ویروسی؛ CD4 < 200 و بار > 50000 خطر بیماری AIDS-defining؛ لنفوسیت توتال < 1700 پیش‌بینی CD4 < 200","بیماری تب‌دار: اکثریت مراجعات: CD4 > 500 مثل ایمن؛ 200 تا 500: عفونت تنفسی باکتریال؛ < 200: PCP، MAC، TB، CMV، تب دارویی، سینوزیت؛ اندوکاردیت، لنفوم، Histoplasma، Cryptococcus؛ تب HIV اولیه: عصر و شب و پاسخ به تب‌بر","IRIS: تب، لنفادنیت و علائم سیستمیک هفته‌ها تا ماه‌ها بعد از ART (اغلب با درمان TB)؛ به‌ندرت قطع دارو؛ مشاوره عفونی","CMV: رتینیت مهم‌ترین؛ MAC منتشر: CD4 < 100 بدون ART: تب، تعریق شبانه، کاهش وزن، اسهال؛ آزمایش اسید-فست"],"ddx":[{"n":"Pneumocystis pneumonia |","cm":1},{"n":"CNS opportunistic infection (toxoplasmosis, cryptococcal meningitis) |","cm":1},{"n":"Tuberculosis |","cm":1},{"n":"Disseminated MAC / CMV |"},{"n":"Drug fever / immune reconstitution syndrome |"},{"n":"Syphilis / endocarditis / lymphoma |"}],"redflags":["هیپوکسی، علائم عصبی جدید، تب با CD4 < 200، رتینیت"],"guide":"آگاهی از HIV تشخیص‌داده‌نشده در همه جمعیت‌ها (بسیاری قابل پیش‌بینی با دموگرافیک نیستند). تب: الکترولیت، CBC، کشت خون، UA و کشت، LFT و CXR؛ سرولوژی انتخابی (سیفلیس، کریپتوکوک، توکسوپلاسما، CMV، کوکسیدیوئیدومایکوز)؛ LP بعد از تصویربرداری عصبی در شک CNS. معیار بستری AIDS: FUO جدید، هیپوکسی بدتر از پایه یا PaO2 < 60، شک PCP/TB، علائم CNS جدید، اسهال مقاوم، شک رتینیت CMV، زونای چشمی یا ناتوانی در مراقبت از خود. سپسیس باکتریال و عفونت کانونی: آنتی‌بیوتیک استاندارد (فصل ۸۹). ART به‌ندرت در ED شروع می‌شود (CD4 < 350 یا بیماری AIDS-defining؛ بدون توجه به CD4: حاملگی، نوروپاتی HIV، همراهی هپاتیت B نیازمند درمان؛ 2 NRTI + PI یا NNRTI).","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 92: HIV Infection and AIDS, pp. 505–512"},"hiv-pulmonary-pcp-tb":{"id":"hiv-pulmonary-pcp-tb","variants":[{"id":"hiv-pcp","o":{"I":[{"t":"Chest radiograph (diffuse interstitial infiltrates; negative in up to 20%); bronchoscopy for definitive diagnosis"}],"L":[{"t":"Pulse oximetry (rest and exertion), arterial blood gas (alveolar-arterial gradient), lactate dehydrogenase, sputum Gram stain and culture, acid-fast stain, blood cultures"}],"A":[{"t":"Trimethoprim-sulfamethoxazole 15–20 mg of trimethoprim component per kilogram per day PO or IV in divided doses three times a day for 3 weeks"}],"T":[{"t":"If PaO2 < 70 mm Hg or alveolar-arterial gradient > 35 mm Hg: Prednisone 40 mg twice a day for 5 days, then 40 mg once a day for 5 days, then 20 mg once a day for 11 days"},{"t":"Alternative: Pentamidine 4 mg/kg/d IV or IM for 3 weeks"}],"Co":[{"t":"Admit (hypoxia / suspected PCP); infectious disease"}]},"name":"Suspected Pneumocystis pneumonia","level":"I","imp":"Suspected Pneumocystis jirovecii pneumonia","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: F.M 6–10 L/min or N.C 3–5 L/min if SpO2 < 94%","sc":"مردی ۳۵ ساله با AIDS (CD4 60)، تب، سرفه خشک و تنگی نفس پیشرونده؛ SpO2 86٪.","why":"PCP: TMP-SMX و استروئید اگر PaO2 < 70؛ بستری."},{"id":"hiv-tb","o":{"I":[{"t":"Chest radiograph (classic upper lobe and cavitary lesions less common)"}],"L":[{"t":"Sputum acid-fast stain and culture","fl":[{"k":"ci","v":"PPD false-negative frequently"}]}],"T":[{"t":"Respiratory isolation"}],"A":[{"t":"Isoniazid 5 mg/kg PO once a day and Rifampin 10 mg/kg PO once a day (or Rifabutin 5 mg/kg PO once a day) and Pyrazinamide 15–30 mg/kg PO once a day and Ethambutol 15–20 mg/kg PO once a day","fl":[{"k":"note","v":"specific drug regimen must be adjusted if the patient is receiving highly active antiretroviral therapy"}]}],"Co":[{"t":"Admit if suspected TB; infectious disease"}]},"name":"Suspected tuberculosis in HIV patient","level":"II","imp":"Suspected tuberculosis in HIV patient","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","o2":"O2 therapy: if SpO2 < 94%, F.M 6–10 L/min or N.C 3–5 L/min; respiratory isolation","sc":"زنی ۲۸ ساله با HIV و CD4 220، تب طولانی، سرفه و کاهش وزن.","why":"TB در HIV آتیپیک؛ ایزولاسیون تنفسی و رژیم چهاردارویی."}],"ch":"92","name":"HIV pulmonary complications: Pneumocystis pneumonia and tuberculosis","name_fa":"عوارض ریوی HIV: پنومونی Pneumocystis و سل","cc":["dyspnea","cough-hemoptysis","fever"],"keywords":"Pneumocystis jirovecii pneumonia, PCP, trimethoprim-sulfamethoxazole, prednisone, pentamidine, tuberculosis HIV, isolation, LDH, پنوموسیستیس","status":"draft","features":["مراجعات ریوی از شایع‌ترین؛ پنومونی باکتریال شایع‌تر از فرصت‌طلب؛ S. pneumoniae شایع‌ترین؛ سرفه مولد، لکوسیتوز و انفیلتره کانونی؛ علل مرتبط HIV: PCP، TB، CMV، C. neoformans، Histoplasma و نئوپلاسم","PCP: شایع‌ترین عفونت فرصت‌طلب و علت مرگ در AIDS؛ علائم موذی: تب، سرفه غیرمولد و تنگی نفس پیشرونده؛ CXR انفیلتره بینابینی منتشر (تا 20٪ نرمال)؛ LDH بالا (غیراختصاصی)؛ هیپوکسی در استراحت/فعالیت و گرادیان A-a بالا؛ تشخیص احتمالی در هیپوکسمی بدون توضیح؛ قطعی اغلب با برونکوسکوپی","TB: CD4 200 تا 500؛ ایزولاسیون تنفسی؛ با پیشرفت HIV علائم کلاسیک (سرفه با هموپتزی، تعریق شبانه، تب طولانی، کاهش وزن) نیست؛ درگیری لوب فوقانی و حفره کمتر؛ PPD منفی کاذب شایع؛ TB خارج ریوی (غدد لنفاوی، مغز استخوان، CNS، GI، ادراری)","ارزیابی: پالس‌اکسیمتری، ABG، کشت و Gram خلط، رنگ اسید-فست، کشت خون، CXR","قارچ منتشر (C. neoformans، A. fumigatus) در ایمنوساپرس شدید؛ علل غیرعفونی: نئوپلاسم، LIP"],"ddx":[{"n":"Pneumocystis jirovecii pneumonia |","cm":1},{"n":"Pulmonary tuberculosis |","cm":1},{"n":"Bacterial pneumonia (Streptococcus pneumoniae) |"},{"n":"CMV / fungal pneumonia |"},{"n":"Lymphocytic interstitial pneumonitis / neoplasm |"}],"redflags":["هیپوکسی در استراحت، PaO2 < 70 یا گرادیان A-a > 35، شک TB (ایزولاسیون)"],"guide":"PCP: trimethoprim-sulfamethoxazole با dose 15–20 mg مؤلفه trimethoprim به‌ازای kg در روز PO یا IV در دوزهای منقسم سه بار روزانه به مدت 3 هفته؛ اگر PaO2 < 70 mm Hg یا گرادیان A-a > 35: افزودن prednisone 40 mg دو بار روزانه 5 روز سپس 40 mg روزانه 5 روز سپس 20 mg روزانه 11 روز؛ یا pentamidine 4 mg/kg/d IV یا IM به مدت 3 هفته. TB: isoniazid 5 mg/kg PO روزانه + rifampin 10 mg/kg PO روزانه (یا rifabutin 5 mg/kg) + pyrazinamide 15–30 mg/kg + ethambutol 15–20 mg/kg؛ رژیم باید با ART تنظیم شود.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 92: HIV Infection and AIDS, pp. 505–512"},"hiv-cns-eye-gi-skin":{"id":"hiv-cns-eye-gi-skin","variants":[{"id":"hiv-cns-infection","o":{"I":[{"t":"Noncontrast head CT first (contrast-enhanced CT or MRI as appropriate)"}],"L":[{"t":"Lumbar puncture: opening pressure; cell count, glucose, protein, Gram stain, India ink stain, bacterial, viral and fungal cultures, toxoplasmosis and cryptococcus antigen, coccidioidomycosis titer"}],"T":[{"t":"Toxoplasmosis: Pyrimethamine 200-mg loading dose PO followed by 50–75 mg PO once a day for 6–8 weeks and Sulfadiazine 1–1.5 g PO every 6 h for 6–8 weeks and Leucovorin 10–25 mg once a day"},{"t":"Cryptococcosis: Amphotericin B 0.7 mg/kg IV once a day for 2 weeks and Flucytosine 25 mg/kg IV four times a day for 2 weeks then Fluconazole 400 mg/d PO for 8–10 weeks","fl":[{"k":"renal","v":"amphotericin B / flucytosine"}]}],"Co":[{"t":"Admit; infectious disease / neurology"}]},"name":"HIV with new CNS symptoms (toxoplasmosis / cryptococcal meningitis)","level":"I","imp":"CNS opportunistic infection in HIV (toxoplasmosis / cryptococcal meningitis)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۴۰ ساله با AIDS (CD4 40)، سردرد پیشرونده، تب و تشنج.","why":"CD4 < 200 با علامت عصبی: CT سپس LP؛ درمان تجربی."},{"id":"hiv-cmv-retinitis-eye","o":{"L":[{"t":"Clinical ophthalmologic evaluation (retinitis often diagnosed clinically)"}],"A":[{"t":"Valganciclovir 900 mg PO twice a day for 14–20 days of induction therapy, then 900 mg PO daily for maintenance; with Ganciclovir 2 mg intravitreal injection 1–4 doses over 7–10 days (or Foscarnet 2.4 mg intravitreal injection) for immediately sight-threatening lesions"},{"t":"Zoster ophthalmicus: Acyclovir 5–10 mg/kg IV/PO every 8 h for 5–7 days (ocular or disseminated disease)"}],"Co":[{"t":"Admit (suspected CMV retinitis, zoster ophthalmicus); ophthalmology"}]},"name":"HIV with visual symptoms (CMV retinitis / zoster ophthalmicus)","level":"II","imp":"CMV retinitis / herpes zoster ophthalmicus in HIV","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۸ ساله با AIDS (CD4 30)، کاهش بینایی و اسکوتوم یک‌چشم.","why":"رتینیت CMV: تهدید بینایی؛ مشاوره فوری چشم و درمان."},{"id":"hiv-gi-oral-skin","o":{"L":[{"t":"Stool for leukocytes, ova and parasites; acid-fast staining and bacterial culture"}],"A":[{"t":"Oral candidiasis: Clotrimazole 10-mg troches five times a day, or Nystatin 500,000 units five times a day (gargle)"},{"t":"Esophagitis (primarily Candida): Fluconazole 100–400 mg/d PO"},{"t":"Diarrhea (bacterial infection suspected) / salmonellosis: Ciprofloxacin 500 mg PO twice a day for 2–4 weeks"},{"t":"Herpes simplex: Acyclovir 200 mg PO five times a day for 7 days, or Famciclovir 125 mg PO twice a day for 7 days, or Valacyclovir 1 g PO twice a day for 7 days; severe disease Acyclovir 5–10 mg/kg IV every 8 h for 7 days"},{"t":"Herpes zoster: Acyclovir 800 mg PO five times a day for 7–10 days, or Famciclovir 500 mg PO three times a day, or Valacyclovir 1 g PO three times a day for 7–10 days"},{"t":"Candida or Trichophyton skin infection: topical Clotrimazole, Miconazole or Ketoconazole two or three times a day for 3 weeks"}],"Co":[{"t":"Admit for intractable diarrhea"}]},"name":"HIV with oral/esophageal candidiasis, diarrhea or cutaneous infection","level":"III","imp":"HIV-related candidiasis / diarrhea / herpes infection","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۴۲ ساله با HIV، دیسفاژی، پلاک سفید دهان و اسهال آبکی ۲ هفته‌ای.","why":"برفک/ازوفاژیت با فلوکونازول؛ اسهال: بررسی مدفوع و سیپروفلوکساسین تجربی."}],"ch":"92","name":"HIV: CNS opportunistic infections, CMV retinitis, GI and cutaneous complications","name_fa":"HIV: عفونت‌های فرصت‌طلب CNS، رتینیت CMV، عوارض گوارشی و پوستی","cc":["headache","altered-mental-status","eye","diarrhea","rash"],"keywords":"toxoplasmosis, cryptococcal meningitis, CMV retinitis, AIDS dementia, oral candidiasis, Kaposi sarcoma, cryptosporidium, pyrimethamine, amphotericin B, fluconazole, valganciclovir, توکسوپلاسموز, کریپتوکوکوز","status":"draft","features":["CNS: سردرد، تشنج، تغییر هوشیاری، مننژیسم یا نقص کانونی: AIDS dementia، Toxoplasma gondii یا C. neoformans؛ تصویربرداری و LP در CD4 < 200 با نقص یا سردرد؛ ابتدا CT بدون کنتراست (یا CT با کنتراست/MRI)؛ LP: فشار باز، شمارش سلولی، گلوکز، پروتئین، Gram، India ink، کشت‌های باکتریال/ویروسی/قارچی، آنتی‌ژن توکسوپلاسما و کریپتوکوک، تیتر کوکسیدیوئیدو؛ AIDS dementia: اختلال تدریجی حافظه؛ کمتر: مننژیت باکتریال، هیستوپلاسموز، CMV، PML، HSV، نوروسیفیلیس، TB؛ نوروپاتی HIV: علائم حسی دردناک پا","چشم: رتینیت CMV شایع‌ترین و علت اصلی کوری در AIDS؛ اوایل بی‌علامت؛ تغییر حدت بینایی، نقص میدان، فتوفوبی، اسکوتوم، قرمزی یا درد؛ zoster ophthalmicus (راش در شاخه افتالمیک V)","GI: اسهال (50% تا 90%): باکتری، انگل، ویروس، قارچ و عوارض ضدویروس؛ بررسی لکوسیت و تخم/انگل مدفوع، اسید-فست و کشت؛ ciprofloxacin تجربی؛ Cryptosporidium و Isospora: اسهال آبکی منتشر؛ مرحله پیشرفته: MAC و CMV (نیاز به بیوپسی)؛ کاندیدیازیس دهانی (> 80٪): پلاک سفید قابل‌کندن؛ ازوفاژیت (Candida، HSV، CMV): ادینوفاژی/دیسفاژی؛ هپاتومگالی با ALP بالا (~50٪)؛ هپاتیت B و C شایع؛ پروکتیت: گنوره، کلامیدیا، سیفلیس، HSV","پوست: خشکی، سبورئیک و خارش؛ کاپوزی ساکوم (پاپول/ندول قهوه‌ای-سیاه یا بنفش بدون درد، غیربلانچ‌شونده: صورت، قفسه، ژنیتال، دهان)؛ زونا، HSV؛ ایمپتیگوی بولوز و زخم مزمن Pseudomonas؛ گال، HPV، حساسیت دارویی"],"ddx":[{"n":"CNS toxoplasmosis / cryptococcal meningitis |","cm":1},{"n":"CMV retinitis (sight-threatening) |","cm":1},{"n":"Herpes zoster ophthalmicus |","cm":1},{"n":"Esophagitis (Candida, HSV, CMV) |"},{"n":"Infectious diarrhea (Cryptosporidium, MAC, CMV) |"},{"n":"Kaposi sarcoma / drug hypersensitivity |"}],"redflags":["سردرد/نقص عصبی با CD4 < 200، کاهش بینایی، دیسفاژی/ادینوفاژی شدید، اسهال مقاوم"],"guide":"CNS: توکسوپلاسموز: pyrimethamine بار 200 mg PO سپس 50–75 mg روزانه 6 تا 8 هفته + sulfadiazine 1–1.5 g PO هر 6 ساعت 6 تا 8 هفته + leucovorin 10–25 mg روزانه. کریپتوکوکوز: amphotericin B 0.7 mg/kg IV روزانه 2 هفته + flucytosine 25 mg/kg IV چهار بار روزانه 2 هفته سپس fluconazole 400 mg/d PO 8 تا 10 هفته (نگهدارنده؛ قطع اگر CD4 > 150 برای > 16 هفته). چشم CMV: valganciclovir 900 mg PO دو بار روزانه 14 تا 20 روز القایی سپس 900 mg روزانه نگهدارنده + ganciclovir 2 mg داخل زجاجیه 1 تا 4 دوز طی 7 تا 10 روز (ضایعه تهدیدکننده فوری بینایی) یا foscarnet 2.4 mg داخل زجاجیه. GI: برفک: clotrimazole troche 10 mg پنج بار روزانه یا nystatin 500000 واحد پنج بار روزانه (gargle)؛ ازوفاژیت: fluconazole 100–400 mg/d PO؛ سالمونلوز: ciprofloxacin 500 mg PO دو بار روزانه 2 تا 4 هفته؛ کریپتوسپوریدیوز: درمان قطعی ندارد؛ بهترین پاسخ با ART. پوست: HSV: acyclovir 200 mg پنج بار روزانه 7 روز یا famciclovir 125 mg دو بار روزانه 7 روز یا valacyclovir 1 g دو بار روزانه 7 روز؛ شدید: acyclovir 5–10 mg/kg IV هر 8 ساعت 7 روز. زونا: acyclovir 800 mg پنج بار روزانه 7 تا 10 روز یا famciclovir 500 mg سه بار روزانه یا valacyclovir 1 g سه بار روزانه؛ چشمی/منتشر: acyclovir 5–10 mg/kg هر 8 ساعت 5 تا 7 روز؛ کاندیدا/Trichophyton: clotrimazole/miconazole/ketoconazole موضعی 2 تا 3 بار روزانه 3 هفته.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 92: HIV Infection and AIDS, pp. 505–512"},"hiv-occupational-pep":{"id":"hiv-occupational-pep","variants":[{"id":"hiv-pep-main","o":{"L":[{"t":"Source patient testing and baseline testing per institutional guideline","fl":[{"k":"note","v":"not detailed in this chapter"}]}],"T":[{"t":"Post-exposure prophylaxis as quickly as possible, preferably within 2 hours, continued for 28 days; minimum three-drug regimen","fl":[{"k":"note","v":"drugs and doses not given in the book; see CDC"}]}],"Co":[{"t":"Infectious disease / occupational health follow-up"}]},"name":"Occupational exposure to HIV","level":"II","imp":"Occupational exposure to HIV","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"پرستار ۳۰ ساله با فرو رفتن سوزن آلوده به خون بیمار HIV مثبت.","why":"PEP ظرف 2 ساعت و ادامه 28 روز."}],"ch":"92","name":"Occupational HIV exposure (post-exposure prophylaxis)","name_fa":"مواجهه شغلی با HIV (پروفیلاکسی پس از مواجهه)","cc":["wound-bite","poisoning"],"keywords":"HIV post-exposure prophylaxis, needlestick, occupational exposure, antiretroviral prophylaxis, پروفیلاکسی پس از مواجهه HIV","status":"draft","features":["ریسک سروکنورژن: (1) آسیب عمیق، (2) خون قابل‌رؤیت روی وسیله، (3) سوزن در ورید/شریان بیمار منبع، (4) بیمار منبع با HIV پیشرفته","پروفیلاکسی پس از مواجهه (PEP) هرچه سریع‌تر، ترجیحاً ظرف 2 ساعت، و ادامه به مدت 28 روز؛ حداقل رژیم سه‌دارویی"],"ddx":[{"n":"HIV / hepatitis B / hepatitis C exposure |","cm":1}],"redflags":["مواجهه پرخطر (آسیب عمیق، ورید/شریان، منبع پیشرفته)"],"guide":"رژیم سه‌دارویی طبق پروتکل مرکز؛ داروهای مشخص در این فصل ذکر نشده است؛ پایش و مشاوره عفونی؛ به راهنمای CDC مراجعه کن.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 92: HIV Infection and AIDS, pp. 505–512"},"infective-endocarditis":{"id":"infective-endocarditis","variants":[{"id":"endocarditis-suspected","o":{"I":[{"t":"Transthoracic echocardiography (transesophageal echocardiography if inconclusive); chest radiograph; neuroimaging if neurologic signs"}],"L":[{"t":"Three sets of blood cultures from three separate vascular sites before antibiotics, ideally with an hour elapsing between first and last; ESR/CRP, hematuria, anemia; urinalysis"}],"A":[{"t":"Uncomplicated: Ceftriaxone 1–2 g IV, or Nafcillin 2 g IV, or Oxacillin 2 g IV, or Vancomycin 15 mg/kg plus Gentamicin 1–3 mg/kg IV or Tobramycin 1 mg/kg IV"},{"t":"Injection drug use, congenital heart disease, hospital-acquired, suspected MRSA, or already on oral antibiotics: Nafcillin 2 g IV plus Gentamicin 1–3 mg/kg IV plus Vancomycin 15 mg/kg IV"},{"t":"Prosthetic heart valve: Vancomycin 15 mg/kg IV plus Gentamicin 1–3 mg/kg IV plus Rifampin 300 mg PO","fl":[{"k":"renal","v":"aminoglycoside"}]}],"T":[{"t":"Pulmonary edema from left-sided valvular rupture: afterload reduction along with usual care for acute heart failure"}],"Co":[{"t":"Admit; cardiology, infectious disease and thoracic surgery (team approach)"}]},"name":"Suspected infective endocarditis","level":"II","imp":"Suspected infective endocarditis","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","sc":"مرد ۳۵ ساله مصرف‌کننده تزریقی با تب 5 روزه، لرز، سوفل جدید و تنگی نفس.","why":"کشت‌های سه‌گانه قبل از آنتی‌بیوتیک؛ اکو؛ پوشش MRSA."}],"ch":"93","name":"Infective endocarditis","name_fa":"اندوکاردیت عفونی","cc":["fever","dyspnea","focal-neuro","chest-pain"],"keywords":"infective endocarditis, Duke criteria, vegetation, Osler nodes, Janeway lesions, blood cultures, vancomycin, gentamicin, nafcillin, echocardiography, اندوکاردیت","status":"draft","features":["عفونت و آسیب اندوکارد با مرگ‌ومیر و عوارض بالا؛ شایع‌تر در دریچه مصنوعی، ناهنجاری ساختاری مادرزادی/اکتسابی، تزریق مواد، وسیله عروقی کاشته‌شده، بهداشت دهان بد، HIV، همودیالیز مزمن","شایع‌ترین عامل استافیلوکوک (دریچه طبیعی و مصنوعی)؛ استرپتوکوک و انتروکوک؛ کشت منفی تا 5٪؛ میترال شایع‌ترین دریچه سپس آئورت، تریکوسپید، پولمونیک؛ مصرف تزریقی: دریچه سمت راست","طیف از شروع حاد و فولمینانت (تب، سوفل جدید، نارسایی قلبی) تا موذی (ناخوشی و خستگی)؛ تب (80٪)، لرز، ضعف، تنگی نفس (40٪)، بی‌اشتهایی، سرفه؛ سوفل و تب شایع‌ترین یافته؛ یافته‌های پوستی کلاسیک (Osler، Janeway، پتشی، splinter) < 50٪","عوارض قلبی (نارسایی قلبی حدود 70٪ به علت تخریب دریچه یا پارگی کوردا؛ بلوک و دیس‌ریتمی)، عصبی (20% تا 40%: سکته ایسکمیک، آبسه مغز، خونریزی، آنوریسم قارچی، تشنج)، آمبولیک (ریه، طحال، روده، کلیه، ایسکمی حاد اندام)","تشخیص در ED دشوار (کشت خون، اکو و مشاهده بالینی)؛ تب بی‌علت با عوامل خطر؛ Duke criteria: ماژور: کشت مثبت با ارگانیسم تیپیک از دو کشت جدا (S. bovis، viridans، HACEK، S. aureus اکتسابی از جامعه یا انتروکوک بدون کانون اولیه) یا کشت پایدار؛ شواهد اکو (vegetation، آبسه، جدا شدن دریچه مصنوعی، رگورژیتاسیون جدید)؛ مینور: زمینه، تب > 38، پدیده‌های عروقی (آمبولی، لکه‌های ملتحمه، Janeway)، ایمونولوژیک (GN، Osler، Roth)، شواهد میکروبیولوژیک؛ قطعی: دو ماژور یا یک ماژور + سه مینور یا پنج مینور؛ ممکن: یک ماژور + یک مینور یا سه مینور","ارزیابی: سه ست کشت خون از سه محل جدا قبل از آنتی‌بیوتیک (ایده‌آل با فاصله 1 ساعت بین اول و آخر)؛ اکو (TTE سپس TEE حساس‌تر)؛ ECG، CXR، آزمایش: آنمی، هماچوری و ESR/CRP بالا"],"ddx":[{"n":"Acute heart failure from valve destruction |","cm":1},{"n":"Embolic stroke / mycotic aneurysm |","cm":1},{"n":"Sepsis from another source |","cm":1},{"n":"Rheumatic fever / SLE |"},{"n":"Vasculitis / atrial myxoma |"}],"redflags":["نارسایی قلبی جدید، سوفل جدید، نقص عصبی، آمبولی محیطی، بلوک قلبی"],"guide":"1) ثبات راه هوایی/تنفس/گردش خون. 2) ادم ریه به علت پارگی دریچه چپ: کاهش afterload همراه درمان معمول نارسایی قلبی. 3) آنتی‌بیوتیک به‌محض گرفتن کشت‌ها (جدول 93-3): بدون عارضه: ceftriaxone 1–2 g IV یا nafcillin 2 g IV یا oxacillin 2 g IV یا vancomycin 15 mg/kg + gentamicin 1–3 mg/kg IV یا tobramycin 1 mg/kg IV. مصرف تزریقی مواد، CHD، بیمارستانی، MRSA مشکوک یا تحت آنتی‌بیوتیک خوراکی: nafcillin 2 g IV + gentamicin 1–3 mg/kg IV + vancomycin 15 mg/kg IV. دریچه مصنوعی: vancomycin 15 mg/kg IV + gentamicin 1–3 mg/kg IV + rifampin 300 mg PO. درمان قطعی بر اساس کشت: 4 تا 6 هفته. 4) بستری با تیم کاردیولوژی، عفونی و جراحی قفسه سینه. 5) پروفیلاکسی فقط پرخطرترین: سابقه IE، دریچه مصنوعی، نقص مادرزادی ترمیم‌نشده، پیوند قلب با رگورژیتاسیون.","pearls":["سه ست کشت خون قبل از آنتی‌بیوتیک."],"section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 93: Infective Endocarditis, pp. 513–516"},"tetanus":{"id":"tetanus","variants":[{"id":"tetanus-generalized","o":{"L":[{"t":"Clinical diagnosis (no confirmatory test); CK and electrolytes","fl":[{"k":"note","v":"not specified in this chapter"}]}],"T":[{"t":"Tetanus immune globulin 3000 to 6000 units IM in a single injection away from the toxoid site, before wound debridement"},{"t":"Tetanus toxoid 0.5 mL IM at presentation, and 6 weeks and 6 months after"},{"t":"Identify and debride any wound or devitalized tissue"},{"t":"Midazolam 0.05 to 0.15 mg/kg/h IV continuous drip (monitored setting), or Lorazepam 2 mg IV to effect","fl":[{"k":"hi","v":""}]},{"t":"Neuromuscular blockade if needed (intubated): Vecuronium bolus 0.1 mg/kg IV then continuous infusion 1 μg/kg/min with appropriate sedation"},{"t":"Sympathetic hyperactivity: Labetalol 0.25 to 1 mg/min IV infusion; Magnesium sulfate 40 mg/kg loading dose then 2 g/h IV (1.5 g/h if ≤ 45 kg) to maintain 2.0–4.0 mmol/L; Morphine sulfate 0.5 to 1 mg/kg/h; Clonidine 0.3 mg every 8 hours PO or NG"},{"t":"Minimize environmental stimuli (noise, touch)"}],"A":[{"t":"Metronidazole 500 mg IV every 6 hours when indicated (antibiotics of uncertain value)"}],"Co":[{"t":"ICU admission; active immunization after recovery (recovery does not confer immunity)"}]},"name":"Generalized tetanus","level":"I","imp":"Generalized tetanus","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: oxygen; airway readiness for laryngospasm / respiratory spasm (ICU)","sc":"مردی ۵۰ ساله با زخم نافذ پا ۱۰ روز قبل و حالا trismus، سفتی شکم و اسپاسم با صدا.","why":"تهدید راه هوایی؛ immune globulin قبل از دبریدمان؛ بنزودیازپین؛ ICU."}],"ch":"94","name":"Tetanus","name_fa":"کزاز","cc":["wound-bite","weakness"],"keywords":"tetanus, Clostridium tetani, trismus, risus sardonicus, tetanus immune globulin, tetanus toxoid, midazolam, magnesium sulfate, کزاز","status":"draft","features":["بیماری حاد و اغلب کشنده ناشی از C. tetani و اگزوتوکسین؛ بعد از هر آسیب (زخم تمیز یا آلوده، جراحی انتخابی، سوختگی، زخم نافذ، اوتیت میانی، عفونت دندان، گزش، سقط و بارداری)؛ در کشورهای توسعه‌یافته نادر","C. tetani در خاک، گردوغبار، پوست و مدفوع؛ اسپور مقاوم؛ شرایط بی‌هوازی بافتی (بافت له‌شده یا نکروتیک، جسم خارجی، عفونت) سم تولید می‌کند؛ نهفتگی < 24 ساعت تا > 1 ماه (اغلب ≤ 14 روز)؛ بسیاری بدون آسیب مشخص؛ آسیب‌ها اغلب جزئی و داخل خانه","موضعی (نادر)، سفالیک (نادر؛ اوتیت یا آسیب سر؛ صورت و اعصاب کرانیال)، منتشر (80٪): الگوی نزولی: درد و سفتی فک → trismus (lockjaw) → risus sardonicus؛ اسپاسم شدید و انقباض تونیک: دیسفاژی، opisthotonos، خم شدن دست، مشت، سفتی شکم، اکستانسیون پا","علائم اتونوم: تب، تعریق، فشار بالا و تاکی‌کاردی؛ نوزادی: ایمنی ناکافی مادر و مراقبت بد بند ناف؛ هفته دوم؛ مرگ‌ومیر بسیار بالا","تشخیص بالینی؛ تست تأییدی ندارد؛ ایمونیزاسیون قبلی تشخیص را رد نمی‌کند","افتراق: مسمومیت استریکنین، دیستونی فنوتیازین، تتانی هیپوکلسمیک، هاری، آبسه پری‌تانسیلار، پریتونیت، مننژیت"],"ddx":[{"n":"Strychnine poisoning |","cm":1},{"n":"Meningitis / rabies |","cm":1},{"n":"Dystonic reaction / hypocalcemic tetany |"},{"n":"Peritonsillar abscess / peritonitis |"}],"redflags":["trismus، اسپاسم تنفسی/لارنگواسپاسم، ناپایداری اتونوم"],"guide":"بستری برای اسپاسم‌های مکرر (3 تا 4 هفته)؛ تحریک با صدا/لمس؛ محیط کم‌تحریک؛ ICU. 1) tetanus immune globulin 3000 تا 6000 واحد IM تک‌تزریق دور از محل toxoid و قبل از دبریدمان زخم. 2) tetanus toxoid 0.5 mL IM در مراجعه، 6 هفته و 6 ماه بعد. 3) دبریدمان زخم/بافت نکروتیک. 4) آنتی‌بیوتیک ارزش نامطمئن: metronidazole 500 mg IV هر 6 ساعت. 5) بنزودیازپین: midazolam 0.05 تا 0.15 mg/kg/h IV در محیط پایش یا lorazepam 2 mg IV تا اثر. 6) بلوک عصبی-عضلانی: vecuronium بولوس 0.1 mg/kg IV سپس 1 μg/kg/min با سداسیون مناسب. 7) فعالیت سمپاتیک: labetalol 0.25 تا 1 mg/min انفوزیون (کودک 0.3 تا 1 mg/kg/h)؛ magnesium sulfate 40 mg/kg بار سپس 2 g/h (1.5 g/h اگر ≤ 45 kg) برای سطح 2.0 تا 4.0 mmol/L؛ morphine 0.5 تا 1 mg/kg/h؛ clonidine 0.3 mg هر 8 ساعت PO/NG. 8) بهبودیافتگان نیاز به ایمونیزاسیون فعال دارند.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 94: Tetanus and Rabies, pp. 517–522"},"rabies-exposure":{"id":"rabies-exposure","variants":[{"id":"rabies-pep-unimmunized","o":{"T":[{"t":"Wound cleansing with soap and water; irrigation with 9:1 diluted povidone-iodine solution (1 mL in 9 mL water or normal saline) if available; tetanus prophylaxis; antibiotics if indicated"},{"t":"Human rabies immunoglobulin (HRIG) 20 IU/kg actual body weight: infiltrate full dose around the wound(s) if anatomically feasible and give any remaining volume IM at an anatomic site distant from vaccine administration (not in the same syringe as vaccine; do not exceed recommended dose); give up to the seventh day after the initial exposure"},{"t":"Rabies vaccine (HDCV or PCECV) 1.0 mL deltoid area (anterolateral thigh in younger children; never gluteal) on days 0, 3, 7 and 14 (immunocompromised: fifth dose on day 28)"}],"Co":[{"t":"Report exposure to animal control and/or public health authorities; CDC/health department assistance"}]},"name":"Rabies post-exposure prophylaxis (not previously immunized)","level":"III","imp":"Animal bite / possible rabies exposure","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله با گزش سگ ولگرد (غیرقابل مشاهده) روی دست.","why":"حیوان ولگرد غیرقابل مشاهده: PEP کامل (HRIG + 4 دوز واکسن)؛ شست‌وی زخم و کزاز."},{"id":"rabies-pep-previously-immunized","o":{"T":[{"t":"Wound cleansing with soap and water; irrigation with 9:1 povidone-iodine solution; tetanus prophylaxis"},{"t":"HRIG should not be administered"},{"t":"Rabies vaccine (HDCV or PCECV) 1.0 mL deltoid area, one dose on days 0 and 3"}],"Co":[{"t":"Notify public health authorities"}]},"name":"Rabies exposure, previously immunized","level":"III","imp":"Animal bite / rabies exposure (previously immunized)","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"دامپزشک ۳۵ ساله با پیش‌ایمن‌سازی و گزش حیوان مشکوک.","why":"قبلاً ایمن‌شده: HRIG نمی‌خواهد؛ دو دوز واکسن."},{"id":"rabies-clinical","o":{"L":[{"t":"Antigen and antibody testing of serum, cerebrospinal fluid, saliva and/or tissue biopsies (CSF mononuclear pleocytosis)"}],"T":[{"t":"Supportive care in a critical care environment (no specific therapy with demonstrated clinical benefit); treat complications"}],"Co":[{"t":"Critical care admission; notify public health"}]},"name":"Clinical rabies encephalitis","level":"I","imp":"Clinical rabies (encephalitis)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: if SpO2 < 94%, F.M 6–10 L/min or N.C 3–5 L/min; critical care","sc":"مردی ۴۵ ساله با گزش خفاش ۲ ماه پیش، تحریک‌پذیری، هیدروفوبی و ترشح بزاق.","why":"بدون درمان اختصاصی؛ مراقبت حمایتی در ICU و آزمایش تشخیصی."}],"ch":"94","name":"Rabies: exposure assessment, post-exposure prophylaxis and clinical rabies","name_fa":"هاری: ارزیابی مواجهه، پروفیلاکسی پس از مواجهه و هاری بالینی","cc":["wound-bite"],"keywords":"rabies, post-exposure prophylaxis, human rabies immunoglobulin, HRIG, rabies vaccine, bat exposure, animal bite, hydrophobia, هاری, واکسن هاری","status":"draft","features":["هاری: آنسفالیت کشنده؛ انتقال با بزاق حیوان آلوده (گزش یا خراش)؛ بیشتر مراجعات ED برای ارزیابی/درمان پس از گزش یا مواجهه؛ در آمریکا: سگ، گربه، خفاش؛ حیوانات اصلی: راکون، خفاش، سینه‌سیاه (skunk)، روباه، گربه، سگ، گاو؛ فرت، خرگوش، خوکچه هندی و سنجاب معمولاً منتقل نمی‌کنند (ریسک بسیار پایین؛ مشاوره بهداشت محلی)","نهفتگی 20 تا 90 روز (4 روز تا 6 سال): پروفیلاکسی بدون توجه به فاصله زمانی","پرودروم 2 تا 10 روز: ناخوشی، بی‌حالی، سردرد، تب، تهوع، استفراغ، اضطراب، درد/پارستزی محل گزش؛ آنسفالیتیک (80٪): تحریک‌پذیری دوره‌ای، گیجی، توهم، رفتار عجیب، اختلال اتونوم، ترشح بزاق، هیپرترمی، تاکی‌کاردی، آریتمی، هیدروفوبی و اسپاسم حلق؛ فلجی (20٪): ضعف پیشرونده اندام و فلج دوطرفه صورت؛ کما ظرف 10 روز؛ تقریباً همیشه کشنده","تشخیص بالینی: آنسفالیت پیشرونده سریع با ناپایداری اتونوم، دیسفاژی، هیدروفوبی؛ پس از علائم: آنتی‌ژن/آنتی‌بادی سرم، CSF، بزاق یا بیوپسی؛ CSF پلئوسیتوز مونونوکلئر؛ تشخیص نهایی پس از مرگ"],"ddx":[{"n":"Tetanus |","cm":1},{"n":"Viral encephalitis (HSV, arboviral) |","cm":1},{"n":"Rabies exposure vs low-risk animal (ferret, rabbit, squirrel) |"},{"n":"Psychiatric / toxic delirium |"}],"redflags":["هیدروفوبی، اسپاسم حلق، آنسفالیت پیشرونده، گزش حیوان وحشی بدون مشاهده"],"guide":"هاری بالینی: درمان حمایتی در ICU؛ درمان اختصاصی ندارد. مواجهه: ارزیابی همه گزیده/خراشیده/مواجهه با بزاق حیوان وحشی یا اهلی احتمالی هار. خفاش: PEP در تماس مستقیم مگر اطمینان کامل از عدم گزش/خراش/مخاط؛ در اتاق مشترک بدون آگاهی: در نظر گرفتن PEP؛ ارسال خفاش برای آزمایش (منفی = PEP لازم نیست). حیوان اهلی سالم قابل مشاهده: PEP فوری لازم نیست (محبوس و مشاهده 10 روزه؛ مشورت بهداشت). حیوان ولگرد/وحشی با سابقه ایمنی نامعلوم و غیرقابل مشاهده: شروع PEP؛ گزارش به کنترل حیوانات/بهداشت. زخم: واکسن کزاز، شست‌وی با آب و صابون، شست‌وی با povidone-iodine رقیق (1 mL در 9 mL آب/نرمال سالین)، آنتی‌بیوتیک در صورت لزوم و پروفیلاکسی هاری.\n# PEP (آمریکا 2010، جدول 94-2)\nایمن‌نشده قبلی: شست‌وی زخم؛ HRIG 20 IU/kg وزن واقعی (تا حد امکان انفیلتراسیون دور زخم و باقیمانده IM در محل دور از واکسن؛ هرگز در یک سرنگ با واکسن؛ بیش از دوز توصیه‌شده ندهید)؛ واکسن HDCV یا PCECV 1.0 mL ناحیه دلتوئید (نه گلوتئال؛ ران قدامی-خارجی در کودک کوچک) روز 0، 3، 7 و 14 (ایمنوساپرس: دوز پنجم روز 28). ایمن‌شده قبلی: شست‌وی زخم؛ HRIG ندهید؛ واکسن 1.0 mL روز 0 و 3.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 94: Tetanus and Rabies, pp. 517–522"},"malaria":{"id":"malaria","variants":[{"id":"malaria-uncomplicated-falciparum","o":{"L":[{"t":"Thick and thin blood films (repeat at least twice daily, preferably during febrile episodes, if initially negative and malaria suspected); rapid diagnostic test; CBC (hemolysis, thrombocytopenia), blood glucose, liver and renal function"}],"A":[{"t":"Artemether-lumefantrine (each tablet artemether 20 mg and lumefantrine 120 mg) 4 tablets twice daily for 3 days (first two doses about 8 h apart)"},{"t":"Alternatives to ACT: Atovaquone-proguanil (adult tablet atovaquone 250 mg/proguanil 100 mg) 4 tablets once daily for 3 days; or Quinine sulfate 650 mg PO every 8 h for 3–7 days plus Doxycycline 100 mg PO every 12 h for 7 days (or Clindamycin 7 mg/kg PO every 8 h for 7 days)"},{"t":"Chloroquine for P. falciparum from areas of low chloroquine resistance (Central America west of the Panama Canal, Haiti, Dominican Republic, parts of the Middle East)","fl":[{"k":"note","v":"dose options on CDC website"}]}],"Co":[{"t":"Admit; infectious disease; CDC malaria hotline 770-488-7788"}]},"name":"Uncomplicated falciparum malaria","level":"II","imp":"Uncomplicated Plasmodium falciparum malaria","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۳۵ ساله از آفریقا با تب و لرز دوره‌ای؛ اسمیر ضخیم P. falciparum؛ بدون علامت شدت.","why":"falciparum بدون عارضه: بستری و ACT؛ تکرار اسمیر در صورت منفی."},{"id":"malaria-vivax-ovale-malariae","o":{"L":[{"t":"Thick and thin blood films; G6PD level before primaquine","fl":[{"k":"note","v":"G6PD testing not specified; primaquine avoided in G6PD deficiency"}]}],"A":[{"t":"Chloroquine adults: 600 mg base (= 1 g salt) loading dose, then 300 mg base (= 500 mg salt) in 6 hours, then 300 mg base per day for 2 days (total 1550 mg base); children: 10 mg/kg base (maximum 600 mg) loading dose, then 5 mg/kg base in 6 hours and 5 mg/kg base per day for 2 days"},{"t":"Primaquine phosphate 30 mg of base per day for 14 days (children 0.5 mg/kg base for 14 days) after full recovery, to eradicate liver forms of P. vivax / P. ovale","fl":[{"k":"ci","v":"avoid in G6PD deficiency (hemolysis)"}]}],"Co":[{"t":"Outpatient treatment often acceptable (P. knowlesi: admit)"}]},"name":"Uncomplicated vivax / ovale / malariae / knowlesi malaria","level":"III","imp":"Uncomplicated Plasmodium vivax / ovale / malariae malaria","cond":"Urgent","act":"RBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۳۰ ساله از هند با تب سه‌روزه دوره‌ای؛ P. vivax؛ پایدار.","why":"chloroquine؛ primaquine برای hypnozoite بعد از بهبود با بررسی G6PD؛ knowlesi: بستری."},{"id":"malaria-severe","o":{"L":[{"t":"Thick and thin blood films (percentage of infected red cells correlates with prognosis); blood glucose (monitor), CBC, renal function, lactate / blood gas, coagulation"}],"S":[{"t":"Appropriate IV fluid replacement; correction of metabolic derangements","fl":[{"k":"ci","v":"caution in pulmonary edema / ARDS"}]}],"A":[{"t":"Artesunate 2.4 mg/kg IV at 0, 8 and 24 h, then daily (can be given IM if necessary) (available from CDC if quinidine fails: 770-488-7788)"},{"t":"Or Quinidine gluconate 6.25 mg base (= 10 mg salt)/kg IV load over 2 h (maximum 600 mg) followed by 0.0125 mg base/kg/min continuous infusion plus Doxycycline 2.2 mg/kg IV (up to 100 mg) every 12 h for 7 days (or children < 8 years Clindamycin 10 mg base/kg IV loading dose then 5 mg base/kg IV every 8 h for 7 days)","fl":[{"k":"ci","v":"quinidine/quinine cause severe hypoglycemia and are myocardial depressants, contraindicated in heart disease; cardiac monitoring"}]},{"t":"Alternative to quinidine: Quinine dihydrochloride 20 mg (salt)/kg IV over 2–4 hours, then 10 mg/kg every 8 hours"}],"T":[{"t":"Continue parenteral treatment for at least 24 hours; advanced support (dialysis, mechanical ventilation) as necessary"}],"Co":[{"t":"ICU admission; CDC hotline 770-488-7788 (770-488-7100 after hours)"}]},"name":"Severe or complicated malaria (cerebral malaria)","level":"I","imp":"Severe (complicated) malaria","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"O2 therapy: F.M 6–10 L/min or N.C 3–5 L/min if SpO2 < 94%","sc":"مردی ۴۰ ساله بازگشته از آفریقا با تب، کما، تشنج، Hb 5 و قند 30.","why":"مالاریای شدید: artesunate وریدی؛ قند خون؛ حمایت تهاجمی."}],"ch":"95","name":"Malaria","name_fa":"مالاریا","cc":["fever","altered-mental-status"],"keywords":"malaria, Plasmodium falciparum, Plasmodium vivax, artemether-lumefantrine, chloroquine, primaquine, artesunate, quinidine, cerebral malaria, thick blood film, مالاریا","status":"draft","features":["بیماری تک‌یاخته‌ای از نیش پشه Anopheles؛ پنج گونه: P. falciparum، P. vivax، P. ovale، P. malariae و P. knowlesi؛ مسافر اخیر از مناطق آندمیک با تب بی‌توضیح؛ > 50٪ موارد آمریکا از جنوب صحرای آفریقا؛ مقاومت P. falciparum به کلروکین و داروهای دیگر","دوره نهفتگی 1 تا 4 هفته (ممکن است ماه‌ها تا سال‌ها با پروفیلاکسی نسبی)؛ اولیه: ناخوشی، تب، لرز، میالژی و سردرد؛ سپس تب بالا با تعریق و خستگی؛ سیکل‌های منظم؛ vivax و ovale: hypnozoite نهفته و عود","معاینه: بیمار حاد، تب بالا، تاکی‌کاردی و تاکی‌پنه؛ اسپلنومگالی و تندرنس شکم؛ falciparum: هپاتومگالی، ادم و ایکتر؛ همولیز، آنمی، پارگی طحال","شدید (معمولاً falciparum): بی‌حالی، آنمی شدید، اسیدوز، هیپوگلیسمی، نارسایی کلیه، ARDS، ادم ریه، ایکتر، شوک، DIC؛ مالاریای مغزی: خواب‌آلودگی، کما، دلیریوم، تشنج؛ blackwater fever: همولیز داخل عروقی، هموگلوبینوری و نارسایی کلیه","تشخیص: سابقه مواجهه، علائم و اسمیر ضخیم و نازک خون (نازک برای شمارش پارازیتمی بالا؛ ضخیم برای کم)؛ ممکن است پارازیتمی اوایل غیرقابل‌تشخیص؛ در شک تکرار حداقل دو بار در روز (ترجیحاً در تب)؛ تست سریع حساس برای falciparum با پارازیتمی بالا و ضعیف برای بقیه","آزمایش: آنمی نرموکروم نرموسیتیک با همولیز، WBC نرمال یا کم، ترومبوسیتوپنی، ESR بالا، اختلال خفیف کبد و کلیه"],"ddx":[{"n":"Cerebral malaria / severe falciparum malaria |","cm":1},{"n":"Sepsis / meningitis |","cm":1},{"n":"Dengue / typhoid fever (travelers) |"},{"n":"Influenza / viral hemorrhagic fever |"},{"n":"Hepatitis A |"}],"redflags":["تغییر هوشیاری، آنمی شدید، هیپوگلیسمی، نارسایی کلیه، شوک، پارازیتمی بالا"],"guide":"درمان بر اساس شدت و گونه. falciparum بدون عارضه: بستری؛ ترجیح: ACT (artemether-lumefantrine: 4 قرص دو بار روزانه 3 روز؛ دوز اول و دوم حدود 8 ساعت فاصله؛ artesunate-amodiaquine در دسترس نیست در آمریکا)؛ جایگزین: atovaquone-proguanil (4 قرص بزرگسال روزانه 3 روز)، quinine sulfate 650 mg PO هر 8 ساعت 3 تا 7 روز + doxycycline 100 mg PO هر 12 ساعت 7 روز (یا clindamycin 7 mg/kg PO هر 8 ساعت 7 روز در کودک < 8 سال). CDC: chloroquine برای falciparum از مناطق با مقاومت پایین (آمریکای مرکزی غرب کانال پاناما، هائیتی، دومینیکن، بخشی از خاورمیانه). vivax، malariae، ovale (غیرپیچیده، اغلب سرپایی) و knowlesi (بستری): chloroquine: بزرگسال 600 mg base بار سپس 300 mg base بعد از 6 ساعت و 300 mg base روزانه 2 روز (کل 1550 mg base)؛ کودک 10 mg/kg base (حداکثر 600 mg) بار سپس 5 mg/kg base بعد از 6 ساعت و 5 mg/kg base روزانه 2 روز. primaquine phosphate بعد از بهبود کامل برای hypnozoite (vivax/ovale): بزرگسال 30 mg base روزانه 14 روز؛ کودک 0.5 mg/kg base 14 روز؛ پرهیز در کمبود G6PD (همولیز). شدید: artesunate 2.4 mg/kg IV در 0، 8 و 24 ساعت سپس روزانه (می‌تواند IM)؛ CDC 770-488-7788؛ یا quinidine gluconate 6.25 mg base/kg IV بار طی 2 ساعت (حداکثر 600 mg) سپس 0.0125 mg base/kg/min + doxycycline 2.2 mg/kg IV هر 12 ساعت 7 روز یا clindamycin 10 mg base/kg بار سپس 5 mg base/kg هر 8 ساعت 7 روز؛ quinine dihydrochloride جایگزین. حداقل 24 ساعت تزریقی؛ قند خون (quinidine/quinine هیپوگلیسمی)؛ ضعیف‌کننده میوکارد (بیماری قلبی ممنوع) و مانیتور قلبی؛ حمایت تهاجمی. خط تلفن CDC: 770-488-7788 (ساعات کاری) و 770-488-7100.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 95: Malaria, pp. 523–526"},"foodborne-waterborne":{"id":"foodborne-waterborne","variants":[{"id":"foodborne-gastroenteritis","o":{"L":[{"t":"Diagnostic testing often not indicated; if acutely ill: stool culture with Gram stain, lactoferrin, electrolytes, CBC; ova and parasite testing only for symptoms > 2 weeks, immunocompromise, community waterborne outbreak, recent travel or men who have sex with men; C. difficile antigen if prolonged symptoms or recent antibiotics"}],"S":[{"t":"Oral rehydration if tolerated; IV normal saline for significant dehydration or continued vomiting","fl":[{"k":"ci","v":"caution in heart failure / CKD"}]}],"T":[{"t":"Metoclopramide 10 mg PO or IV, or Ondansetron 4 PO or IV"},{"t":"Diphenhydramine 25 mg PO or IV for scombroid fish poisoning"},{"t":"Loperamide 4 mg initially, then 2 mg after every unformed stool up to 16 mg per day for mild to moderate nonbloody diarrhea in adults without fever","fl":[{"k":"ci","v":"not with suspected E. coli O157:H7"}]}],"A":[{"t":"Moderate to severe traveler's diarrhea, symptoms > 1 week, hospitalization or immunocompromised: Ciprofloxacin 500 mg PO twice per day for 3 to 5 days, or Levofloxacin 500 mg PO once daily for 3 to 5 days","fl":[{"k":"ci","v":"antibiotics and antimotility agents contraindicated with suspected E. coli O157:H7 (hemolytic uremic syndrome)"}]}],"Co":[{"t":"Admit if toxic appearing, significant dehydration or uncontrolled vomiting, immunocompromised, or extremes of age with significant symptoms"}]},"name":"Food/water-borne gastroenteritis, stable","level":"III","imp":"Foodborne / waterborne gastroenteritis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۸ ساله پس از غذای رستوران با استفراغ، اسهال آبکی و کرامپ؛ چند همراه علائم مشابه؛ بدون تب بالا.","why":"بیشتر خودمحدود؛ ORS و ضدتهوع؛ آنتی‌بیوتیک فقط در اندیکاسیون."},{"id":"waterborne-skin-infection","o":{"L":[{"t":"Cultures of wound / blood","fl":[{"k":"note","v":"not specified in this chapter"}]}],"A":[{"t":"Vibrio vulnificus: Doxycycline 100 mg IV twice per day plus a fourth-generation cephalosporin"},{"t":"Aeromonas: mild Ciprofloxacin 500 mg PO twice per day; severe Ciprofloxacin 400 mg IV twice per day plus IV antipseudomonal penicillin or fourth-generation cephalosporin"},{"t":"Pseudomonas aeruginosa: hot-tub folliculitis usually self-limited; severe infection: Ciprofloxacin 400 mg IV twice per day plus IV antipseudomonal penicillin or fourth-generation cephalosporin"},{"t":"Mycobacterium marinum: Clarithromycin 500 mg PO twice per day or Doxycycline 100 mg PO twice per day for 3 months (severe: combine with rifampin or ethambutol)"}],"T":[{"t":"Tetanus vaccination"}],"Co":[{"t":"Emergent surgical consultation for necrotizing infections (operative debridement)"}]},"name":"Waterborne skin infection (Vibrio, Aeromonas, Pseudomonas, M. marinum)","level":"II","imp":"Waterborne skin infection","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۵۵ ساله الکلی با سلولیت و بول هموراژیک ساق پس از تماس با آب دریا.","why":"V. vulnificus: داکسی‌سایکلین وریدی و سفالوسپورین؛ نکروزان: دبریدمان اورژانس."}],"ch":"96","name":"Foodborne and waterborne illness (gastroenteritis, scombroid and ciguatera poisoning, waterborne skin infections)","name_fa":"بیماری‌های منتقله از غذا و آب (گاستروانتریت، مسمومیت scombroid و ciguatera، عفونت‌های پوستی ناشی از آب)","cc":["nausea-vomiting","diarrhea","rash"],"keywords":"food poisoning, norovirus, Salmonella, scombroid, ciguatera, traveler's diarrhea, loperamide, Vibrio vulnificus, Aeromonas, hot tub folliculitis, Mycobacterium marinum, مسمومیت غذایی","status":"draft","features":["غذای آلوده به باکتری، ویروس، انگل، مواد شیمیایی یا زیست‌سم؛ ویروس‌ها (norovirus > نیمی)، salmonella غیرتیفوئیدی بیشترین بستری و مرگ؛ C. perfringens، Campylobacter، Listeria، Shigella، STEC و S. aureus؛ انگل: Giardia، Toxoplasma، Entamoeba، Cryptosporidium؛ ماهی: scombroid و ciguatera","آب: علائم GI یا پوستی؛ عوامل: مشابه غذایی به‌علاوه Vibrio، Aeromonas، P. aeruginosa، Yersinia، هپاتیت A و mycobacterium غیرتوبرکولوزی؛ شایع‌ترین در طغیان‌های تفریحی Cryptosporidium","علائم: تهوع، استفراغ، اسهال، کرامپ، تب، دهیدراتاسیون و ناخوشی؛ چند نفر با علائم همزمان حمایتی؛ بیماری > 2 هفته: تک‌یاخته؛ STEC: استفراغ، کرامپ، اسهال خونی و تب خفیف و ممکن است HUS (به‌ویژه با آنتی‌بیوتیک)","scombroid و ciguatera: 1 تا 6 ساعت بعد از خوردن؛ scombroid: فلاشینگ و سردرد (هیستامین)؛ ciguatera: سردرد، درد عضله، پارستزی، وارونگی حس گرم و سرد","پوست: سلولیت، پلاک ایندوره دردناک M. marinum، عفونت نکروزان و بول هموراژیک V. vulnificus، Aeromonas (تروما با آب شیرین، زخم بدبو)","الگو (جدول 96-1): استفراغ غالب (ویروسی، S. aureus، B. cereus)؛ اسهال غیرالتهابی (ETEC، Giardia، Vibrio cholera، Cryptosporidium)؛ التهابی (Shigella، Campylobacter، Salmonella، EIEC، STEC، Yersinia، Entamoeba)؛ پایدار > 14 روز (انگل)؛ عصبی (بوتولیسم، scombroid، ciguatera، تترودوتوکسین، قارچ سمی، GBS)؛ سیستمیک (Listeria، Brucella، Salmonella typhi، Vibrio vulnificus، هپاتیت A/E)"],"ddx":[{"n":"Shiga toxin-producing E. coli (hemolytic uremic syndrome) |","cm":1},{"n":"Botulism / toxic mushroom |","cm":1},{"n":"Vibrio vulnificus necrotizing infection |","cm":1},{"n":"Viral gastroenteritis (norovirus) |"},{"n":"Salmonella / Campylobacter / Shigella |"},{"n":"Giardia / Cryptosporidium |"}],"redflags":["ظاهر سمی، دهیدراتاسیون شدید، اسهال خونی با شک STEC، علائم عصبی (بوتولیسم)، بول هموراژیک پس از تماس با آب"],"guide":"آزمایش اغلب لازم نیست؛ بدحال یا تشخیص مهم: کشت مدفوع با Gram، لاکتوفرین، الکترولیت و CBC؛ تست لکوسیت مدفوع حساس/اختصاصی نیست؛ ova و parasite برای علائم > 2 هفته، ایمنوساپرس، طغیان آب جامعه، سفر یا MSM؛ C. difficile در علائم طولانی، آنتی‌بیوتیک اخیر. حمایتی: ORS اگر تحمل شود؛ NS وریدی در دهیدراتاسیون قابل‌توجه یا استفراغ ادامه‌دار؛ ضدتهوع: metoclopramide 10 mg PO/IV یا ondansetron 4 PO/IV؛ diphenhydramine 25 mg PO/IV برای scombroid؛ loperamide 4 mg ابتدا سپس 2 mg پس از هر مدفوع نرم (حداکثر 16 mg/day) در اسهال خفیف تا متوسط غیرخونی و بدون تب؛ آنتی‌بیوتیک در مسافران متوسط تا شدید، > 1 هفته، بستری و ایمنوساپرس: ciprofloxacin 500 mg PO دو بار روزانه 3 تا 5 روز یا levofloxacin 500 mg PO روزانه 3 تا 5 روز؛ ممنوع آنتی‌بیوتیک/ضدحرکت در شک O157:H7. پوست (جدول 96-2): V. vulnificus: doxycycline 100 mg IV دو بار روزانه + سفالوسپورین نسل 4؛ نکروزان: دبریدمان اورژانس. Aeromonas: خفیف: ciprofloxacin 500 mg PO دو بار روزانه؛ شدید: ciprofloxacin 400 mg IV دو بار روزانه + پنی‌سیلین ضد-Pseudomonas یا سفالوسپورین نسل 4. Pseudomonas: hot-tub folliculitis خودمحدود؛ شدید: ciprofloxacin 400 mg IV + پنی‌سیلین ضد-Pseudomonas. M. marinum: clarithromycin 500 mg PO دو بار روزانه یا doxycycline 100 mg PO دو بار روزانه 3 ماه؛ شدید + rifampin یا ethambutol. کزاز پروفیلاکسی. بستری: ظاهر سمی، دهیدراتاسیون قابل‌توجه یا استفراغ کنترل‌نشده، ایمنوساپرس یا سنین حدی.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 96: Foodborne and Waterborne Diseases, pp. 527–530"},"tick-borne-rmsf-ehrlichiosis":{"id":"tick-borne-rmsf-ehrlichiosis","variants":[{"id":"rmsf-ehrlichiosis-main","o":{"L":[{"t":"CBC (normal white and red cells, thrombocytopenia), liver function tests, sodium (hyponatremia); peripheral blood smear (ehrlichiosis), PCR; serology (acute and convalescent) or skin biopsy with immunofluorescence for confirmation (outside the ED)"}],"A":[{"t":"Doxycycline 100 mg PO or IV twice a day for 7 days or until 3 days after resolution of fever (some recommend a 200 mg loading dose); children < 45 kg Doxycycline 2.2 mg/kg PO twice a day"},{"t":"Ehrlichiosis: Doxycycline 100 mg PO twice a day until 3 to 5 days after fever resolution (or 10 to 14 days after resolution of CNS symptoms in severe disease); Rifampin 300 mg twice a day for patients with contraindications to doxycycline","fl":[{"k":"ci","v":"doxycycline contraindicated in pregnancy but warranted in life-threatening situations; chloramphenicol 50 mg/kg/d divided in four doses for 7 days is the alternative"}]}],"Co":[{"t":"Admit if toxic; infectious disease"}]},"name":"Suspected Rocky Mountain spotted fever / ehrlichiosis","level":"II","imp":"Suspected Rocky Mountain spotted fever / ehrlichiosis","cond":"Emergent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۴۰ ساله در ژوئن با تب 39.5، سردرد شدید، میالژی و راش پتشیال مچ‌ها و کف دست‌ها؛ گزش کنه 4 روز قبل.","why":"RMSF بالینی است؛ درمان را قبل از تأیید با doxycycline شروع کن."}],"ch":"97","name":"Rocky Mountain spotted fever and ehrlichiosis","name_fa":"تب خال‌دار کوه‌های راکی و ارلیخیوز","cc":["fever","rash","headache"],"keywords":"Rocky Mountain spotted fever, RMSF, Rickettsia rickettsii, ehrlichiosis, tick bite, doxycycline, petechial rash palms soles, تب خالدار","status":"draft","features":["RMSF: بیماری منتقله با کنه (R. rickettsii)؛ ناقل‌ها: Dermacentor variabilis، D. andersoni، Rhipicephalus sanguineus؛ آوریل تا سپتامبر با اوج ژوئن/ژوئیه؛ > 60٪ از پنج ایالت (NC، TN، OK، MO، AR)","اولیه: تب، سردرد، میالژی، ناخوشی؛ لنفادنوپاتی، تهوع، استفراغ، اسهال؛ کودکان: درد شکم و ادم؛ دیررس: مننژیت، آنسفالیت، نارسایی کلیه/تنفس، میوکاردیت","تریاد کلاسیک (تب، راش، سابقه کنه) نادر: فقط 50٪ گزش کنه را به یاد می‌آورند و راش در 10٪ غایب؛ راش 2 تا 4 روز بعد از تب: ماکولوپاپولار، سپس پتشیال؛ مچ پا و مچ دست سپس مرکزگرا؛ معمولاً صورت سالم؛ کف دست و پا","تشخیص بالینی (تأیید پس از شروع درمان)؛ در بیمار تب‌دار با سردرد از منطقه آندمیک در بهار/تابستان؛ ترکیب WBC و RBC نرمال، ترومبوسیتوپنی، آنزیم کبد بالا و هیپوناترمی؛ تأیید: افزایش تیتر یا بیوپسی پوست با ایمونوفلورسانس","افتراق: ویروسی، پنومونی، منینگوکوکسمی، ارلیخیوز، Kawasaki، TSS، مخملک، لپتوسپیروز","ارلیخیوز: Ehrlichia (کوکوباسیل گرم‌منفی در لکوسیت‌ها)؛ کنه lone star (Amblyomma americanum) و گوزن دم‌سفید؛ 1 تا 2 هفته بعد از گزش؛ تب (97٪)، سردرد، ناخوشی، تهوع، استفراغ، اسهال، درد شکم و آرترالژی؛ راش متغیر و غیرشایع؛ اقلیت: نارسایی کلیه/تنفس و آنسفالیت؛ آزمایش: لکوپنی، ترومبوسیتوپنی، آنزیم کبد بالا؛ هفته اول اسمیر ممکن است 20٪ مثبت؛ PCR اختصاصی ولی حساسیت کم؛ افزایش تیتر؛ استاندارد طلایی: IFA"],"ddx":[{"n":"Meningococcemia |","cm":1},{"n":"Toxic shock syndrome / sepsis |","cm":1},{"n":"Ehrlichiosis / anaplasmosis / Lyme disease |"},{"n":"Kawasaki disease / viral illness |"},{"n":"Leptospirosis / typhoid / malaria |"}],"redflags":["راش پتشیال کف دست/پا با تب، تغییر هوشیاری، شوک"],"guide":"RMSF بزرگسال: doxycycline 100 mg PO/IV دو بار روزانه (برخی بار 200 mg)، 7 روز یا تا 3 روز بعد از رفع تب (جدول 97-2: 7 روز یا تا 2 روز بعد از نرمال شدن دما). کودک < 45 kg: doxycycline 2.2 mg/kg PO دو بار روزانه؛ AAP و CDC آن را درمان انتخابی ریکتزیوز در همه سنین می‌دانند. حاملگی: doxycycline در موارد تهدیدکننده حیات موجه؛ جایگزین chloramphenicol 50 mg/kg/d در چهار دوز 7 روز (سمی و مشکل‌ساز). ارلیخیوز: doxycycline 100 mg PO دو بار روزانه (2.2 mg/kg دو بار روزانه برای < 45 kg) برای همه سنین؛ تا 3 تا 5 روز بعد از رفع تب یا 10 تا 14 روز بعد از رفع علائم CNS در شدید؛ rifampin 300 mg دو بار روزانه در موارد ممنوعیت doxycycline.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 97: Zoonotic Infections, pp. 531–539"},"lyme-disease":{"id":"lyme-disease","variants":[{"id":"lyme-early","o":{"L":[{"t":"Clinical diagnosis (erythema migrans); PCR, polyvalent fluorescence immunoassay or Western immunoblot for confirmation"}],"A":[{"t":"Doxycycline 100 mg PO twice a day (children < 45 kg 2.2 mg/kg twice daily), or Amoxicillin 500 mg PO three times a day (children 50 mg/kg/d divided three times a day), or Cefuroxime 500 mg PO twice a day (children 30 mg/kg/d divided three times a day) for 14 to 21 days"},{"t":"Prophylaxis after deer tick bite (highly endemic area, attachment ≥ 36 hours, within 72 hours of removal): single dose Doxycycline 200 mg (children ≥ 8 years 4 mg/kg)"}]},"name":"Early Lyme disease (erythema migrans, mild)","level":"III","imp":"Early Lyme disease","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۵ ساله در ژوئیه با پلاک حلقوی قرمز بزرگ با پاکسازی مرکزی روی ران و خستگی.","why":"Lyme اولیه با doxycycline یا amoxicillin 14 تا 21 روز."},{"id":"lyme-severe-neuro-cardiac","o":{"L":[{"t":"Lumbar puncture if meningitis suspected ; serology / PCR for confirmation","fl":[{"k":"note","v":"not specified in this chapter"}]}],"A":[{"t":"Ceftriaxone 2 g IV daily (children 50 to 75 mg/kg daily) for 14 to 30 days"}],"T":[{"t":"Cardiac monitoring; temporary pacemaker may be required for high-degree AV block"}],"Co":[{"t":"Admit; cardiology / infectious disease"}]},"name":"Lyme disease with meningitis, radiculopathy or high-degree heart block","level":"I","imp":"Lyme neuroborreliosis / Lyme carditis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"مردی ۴۵ ساله با Lyme، فلج دوطرفه صورت و بلوک AV درجه 3.","why":"شدید: ceftriaxone وریدی؛ مانیتور قلبی و پیس‌میکر موقت در صورت نیاز."}],"ch":"97","name":"Lyme disease","name_fa":"بیماری لایم","cc":["rash","fever","joint-limb-pain"],"keywords":"Lyme disease, Borrelia burgdorferi, erythema migrans, facial nerve palsy, heart block, doxycycline, ceftriaxone, tick prophylaxis, لایم","status":"draft","features":["شایع‌ترین عفونت زئونوز منتقله با ناقل در آمریکا؛ Borrelia burgdorferi و کنه Ixodes؛ احتمال انتقال حدود 3٪ در مناطق بسیار آندمیک؛ ریسک ناچیز اگر چسبندگی < 36 ساعت؛ 95٪ از 13 ایالت شمال‌شرق و میدوست شمالی؛ اوج مه تا اوت","مرحله 1 (موضعی زودرس): erythema migrans (60٪ تا 80٪؛ 2 تا 30 روز؛ پلاک اریتماتو با پاکسازی مرکزی)؛ خستگی، سردرد، تب، سفتی گردن، میالژی، آرترالژی، آدنوپاتی","مرحله 2 (منتشر زودرس): چند روز تا 6 ماه؛ ضایعات آنولار هدف‌مانند متعدد، تب، آدنوپاتی، نوروپاتی (15٪ عصبی: نوریت کرانیال → فلج دوطرفه عصب صورت؛ سردرد، سفتی گردن، آتاکسی مخچه‌ای، میلیت، آنسفالیت)، آرتریت اولیگوآرتیکولار مفاصل بزرگ، قلبی 8٪: میوپریکاردیت یا بلوک AV (گاهی پیس‌میکر موقت)","مرحله 3 (منتشر دیررس): ماه‌ها تا سال‌ها: آرتریت مزمن، میوکاردیت، انسفالوپاتی تحت‌حاد، پلی‌نوروپاتی آکسونال","تشخیص بالینی؛ تأیید: PCR، ایمونواسی فلورسانس، immunoblot؛ افتراق: STARI، سلولیت، EM، tinea، مننژیت، آنسفالیت، تب روماتیسمی، آرتریت سپتیک، اندوکاردیت"],"ddx":[{"n":"Lyme carditis (AV block) |","cm":1},{"n":"Lyme meningitis / facial nerve palsy |","cm":1},{"n":"Cellulitis / tinea corporis |"},{"n":"Septic arthritis / rheumatic fever |"},{"n":"Erythema multiforme / STARI |"}],"redflags":["بلوک AV، فلج صورت دوطرفه، مننژیت"],"guide":"مرحله اولیه یا ثانویه خفیف: 14 تا 21 روز doxycycline 100 mg PO دو بار روزانه (کودک < 45 kg 2.2 mg/kg دو بار روزانه)، amoxicillin 500 mg PO سه بار روزانه (کودک 50 mg/kg/d در سه دوز) یا cefuroxime 500 mg PO دو بار روزانه (کودک 30 mg/kg/d در سه دوز)؛ ماکرولیدها کمتر مؤثر. شدید، مننژیت، رادیکولوپاتی یا بلوک قلبی درجه بالا: ceftriaxone 2 g IV روزانه (کودک 50 تا 75 mg/kg روزانه) 14 تا 30 روز. پروفیلاکسی روتین پس از گزش توصیه نمی‌شود؛ یک دوز doxycycline 200 mg (کودک ≥ 8 سال 4 mg/kg) برای گزش کنه گوزن در منطقه بسیار آندمیک اگر اتصال ≥ 36 ساعت و ظرف 72 ساعت پس از برداشتن کنه.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 97: Zoonotic Infections, pp. 531–539"},"tularemia-anthrax-plague":{"id":"tularemia-anthrax-plague","variants":[{"id":"tularemia-main","o":{"L":[{"t":"Culture, direct fluorescent antibody or PCR from skin lesion swab, lymph node sampling or sputum"}],"A":[{"t":"Adults: Streptomycin 1 g IM twice a day, or Gentamicin 5 mg/kg/d IM or IV divided every 8 hours, for 10 days; children: Streptomycin 15 mg/kg IM twice a day (maximum 2 g/d) or Gentamicin 2.5 mg/kg IM/IV two or three times a day for 10 days","fl":[{"k":"renal","v":"aminoglycoside"}]},{"t":"Mild disease in adults: Ciprofloxacin 750 mg PO twice a day or Doxycycline 100 mg PO twice a day for 21 days"}],"Co":[{"t":"Admit if severe; infectious disease"}]},"name":"Tularemia","level":"II","imp":"Tularemia","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"PA","sc":"شکارچی ۴۵ ساله پس از پوست‌کنی خرگوش با زخم انگشت، لنفادنوپاتی دردناک زیربغل و تب.","why":"اولسروگلاندولار: آمینوگلیکوزید؛ خفیف: سیپروفلوکساسین یا داکسی‌سایکلین."},{"id":"anthrax-cutaneous","o":{"L":[{"t":"Gram stain, direct fluorescent antibody or culture of skin lesions or vesicle fluid; blood cultures"}],"A":[{"t":"Ciprofloxacin 500 mg PO every 12 hours or Doxycycline 100 mg PO every 12 hours: 7 to 10 days if naturally acquired from animals; 60 days for bioterrorism-related cases"}],"Co":[{"t":"Notify public health; infectious disease"}]},"name":"Cutaneous anthrax","level":"III","imp":"Cutaneous anthrax","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کارگر پشم ۴۰ ساله با اسکار سیاه بدون درد روی انگشت و ادم اطراف.","why":"پوستی بدون سیستمیک: سیپروفلوکساسین یا داکسی‌سایکلین؛ 60 روز اگر بیوتروریسم."},{"id":"anthrax-systemic","o":{"I":[{"t":"Chest radiograph (mediastinal widening/hilar edema); CT chest","fl":[{"k":"note","v":"not specified in this chapter"}]}],"L":[{"t":"Blood cultures; Gram stain / culture / DFA of lesions if present; lumbar puncture if meningitis suspected","fl":[{"k":"note","v":"LP not specified"}]}],"A":[{"t":"Possible or confirmed meningitis: Ciprofloxacin 400 mg IV every 8 hours plus Meropenem 2 g every 8 hours plus Linezolid 600 mg every 12 hours; consider one-time Raxibacumab 40 mg/kg diluted infusion over 2.25 hours"},{"t":"Meningitis excluded: Ciprofloxacin 400 mg IV every 8 hours plus Clindamycin 900 mg every 8 hours or Linezolid 600 mg every 12 hours"}],"Co":[{"t":"Infectious disease; public health notification; ICU"}]},"name":"Systemic / inhalational anthrax","level":"I","imp":"Systemic (inhalational) anthrax","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: F.M 6–10 L/min or N.C 3–5 L/min if SpO2 < 94%","sc":"مردی ۵۰ ساله با تب، سرفه، تنگی نفس پیشرونده و ادم مدیاستن در CXR.","why":"تقریباً همیشه کشنده؛ چند آنتی‌بیوتیک وریدی فوری و raxibacumab."},{"id":"plague-main","o":{"L":[{"t":"Blood culture and culture of suspected sites (do not wait for results to start treatment)"}],"A":[{"t":"Gentamicin 5 mg/kg IM/IV daily or Streptomycin 15 mg/kg (or 1 g) IM twice a day for 10 days; pediatric Gentamicin 2 to 2.5 mg/kg/dose IM/IV every 8 hours"},{"t":"Alternatives: Doxycycline 100 mg IV twice a day (or 200 mg IV daily), Ciprofloxacin 400 mg IV twice a day, or Chloramphenicol 25 mg/kg IV every 6 hours for 10 days"}],"T":[{"t":"Respiratory droplet isolation for pneumonic plague"}],"Co":[{"t":"ICU; infectious disease; public health notification"}]},"name":"Bubonic / pneumonic plague","level":"I","imp":"Plague (bubonic / pneumonic)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","o2":"O2 therapy: F.M 6–10 L/min or N.C 3–5 L/min if SpO2 < 94%; droplet isolation (pneumonic)","sc":"مردی ۴۰ ساله از جنوب‌غرب پس از تماس با سنجاب مرده با تب، سردرد و غده کشاله ران دردناک و چرکی؛ یا با سرفه و شوک.","why":"درمان را بدون انتظار کشت شروع کن؛ پنومونیک مسری است."}],"ch":"97","name":"Tularemia, anthrax and plague","name_fa":"تولارمی، سیاه‌زخم (آنتراکس) و طاعون","cc":["fever","rash","wound-bite"],"keywords":"tularemia, Francisella tularensis, anthrax, Bacillus anthracis, cutaneous anthrax, inhalational anthrax, raxibacumab, plague, Yersinia pestis, bubo, streptomycin, gentamicin, ciprofloxacin, تولارمی, سیاه زخم, طاعون","status":"draft","features":["تولارمی (F. tularensis): کنه Dermacentor/Amblyomma؛ مخزن: خرگوش، شاه‌بلوط‌خوار و گوزن؛ گزش کنه/مگس، استنشاق، تلقیح پوست/مخاط؛ اولسروگلاندولار شایع‌ترین: ضایعه ماکولوپاپولار زخمی شده در محل + لنفادنوپاتی دردناک و علائم سیستمیک؛ گلاندولار: لنفادنوپاتی بدون زخم؛ تیفوئیدی: بیشترین عارضه (تب، لرز، سردرد، درد شکم)؛ چشمی-اوروفارنژیال و پنومونیک از ذرات هوا؛ تشخیص: کشت، DFA یا PCR از ضایعه/غده/خلط","آنتراکس (B. anthracis): استنشاق اسپور، پوست آسیب‌دیده، گزش آرتروپود (کک) یا خوردن گوشت ناکافی پخته؛ استنشاقی: مدیاستینیت (نه پنومونی واقعی) تقریباً همیشه کشنده: ابتدا شبه‌آنفلوانزا، طی 2 تا 3 روز ادم مدیاستن/هیل و نارسایی تنفس؛ پوستی (95٪): ماکول خارش‌دار (معمولاً انگشت) → زخم با وزیکول سروزی خونی → اسکار سیاه بدون درد که ظرف 2 هفته می‌افتد؛ اقلیت: باکتریمی سریع‌الکشنده؛ تشخیص: Gram، DFA، کشت ضایعه/وزیکول؛ کشت خون","طاعون (Y. pestis): سنجاب سنگ و جوندگان جنوب‌غرب؛ کک؛ گزش، خوردن حیوان آلوده یا ترشحات؛ اسکار محل گزش سپس bubo (غدد پروگزیمال چرکی)؛ بوبونیک: تب، سردرد، bubo؛ پنومونیک: سرفه، لرز، تنگی نفس و شوک و بسیار مسری (قطره‌ای)؛ تشخیص بالینی؛ درمان بدون انتظار کشت"],"ddx":[{"n":"Inhalational anthrax / pneumonic plague |","cm":1},{"n":"Sepsis |","cm":1},{"n":"Influenza / tuberculosis / mediastinitis |"},{"n":"Cutaneous anthrax vs spider bite / ecthyma gangrenosum / tularemia |"},{"n":"Pyogenic infection / syphilis / lymphogranuloma venereum |"}],"redflags":["ادم مدیاستن/هیل با نارسایی تنفس، پنومونی همراه خون‌ریزی و شوک (پنومونیک)، سابقه مواجهه شغلی/بیوتروریسم"],"guide":"# تولارمی\nبزرگسال: streptomycin 1 g IM دو بار روزانه یا gentamicin 5 mg/kg/d IM/IV تقسیم هر 8 ساعت 10 روز؛ کودک: streptomycin 15 mg/kg IM دو بار روزانه (حداکثر 2 g/d) یا gentamicin 2.5 mg/kg IM/IV دو یا سه بار روزانه 10 روز؛ خفیف بزرگسال: ciprofloxacin 750 mg PO دو بار روزانه یا doxycycline 100 mg PO دو بار روزانه 21 روز.\n# آنتراکس\nسیستمیک با مننژیت محتمل/قطعی: ciprofloxacin 400 mg IV هر 8 ساعت + meropenem 2 g هر 8 ساعت + linezolid 600 mg هر 12 ساعت؛ در نظر گرفتن raxibacumab 40 mg/kg طی 2.25 ساعت؛ سیستمیک بدون مننژیت: ciprofloxacin 400 mg IV هر 8 ساعت + clindamycin 900 mg هر 8 ساعت یا linezolid 600 mg هر 12 ساعت؛ مشاوره عفونی. پوستی بدون درگیری سیستمیک: ciprofloxacin 500 mg PO هر 12 ساعت یا doxycycline 100 mg PO هر 12 ساعت: 7 تا 10 روز (طبیعی) و 60 روز (بیوتروریسم). پروفیلاکسی: 60 روز آنتی‌بیوتیک + سه دوز واکسن.\n# طاعون\ngentamicin 5 mg/kg IM/IV روزانه یا streptomycin 15 mg/kg (یا 1 g) IM دو بار روزانه 10 روز؛ کودک: gentamicin 2 تا 2.5 mg/kg/dose هر 8 ساعت؛ جایگزین: doxycycline 100 mg IV دو بار روزانه (یا 200 mg روزانه)، ciprofloxacin 400 mg IV دو بار روزانه یا chloramphenicol 25 mg/kg IV هر 6 ساعت 10 روز.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 97: Zoonotic Infections, pp. 531–539"},"zoonotic-systemic-other":{"id":"zoonotic-systemic-other","variants":[{"id":"zoonoses-other-main","o":{"L":[{"t":"Blood cultures; serologic testing (brucellosis, psittacosis, Q fever, leptospirosis: darkfield microscopy of body fluids); wound culture for bite infections; PCR"}],"A":[{"t":"Q fever (Coxiella burnetii): Doxycycline (possible alternative: fluoroquinolone or macrolide)","fl":[{"k":"note","v":"dose not given in the book"}]},{"t":"Psittacosis: Doxycycline; alternatives Azithromycin and Levofloxacin","fl":[{"k":"note","v":"doses not given in the book"}]},{"t":"Brucellosis: Doxycycline plus gentamicin or rifampin (children TMP-SMX plus gentamicin)","fl":[{"k":"note","v":"doses not given in the book"}]},{"t":"Capnocytophaga: Amoxicillin-clavulanate or clindamycin; shock: piperacillin-tazobactam or carbapenem plus clindamycin / vancomycin"},{"t":"Leptospirosis: Penicillin G IV (alternative Ceftriaxone IV); mild disease oral Doxycycline or Amoxicillin or Azithromycin"},{"t":"Tick-borne relapsing fever: Doxycycline 100 mg PO/IV twice a day for 7–10 days (alternative Erythromycin 500 mg PO/IV four times a day); Babesiosis: Atovaquone 750 mg PO every 12 h plus Azithromycin 500 mg PO on day 1 then 250–1000 mg daily for 10 days (severe: Clindamycin 1200 mg IV twice a day plus Quinine 650 mg PO three times a day for 7–10 days)"}],"Co":[{"t":"Infectious disease; public health notification as indicated"}]},"name":"Suspected systemic zoonotic infection","level":"II","imp":"Suspected systemic zoonotic infection","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مردی ۳۸ ساله دامدار با تب، سردرد، میالژی و پنومونی بعد از زایمان گوسفندان.","why":"تب Q: doxycycline؛ سایر زئونوزها بر اساس مواجهه."}],"ch":"97","name":"Other systemic zoonoses (brucellosis, Capnocytophaga, psittacosis, Q fever, leptospirosis, Salmonella, Streptococcus iniae)","name_fa":"سایر زئونوزهای سیستمیک (بروسلوز، Capnocytophaga، پسیتاکوز، تب Q، لپتوسپیروز، سالمونلا، Streptococcus iniae)","cc":["fever","wound-bite"],"keywords":"brucellosis, Capnocytophaga, psittacosis, Q fever, Coxiella burnetii, leptospirosis, zoonosis, babesiosis, relapsing fever, Colorado tick fever, بروسلوز, لپتوسپیروز","status":"draft","features":["زئونوز: انتقال طبیعی بین حیوانات مهره‌دار و انسان؛ تماس مستقیم، خوردن غذا/آب آلوده، استنشاق یا ناقل آرتروپود (اغلب کنه)؛ تشخیص دشوار (تب، سردرد، میالژی مشابه بسیاری بیماری‌ها)؛ در بیمار با بیماری شبه‌ویروسی و خطر شغلی یا جغرافیایی در نظر بگیر","جدول 97-1: Aeromonas (ماهی/خزندگان): سلولیت کرپیتانت و گاستروانتریت (فصل ۹۶)؛ Brucella canis (سگ): تب غیراختصاصی؛ سرولوژی/کشت خون؛ doxycycline + gentamicin یا rifampin (کودک: TMP-SMX + gentamicin)؛ Capnocytophaga (سگ/گربه): تب، شوک سپتیک و مننژیت پس از گزش؛ کشت؛ amoxicillin-clavulanate یا clindamycin؛ شوک: pip-tazo یا کارباپنم + clindamycin/vancomycin؛ Chlamydophila psittaci (پرندگان): شبه‌آنفلوانزا، پنومونی، اندوکاردیت؛ doxycycline (جایگزین azithromycin و levofloxacin)؛ Coxiella burnetii (گاو، گوسفند، بز): تب، پنومونی، هپاتیت، مننژیت، اندوکاردیت؛ doxycycline؛ Leptospira (پرندگان، سگ، جوندگان): تب، سپسیس، مننژیت، پنومونی، هپاتیت، راش؛ darkfield و سرولوژی؛ penicillin G IV یا ceftriaxone IV (خفیف: doxycycline خوراکی یا amoxicillin یا azithromycin)؛ Salmonella enterica (سگ، گربه، خزندگان): تب، اسهال، درد شکم، سپسیس؛ کشت خون/مدفوع؛ فلوروکینولون یا سفالوسپورین نسل 3؛ Streptococcus iniae (ماهی/غذاهای دریایی): سلولیت؛ کشت؛ β-لاکتام (به‌جز aztreonam)","سایر بیماری‌های کنه‌ای (جدول 97-2): تب راجعه کنه‌ای: doxycycline 100 mg PO/IV دو بار روزانه 7 تا 10 روز (erythromycin 500 mg چهار بار روزانه جایگزین)؛ babesiosis: atovaquone 750 mg PO هر 12 ساعت + azithromycin 500 mg روز اول سپس 250 تا 1000 mg روزانه 10 روز؛ شدید: clindamycin 1200 mg IV دو بار روزانه + quinine 650 mg PO سه بار روزانه 7 تا 10 روز؛ Colorado tick fever: حمایتی"],"ddx":[{"n":"Sepsis / septic shock |","cm":1},{"n":"Endocarditis |","cm":1},{"n":"Influenza-like illness |"},{"n":"Meningitis / pneumonia |"},{"n":"Hepatitis |"}],"redflags":["شوک، مننژیت، پنومونی شدید، اندوکاردیت"],"guide":"انتخاب بر اساس مواجهه حیوانی/ناقل و جدول 97-1؛ مشاوره عفونی؛ آنتی‌بیوتیک‌ها مطابق ویژگی‌ها. سپسیس/شوک: فصل ۸۹.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 97: Zoonotic Infections, pp. 531–539"},"traveler-fever-arboviral":{"id":"traveler-fever-arboviral","variants":[{"id":"traveler-fever-undifferentiated","o":{"I":[{"t":"Chest radiograph if respiratory symptoms; liver ultrasound if amebic liver abscess suspected"}],"L":[{"t":"CBC with differential and platelets (lymphopenia, eosinophilia, thrombocytopenia), blood smear and malaria antigen dipstick, liver function tests if jaundice, urinalysis; dengue PCR (1 to 8 days from onset) or IgM ELISA (after 4 days); chikungunya PCR (1 to 4 days) or IgM (after 5 days); daily blood counts for dengue"}],"S":[{"t":"Oral hydration as tolerated (mild dengue)","fl":[{"k":"ci","v":"avoid aspirin and NSAIDs in dengue"}]}],"T":[{"t":"Supportive therapy for dengue, chikungunya (rest, fluids, NSAIDs for pain/fever; avoid further mosquito exposure in the first week), Zika and yellow fever (transfusion as needed)","fl":[{"k":"note","v":"no specific antiviral treatment"}]},{"t":"Crimean-Congo hemorrhagic fever: supportive care, transfusions or respiratory support if severe; Ribavirin for moderate to severe illness","fl":[{"k":"note","v":"dose not given in the book"}]}],"Co":[{"t":"Admit for drop in hemoglobin or platelets, hemorrhagic symptoms or abnormal vital signs; infectious disease; isolation if hemorrhagic fever suspected"}]},"name":"Febrile returning traveler (undifferentiated)","level":"II","imp":"Fever in a returning traveler","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مردی ۳۰ ساله ۱۰ روز پس از بازگشت از آسیای جنوب‌شرقی با تب بالا، سردرد، میالژی و راش.","why":"مالاریا را رد کن؛ دنگی و سایر عفونت‌های مسافرتی؛ بستری بر اساس هشدارها."}],"ch":"98","name":"Febrile returning traveler: dengue, chikungunya, Zika, yellow fever, Crimean-Congo hemorrhagic fever","name_fa":"مسافر تب‌دار بازگشته: دنگی، چیکونگونیا، زیکا، تب زرد، تب هموراژیک کریمه-کنگو","cc":["fever","rash"],"keywords":"returning traveler, dengue, chikungunya, Zika virus, yellow fever, Crimean-Congo hemorrhagic fever, ribavirin, travel history, دنگی, زیکا, چیکونگونیا, مسافر","status":"draft","features":["نهفتگی بیماری‌ها اغلب بیش از مدت اقامت؛ علائم پس از بازگشت؛ بپرس: بازدید پارک حیات‌وحش، مزرعه، غار، مراکز درمانی، غذاهای عجیب، تماس با آب شیرین/شور، گزش حشره، فعالیت جنسی، اپیدمی گزارش‌شده، تماس با بیمار، واکسن و آنتی‌بیوتیک پروفیلاکتیک قبل از سفر؛ زمان‌بندی تب","جدول 98-1 منطقه‌ای: آفریقا (مالاریا، HIV، TB، بروسلوز، تب زرد، لاسا/ابولا، تب راجعه، شیستوزومیازیس...)؛ آمریکای مرکزی/جنوبی (مالاریا، دنگی، Chagas، تیفوس، زیکا)؛ مکزیک/کارائیب (دنگی، سیستی‌سرکوز، آمیبیاز، زیکا)؛ استرالیا/نیوزیلند (دنگی، Q fever، Japanese encephalitis)؛ خاورمیانه (مالاریا، سیاه‌زخم، بروسلوز)؛ اروپا (ژیاردیازیس، لایم، babesiosis)؛ چین/شرق آسیا (دنگی، مالاریا، Japanese encephalitis، تب هموراژیک)","یافته‌های فیزیکی (جدول 98-2): راش (دنگی، تیفوس، سیفلیس، ابولا، چیکونگونیا، HIV، زیکا)؛ ایکتر (هپاتیت، مالاریا، تب زرد، لپتوسپیروز)؛ آدنوپاتی؛ هپاتومگالی؛ اسپلنومگالی؛ eschar (تیفوس، borreliosis، CCHF، سیاه‌زخم)؛ خونریزی (Lassa/Marburg/Ebola، CCHF، منینگوکوکسمی)","آزمایش: CBC با دیفرانسیل: لنفوپنی (دنگی، HIV، تیفوئید)، ائوزینوفیلی (انگل و قارچ)، ترومبوسیتوپنی (مالاریا، دنگی، HIV حاد، تیفوئید)؛ اسمیر خون و آنتی‌ژن مالاریا؛ UA: پروتئینوری و هماچوری در لپتوسپیروز؛ LFT در ایکتر؛ CXR با علائم تنفسی؛ سونو کبد در شک آبسه آمیبی","دنگی: ناقل Aedes aegypti؛ نهفتگی 4 تا 7 روز؛ تب بالا، سردرد، تهوع، استفراغ، میالژی و راش؛ دنگی هموراژیک: تب بالا، نفوذپذیری عروقی، خونریزی، هپاتومگالی و شوک؛ تشخیص: PCR (روز 1 تا 8) یا IgM ELISA (بعد از 4 روز)","چیکونگونیا: آربوویروس؛ Aedes aegypti و albopictus؛ مشابه دنگی با آرترالژی منتشر که در 5% تا 30% به آرتروپاتی مزمن می‌رسد؛ PCR روز 1 تا 4 یا IgM بعد از 5 روز","زیکا: Aedes؛ تب، راش، درد مفصل و ملتحمه؛ معمولاً خفیف < 1 هفته؛ GBS و میکروسفالی مادرزادی","تب زرد: فلاویویروس با پشه روزگزنده؛ کمربند استوایی؛ 15٪ شدید با مرگ 20٪ تا 50٪؛ نهفتگی 3 تا 6 روز؛ تب، سردرد، میالژی، ملتحمه، درد شکم، گُرگرفتگی صورت و برادی‌کاردی نسبی؛ سپس ایکتر، استفراغ سیاه و آلبومینوری؛ شدید: شوک و خونریزی","CCHF: ویروس منتقله با کنه (آفریقا، آسیا، اروپای شرقی، خاورمیانه)؛ کشاورزان؛ تماس با خون؛ شروع ناگهانی تب، سردرد، میالژی، سرگیجه و گیجی؛ روز 3 تا 5 دوره هموراژیک (epistaxis، هموپتزی، GI، واژینال، هماچوری)؛ ترومبوسیتوپنی، آنزیم کبد/کراتینین بالا، PT/aPTT طولانی"],"ddx":[{"n":"Malaria |","cm":1},{"n":"Viral hemorrhagic fever (Ebola, Lassa, CCHF) |","cm":1},{"n":"Typhoid fever / meningococcemia |","cm":1},{"n":"Dengue / chikungunya / Zika / yellow fever |"},{"n":"Leptospirosis / rickettsial infection / acute HIV |"}],"redflags":["خونریزی، شوک، افت پلاکت/هموگلوبین، تغییر هوشیاری، ایکتر با تب"],"guide":"دنگی: درمان حمایتی؛ خفیف سرپایی با مایع خوراکی و پیگیری آزمایش خون؛ از آسپیرین و NSAID پرهیز؛ شمارش خون روزانه؛ بستری: افت Hb یا پلاکت، علائم هموراژیک یا علائم حیاتی غیرطبیعی. چیکونگونیا: حمایتی (استراحت، مایع، NSAID برای درد/تب)؛ واکسن و دارو ندارد؛ پرهیز از گزش پشه در هفته اول. زیکا: حمایتی؛ بدون ضدویروس. تب زرد: حمایتی با ترانسفوزیون در صورت نیاز. CCHF: حمایتی (ترانسفوزیون/حمایت تنفسی)؛ متوسط تا شدید: ribavirin. مالاریا: اسمیر و تست آنتی‌ژن (فصل ۹۵).","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 98: World Travelers, pp. 540–545"},"enteric-rickettsial-lepto-brucella":{"id":"enteric-rickettsial-lepto-brucella","variants":[{"id":"typhoid-main","o":{"L":[{"t":"Stool culture (confirmation); blood cultures; CBC","fl":[{"k":"note","v":"blood cultures/CBC not specified in this chapter beyond travel workup"}]}],"A":[{"t":"Ceftriaxone 2 g IV or IM for 14 days, or Ciprofloxacin 500 to 750 mg PO twice daily for 14 days"}],"T":[{"t":"Severe typhoid with delirium, coma, shock or DIC: initial dose of Dexamethasone 3 mg/kg IV; blood transfusion in severe cases"}],"Co":[{"t":"Admit if severe; infectious disease"}]},"name":"Typhoid (enteric) fever","level":"II","imp":"Typhoid fever","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۳۰ ساله ۲ هفته پس از بازگشت از هند با تب 39.5 یک‌هفته‌ای، سردرد، درد شکم و یبوست.","why":"تیفوئید با سفتریاکسون یا سیپروفلوکساسین 14 روز؛ دگزامتازون در شدید."},{"id":"rickettsial-lepto-brucella-main","o":{"L":[{"t":"Serologic tests to confirm diagnosis after empiric treatment (rickettsial, leptospirosis, brucellosis); blood culture (brucellosis); urinalysis (proteinuria, hematuria in leptospirosis)"}],"A":[{"t":"Rickettsial spotted fevers / louse-borne typhus: Doxycycline 100 mg twice daily for 7 to 10 days"},{"t":"Leptospirosis: mild (within 3 days of symptoms) Amoxicillin 500 mg three times daily or Doxycycline 100 mg twice daily; severe Penicillin G 5 MU IV every 6 hours, or Ceftriaxone 1 g IV or IM daily for 7 to 14 days"},{"t":"Brucellosis: doxycycline, rifampicin, streptomycin or gentamicin for 2 weeks (consult infectious disease)","fl":[{"k":"note","v":"doses not given in this chapter"}]}],"Co":[{"t":"Infectious disease"}]},"name":"Rickettsial infection / leptospirosis / brucellosis in a traveler","level":"II","imp":"Rickettsial infection / leptospirosis / brucellosis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۳۵ ساله بازگشته از آفریقا با تب، سردرد شدید، eschar سیاه روی ساق و راش.","why":"ریکتزیوز: داکسی‌سایکلین تجربی؛ لپتوسپیروز با ریسک آب شیرین."}],"ch":"98","name":"Typhoid fever, rickettsial/louse-borne typhus, leptospirosis and brucellosis in travelers","name_fa":"تب تیفوئید، ریکتزیوز/تیفوس شپشی، لپتوسپیروز و بروسلوز در مسافران","cc":["fever","rash","abdominal-pain"],"keywords":"typhoid fever, enteric fever, Salmonella typhi, rose spots, scrub typhus, African tick typhus, louse-borne typhus, leptospirosis, brucellosis, ceftriaxone, doxycycline, تیفوئید, تیفوس","status":"draft","features":["تیفوئید (S. typhi/paratyphi): غذای/آب آلوده یا تماس با ادرار/مدفوع؛ نهفتگی 1 تا 3 هفته؛ > 10 روز؛ تب با سردرد → تب بالا با لرز، سرفه، اتساع شکم، میالژی، یبوست و prostration؛ برادی‌کاردی نسبی (اغلب نیست)؛ rose spots روی تنه؛ عوارض: زخم روده کوچک، آنمی، DIC، پنومونی، مننژیت، میوکاردیت و نارسایی کلیه؛ تشخیص بالینی و کشت مدفوع","بروسلوز: تماس با گاو، بز، شتر، سگ، خوک یا خوردن لبنیات غیرپاستوریزه؛ تب، درد شکم، کمردرد، خستگی، سردرد، درد مفصل؛ تب راجعه یا مزمن خفیف؛ آدنوپاتی، هپاتواسپلنومگالی و آرتریت سپتیک؛ کشت خون/سرولوژی","ریکتزیوزهای تب خال‌دار: گزش/مدفوع کنه؛ مرگ بدون درمان تا 25٪؛ scrub typhus (آسیای جنوب‌شرقی) و African tick typhus (آفریقا)؛ نهفتگی 3 تا 14 روز؛ تب، ناخوشی، میالژی، سردرد شدید، راش، تهوع و استفراغ سپس آدنوپاتی و اسپلنومگالی؛ eschar سیاه در scrub typhus","تیفوس شپشی اپیدمیک (R. prowazekii): مکزیک، گواتمالا، اتیوپی، هیمالیا؛ نهفتگی 8 تا 12 روز؛ تب بالا، سردرد شدید و راش ماکولوپاپولار روز 4 تا 7","لپتوسپیروز: آب شیرین یا سگ آلوده؛ نهفتگی 2 تا 20 روز؛ تب بالا، سردرد شدید، لرز، میالژی، هپاتیت و ملتحمه؛ سرولوژی"],"ddx":[{"n":"Typhoid fever with intestinal perforation |","cm":1},{"n":"Rickettsial infection (treatable, fatal if untreated) |","cm":1},{"n":"Leptospirosis / Weil disease |"},{"n":"Brucellosis / malaria |"},{"n":"Dengue / viral hepatitis |"}],"redflags":["شوک، DIC، دلیریوم/کما، خونریزی گوارشی/پرفوراسیون"],"guide":"تیفوئید: ceftriaxone 2 g IV یا IM 14 روز یا ciprofloxacin 500 تا 750 mg PO دو بار روزانه 14 روز؛ شدید با دلیریوم/کما/شوک/DIC: دوز اولیه dexamethasone 3 mg/kg IV؛ ترانسفوزیون در صورت نیاز. بروسلوز: مشاوره عفونی؛ doxycycline، rifampicin، streptomycin یا gentamicin 2 هفته. ریکتزیوز و تیفوس شپشی: درمان تجربی با doxycycline 100 mg دو بار روزانه 7 تا 10 روز سپس تأیید سرولوژی. لپتوسپیروز: خفیف طی 3 روز از علائم: amoxicillin 500 mg سه بار روزانه یا doxycycline 100 mg دو بار روزانه؛ شدید: penicillin G 5 MU IV هر 6 ساعت یا ceftriaxone 1 g IV/IM روزانه 7 تا 14 روز.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 98: World Travelers, pp. 540–545"},"traveler-parasitic-diseases":{"id":"traveler-parasitic-diseases","variants":[{"id":"parasitic-neuro-amebic","o":{"I":[{"t":"Noncontrast CT head (calcifications of inactive neurocysticercosis; hydrocephalus); liver ultrasound for amebic liver abscess"}],"L":[{"t":"Stool for ova and parasites; midday urine/stool microscopy for schistosome eggs; CBC with eosinophilia; serology as indicated"}],"T":[{"t":"Neurocysticercosis: Praziquantel 17 mg/kg three times daily; steroids for encephalitis, hydrocephalus or vasculitis"},{"t":"Schistosomiasis: Praziquantel 20 mg/kg, two doses in a single day (three doses in a single day with GI involvement)"},{"t":"Amebiasis: Metronidazole 500 to 750 mg PO three times daily for 10 days"}],"Co":[{"t":"Infectious disease; neurology for seizures"}]},"name":"Neurocysticercosis / amebiasis / schistosomiasis","level":"II","imp":"Tropical parasitic infection (neurocysticercosis / amebiasis / schistosomiasis)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۳۵ ساله مکزیکی با اولین تشنج و کلسیفیکاسیون‌های CT؛ یا مسافری با اسهال خونی و تب بعد از سفر.","why":"تشخیص و درمان اختصاصی هر انگل؛ CT بدون کنتراست در تشنج."},{"id":"parasitic-helminth-outpatient","o":{"L":[{"t":"Stool examination (and serology for ascariasis, tapeworm); cellophane tape swab of the anus for pinworm"}],"A":[{"t":"Ascariasis: Mebendazole 100 mg PO daily for 3 days or 500 mg PO single dose, or Albendazole 400 mg PO single dose, or Ivermectin 150 to 200 μg/kg PO single dose"},{"t":"Enterobiasis: Mebendazole 100 mg PO single dose and repeat in 2 weeks, or Albendazole 400 mg PO single dose and repeat in 2 weeks, or Pyrantel pamoate 11 mg/kg (up to 1 g) PO single dose and repeat in 2 weeks"},{"t":"Hookworm: Albendazole 400 mg PO single dose, or Mebendazole 100 mg PO twice daily for 3 days or 500 mg PO single dose, or Pyrantel pamoate 11 mg/kg (up to 1 g) PO daily for 3 days"},{"t":"Tapeworm: Praziquantel 5 to 10 mg/kg PO single dose"}],"Co":[{"t":"Outpatient follow-up"}]},"name":"Intestinal helminths (ascariasis, pinworm, hookworm, tapeworm)","level":"III","imp":"Intestinal helminth infection","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودک ۸ ساله بازگشته از سفر با خارش شبانه شدید مقعد؛ یا مسافر با درد شکم و کرم در مدفوع.","why":"تک‌دوز ضد کرم مناسب؛ تأیید با مدفوع/نوار چسب."},{"id":"parasitic-protozoal-systemic","o":{"L":[{"t":"Rapid blood smear for mobile parasites (African trypanosomiasis; Chagas acute phase: blood culture or smear); serology or tissue biopsy (chronic Chagas); CBC (pancytopenia in visceral leishmaniasis), hypergammaglobulinemia"}],"A":[{"t":"African trypanosomiasis: Pentamidine or other agents","fl":[{"k":"note","v":"consult infectious disease; specific drug depends on type of infection"}]},{"t":"Chagas disease: Nifurtimox, Benznidazole or other agents","fl":[{"k":"note","v":"consult infectious disease"}]},{"t":"Visceral leishmaniasis: pentavalent antimonial compounds such as sodium stibogluconate (available through the CDC) or Miltefosine","fl":[{"k":"note","v":"doses not given in the book"}]}],"Co":[{"t":"Infectious disease; admit"}]},"name":"Trypanosomiasis / Chagas disease / visceral leishmaniasis","level":"II","imp":"Systemic tropical protozoal infection (trypanosomiasis / Chagas disease / leishmaniasis)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مسافر ۴۰ ساله از آفریقا با شانکر بدون درد، تب متناوب و تغییرات رفتاری؛ یا فرد با تب، کاهش وزن، اسپلنومگالی و پانسیتوپنی پس از اقامت در ناحیه آندمیک.","why":"تشخیص با اسمیر خون یا سرولوژی؛ درمان اختصاصی با مشاوره عفونی."}],"ch":"98","name":"Tropical parasitic diseases in travelers (cysticercosis, trypanosomiasis, Chagas, leishmaniasis, schistosomiasis, amebiasis, helminths)","name_fa":"بیماری‌های انگلی گرمسیری در مسافران (سیستی‌سرکوز، تریپانوزومیازیس، Chagas، لیشمانیوز، شیستوزومیازیس، آمیبیاز، کرم‌ها)","cc":["fever","diarrhea","seizure"],"keywords":"neurocysticercosis, praziquantel, African trypanosomiasis, Chagas disease, visceral leishmaniasis, schistosomiasis, amebiasis, metronidazole, ascariasis, pinworm, hookworm, tapeworm, albendazole, mebendazole, انگل گرمسیری","status":"draft","features":["سیستی‌سرکوز: لارو کیست کرم نواری خوک؛ نورو: علت شایع تشنج جهانی؛ سردرد، تغییر بینایی/هوشیاری، سکته، مننگوآنسفالیت، هیدروسفالی انسدادی؛ CT بدون کنتراست: کلسیفیکاسیون","تریپانوزومیازیس آفریقایی (T. brucei): مگس تسه‌تسه؛ شانکر بدون درد 2 تا 3 روز بعد؛ تب متناوب، ناخوشی، راش؛ CNS: تغییرات رفتاری و عصبی تا کما؛ تشخیص با اسمیر خون سریع؛ مشاوره عفونی (pentamidine یا سایر)","Chagas (T. cruzi): آمریکای لاتین تا تگزاس؛ حشره «kissing bug»؛ فاز حاد: ادم یک‌طرفه دور چشم یا chagoma؛ سپس پارازیتمی با آدنوپاتی و هپاتواسپلنومگالی؛ تشخیص حاد: کشت یا اسمیر خون؛ مزمن: سرولوژی/بیوپسی؛ nifurtimox یا benznidazole با مشاوره عفونی","لیشمانیوز احشایی: ساس‌مگس؛ سربازان، مسافران ماجراجو؛ تب، کاهش وزن، هپاتواسپلنومگالی، پانسیتوپنی و هیپرگاماگلوبولینمی؛ sodium stibogluconate (از CDC) یا miltefosine","شیستوزومیازیس: لارو از حلزون در آب شیرین؛ درماتیت ماکولوپاپولار خارش‌دار ساق؛ 4 تا 8 هفته بعد: تب، سردرد، سرفه، کهیر، اسهال، هپاتواسپلنومگالی و ائوزینوفیلی؛ تخم در ادرار/مدفوع ظهر","آمیبیاز (E. histolytica): آسیا، آفریقا، آمریکای لاتین؛ نهفتگی 1 تا 3 هفته (کولیت)؛ مدفوع شل و کرامپ؛ اسهال خونی آمیبی؛ آبسه کبد: تب، درد RUQ؛ اوا و انگل مدفوع؛ سونو","آسکاریازیس: سرفه خشک/پنومونی، سوءتغذیه، انسداد روده؛ مدفوع/سرولوژی","Enterobius (سیرمک): خارش شدید مقعد؛ نوار چسب سلوفان","قلاب‌دار (Ancylostoma/Necator): درد شکم، آنمی شدید و cutaneous larva migrans","کرم نواری (Taenia solium/saginata/Diphyllobothrium): اسهال، درد شکم، انسداد؛ مدفوع/سرولوژی"],"ddx":[{"n":"Neurocysticercosis (seizure) |","cm":1},{"n":"Amebic liver abscess |","cm":1},{"n":"Visceral leishmaniasis / malaria |"},{"n":"Schistosomiasis / helminth infection |"},{"n":"Chagas disease / African trypanosomiasis |"}],"redflags":["تشنج یا تغییر هوشیاری، انسداد روده، آنمی شدید، پانسیتوپنی"],"guide":"سیستی‌سرکوز: praziquantel 17 mg/kg سه بار روزانه؛ استروئید در آنسفالیت، هیدروسفالی یا واسکولیت. شیستوزومیازیس: praziquantel 20 mg/kg دو دوز در یک روز (GI: سه دوز). آمیبیاز: metronidazole 500 تا 750 mg PO سه بار روزانه 10 روز. آسکاریازیس: mebendazole 100 mg PO روزانه 3 روز یا 500 mg تک‌دوز یا albendazole 400 mg تک‌دوز یا ivermectin 150 تا 200 μg/kg تک‌دوز. Enterobius: mebendazole 100 mg تک‌دوز و تکرار 2 هفته، albendazole 400 mg تک‌دوز و تکرار 2 هفته یا pyrantel pamoate 11 mg/kg (تا 1 g) تک‌دوز و تکرار 2 هفته. قلاب‌دار: albendazole 400 mg تک‌دوز یا mebendazole 100 mg دو بار روزانه 3 روز یا 500 mg تک‌دوز یا pyrantel pamoate 11 mg/kg (تا 1 g) روزانه 3 روز. کرم نواری: praziquantel 5 تا 10 mg/kg PO تک‌دوز. تریپانوزومیازیس/Chagas/لیشمانیوز: مشاوره عفونی.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 98: World Travelers, pp. 540–545"},"transplant-infection":{"id":"transplant-infection","variants":[{"id":"transplant-fever-infection","o":{"I":[{"t":"Chest radiograph (low threshold); lumbar puncture if CNS infection suspected"}],"L":[{"t":"Blood counts, inflammatory markers, renal and liver function; appropriate cultures of urine, blood and other body fluids; drug levels","fl":[{"k":"note","v":"immunosuppressant levels per transplant team"}]}],"S":[{"t":"IV fluids as indicated for dehydration","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema; allograft nephrotoxicity"}]}],"A":[{"t":"Skin/superficial wound: broad-spectrum antibiotic plus MRSA agent: Imipenem 500 mg IV every 6 hours, or Meropenem 1 g IV every 8 hours, or Piperacillin/tazobactam 3.375 g IV every 6 hours, plus Vancomycin 1 g IV every 12 hours or Linezolid 600 mg IV every 12 hours"},{"t":"Pneumonia: Imipenem 500 mg IV every 6 hours, Meropenem 1 g IV every 8 hours, Cefotaxime 1 to 2 g IV every 6 to 8 hours plus Gentamicin 1 to 2 mg/kg IV every 8 hours, or Piperacillin/tazobactam 3.375 g IV every 6 hours; add MRSA-specific and antifungal therapy if suspected"},{"t":"Intra-abdominal infection: Metronidazole 500 mg IV every 12 hours plus Imipenem 500 mg IV every 6 hours, or Meropenem 1 g IV every 8 hours, or Doripenem 500 mg IV every 8 hours, or Piperacillin/tazobactam 3.375 g IV every 6 hours"},{"t":"Suspected fungal disease: Fluconazole 400 mg daily IV (Amphotericin B 0.7 mg/kg/d IV more toxic); oral/esophageal Candida: Fluconazole 200 mg PO day 1 then 100 mg PO daily"},{"t":"Suspected CMV: Ganciclovir 5 mg/kg IV twice daily (bone marrow transplant: add immunoglobulin)"},{"t":"Disseminated/ocular varicella and HSV: Acyclovir 800 mg IV five times a day (adjust for renal insufficiency); alternatives Valacyclovir 1000 mg every 8 hours or Famciclovir 500 mg every 8 hours"},{"t":"Pneumocystis pneumonia: Prednisone 80 mg/d then TMP-SMX 15 mg/kg/d IV divided every 8 hours while critically ill (oral TMP-SMX DS two tablets PO every 8 hours, 3 weeks total); alternatives Pentamidine 4 mg/kg/d IV or IM for 3 weeks, or Clindamycin 600 mg IV plus Primaquine 30 mg orally daily"},{"t":"Toxoplasmosis: Pyrimethamine 200 mg PO initially then 50 to 75 mg PO daily plus Sulfadiazine 1 to 4 g PO daily plus Folinic acid 10 mg PO daily"}],"Co":[{"t":"Transplant team consultation (treatment medications and duration); admit; discuss any new medication with the transplant team"}]},"name":"Fever / suspected infection in a transplant recipient","level":"II","imp":"Suspected infection in a transplant recipient","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مرد ۵۰ ساله با پیوند کلیه ۳ ماه پیش، تب 38.8، سرفه و SpO2 90٪.","why":"پیوندی: آستانه پایین برای CXR و آنتی‌بیوتیک وسیع؛ مشاوره تیم پیوند."}],"ch":"99","name":"Infection in the transplant patient","name_fa":"عفونت در بیمار پیوندی","cc":["fever","dyspnea"],"keywords":"transplant infection, immunosuppressed, post-transplant fever, Pneumocystis, CMV, ganciclovir, fluconazole, imipenem, meropenem, vancomycin, TMP-SMX, پیوند, عفونت","status":"draft","features":["سه حوزه: اختلالات خاص عضو پیوندی، اختلالات مشترک (ایمنوساپرسیون/داروهای ضدرد پیوند)، اختلالات غیراختصاصی که مراقبت ویژه می‌خواهند؛ علل مراجعه: عفونت (39٪)، GI/GU غیرعفونی (15٪)، دهیدراتاسیون (15٪)، اختلال الکترولیت (10٪)، قلبی-ریوی (10٪)، آسیب (8٪)، رد (6٪)","عفونت شایع‌ترین تشخیص ED؛ عوامل خطر اضافه: دیابت، سن بالا، چاقی","جدول 99-1: < 1 ماه: ارگانیسم‌های مقاوم (MRSA، VRE، Candida)، عوارض جراحی/بستری (آسپیراسیون، کاتتر، زخم، نشت آناستوموز، C. difficile)، Aspergillus/Pseudomonas/Klebsiella/Legionella؛ عفونت فرصت‌طلب معمولاً غایب؛ علائم زودرس غیرقابل‌توضیح (هپاتیت، آنسفالیت، پنومونیت یا راش) ممکن است donor-derived؛ 1 تا 6 ماه: با پروفیلاکسی (PCP، CMV، HBV): BK، C. difficile، HCV، آدنوویروس، آنفلوانزا، Cryptococcus، TB؛ بدون پروفیلاکسی: Pneumocystis، هرپس‌ویروس، HBV، Listeria، Nocardia، Toxoplasma، Strongyloides، Leishmania، T. cruzi؛ > 6 ماه: عمومی: پنومونی و UTI اکتسابی از جامعه؛ Aspergillus/Mucor، Nocardia؛ ویروس‌های دیررس: CMV، هپاتیت، HSV آنسفالیت، JC (PML)، سرطان پوست/لنفوم (PTLD)","شایع‌ترین علت مراجعه تب؛ تا نیمی با عفونت جدی بدون تب؛ علل دیگر تب: عوارض دارو، حساسیت، رد و بدخیمی","شایع‌ترین عفونت‌ها: پنومونی و UTI؛ آستانه پایین برای CXR؛ کشت‌های مناسب؛ LP در شک CNS؛ کبد: عفونت شکمی ماه اول؛ ریه: پنومونی؛ قلب: مدیاستینیت ماه اول"],"ddx":[{"n":"Sepsis / pneumonia |","cm":1},{"n":"Opportunistic infection (PCP, CMV, fungal) |","cm":1},{"n":"Allograft rejection |","cm":1},{"n":"Drug fever / hypersensitivity |"},{"n":"Post-transplant lymphoproliferative disorder |"},{"n":"Meningitis / encephalitis |"}],"redflags":["تب یا بدحالی بدون تب، هیپوکسی، تغییر هوشیاری، عدم توانایی مصرف داروی ضدرد پیوند"],"guide":"در عفونت تشخیص‌داده‌شده با تیم پیوند مشاوره کن. 2) پوست/زخم: وسیع‌الطیف + MRSA: imipenem 500 mg IV هر 6 ساعت یا meropenem 1 g IV هر 8 ساعت یا piperacillin/tazobactam 3.375 g IV هر 6 ساعت + vancomycin 1 g IV هر 12 ساعت یا linezolid 600 mg IV هر 12 ساعت. 3) پنومونی: imipenem، meropenem، cefotaxime 1 تا 2 g IV هر 6 تا 8 ساعت + gentamicin 1 تا 2 mg/kg IV هر 8 ساعت یا piperacillin/tazobactam؛ افزودن MRSA و ضدقارچ در صورت شک. 4) شکمی: metronidazole 500 mg IV هر 12 ساعت + imipenem، meropenem 1 g هر 8 ساعت، doripenem 500 mg هر 8 ساعت یا piperacillin/tazobactam. 5) قارچ: fluconazole 400 mg روزانه IV؛ amphotericin B 0.7 mg/kg/d (سمی‌تر)؛ کاندیدای دهان/مری: fluconazole 200 mg PO روز اول سپس 100 mg روزانه. 6) CMV: ganciclovir 5 mg/kg IV دو بار روزانه (پیوند مغز استخوان: افزودن ایمونوگلوبولین). 7) واریسلا منتشر/چشمی و HSV: acyclovir 800 mg IV پنج بار روزانه (تنظیم در نارسایی کلیه)؛ valacyclovir 1000 mg هر 8 ساعت یا famciclovir 500 mg هر 8 ساعت. 8) PCP: prednisone 80 mg/d سپس TMP-SMX 15 mg/kg/d IV تقسیم هر 8 ساعت (بحرانی) یا DS دو قرص PO هر 8 ساعت 3 هفته؛ جایگزین: pentamidine 4 mg/kg/d IV/IM 3 هفته یا clindamycin 600 mg IV + primaquine 30 mg PO روزانه. 9) توکسوپلاسموز: pyrimethamine 200 mg PO سپس 50 تا 75 mg روزانه + sulfadiazine 1 تا 4 g روزانه + folinic acid 10 mg روزانه. 10) UTI، گاستروانتریت تهاجمی (Salmonella، Campylobacter، Listeria) و دیورتیکولیت با آنتی‌میکروبیال‌های معمول. عوارض داروهای ایمنوساپرسیو: تدریجی (پانکراتیت، خونریزی، قند، برادی/تاکی‌کاردی، هیپرکالمی، فشار، کاردیوتوکسیسیتی، ادم ریه، تشنج، ترومبوآمبولی، ترومبوسیتوپنی)؛ سردرد مشابه میگرن در 2 ماه اول؛ بیماری که مانع مصرف دارو شود: بستری برای تجویز وریدی؛ شروع داروی جدید با مشاوره تیم پیوند.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 99: The Transplant Patient, pp. 546–554"},"transplant-rejection-organ":{"id":"transplant-rejection-organ","variants":[{"id":"transplant-heart-rejection","o":{"I":[{"t":"Chest radiograph; echocardiography as indicated","fl":[{"k":"note","v":"not specified in this chapter"}]}],"L":[{"t":"Serial troponin levels; electrolytes, drug levels"}],"T":[{"t":"Acute rejection: Methylprednisolone 1 g IV after consultation with the transplant center (treatment typically begun after biopsy confirmation unless hemodynamically unstable)"},{"t":"Bradydysrhythmias: Isoproterenol 2 to 10 μg/min IV infusion","fl":[{"k":"ci","v":"atropine has no effect on a denervated heart"}]},{"t":"Hypotension: Dopamine 2 to 20 μg/kg/min IV or Dobutamine 2 to 20 μg/kg/min IV"}],"Co":[{"t":"Transplant center consultation; transfer to a transplantation center when possible"}]},"name":"Heart transplant: suspected rejection, silent ischemia or bradycardia","level":"I","imp":"Heart transplant recipient with suspected rejection / ischemia","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مرد ۴۵ ساله با پیوند قلب، تنگی نفس جدید، خستگی و آریتمی بطنی؛ بدون درد قفسه سینه.","why":"دناروه: MI خاموش؛ رد حاد؛ آتروپین بی‌اثر."},{"id":"transplant-lung-kidney-liver","o":{"I":[{"t":"Lung: chest radiograph, spirometry; kidney: renal ultrasonography (obstruction), MRI for hematomas/fluid collections/vascular abnormalities (discuss gadolinium with transplant team); liver: abdominal ultrasound (fluid collections, hepatic artery or portal vein thrombosis, biliary dilatation) or CT; cholangiography / ERCP if biliary obstruction suspected"}],"L":[{"t":"Lung: pulse oximetry, ABG, CBC, electrolytes, creatinine, magnesium, drug levels; kidney: urinalysis, serial creatinine, immunosuppressive drug levels; liver: CBC, serum chemistry, liver function tests, coagulation studies, lipase, cultures of blood, urine, bile or ascites"}],"A":[{"t":"Liver biliary obstruction: Metronidazole 500 mg IV every 12 hours plus Imipenem 500 mg IV every 6 hours or Piperacillin/tazobactam 3.375 g IV every 6 hours"},{"t":"Lung: empiric antibiotics for suspected infection (see above)"}],"T":[{"t":"Acute rejection: Methylprednisolone 1 g IV after consultation with the transplant center"},{"t":"Biliary obstruction: balloon dilatation; biliary leakage: surgery; hepatic artery thrombosis may require retransplantation"}],"Co":[{"t":"Transplant center consultation; transfer (surgical complications best managed at the original transplant center)"}]},"name":"Lung / kidney / liver transplant: suspected rejection or surgical complication","level":"II","imp":"Transplant recipient with suspected rejection / surgical complication","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مرد ۴۰ ساله با پیوند کبد ۳ هفته پیش با تب، درد شکم، ایکتر و LFT بالا.","why":"رد یا نشت/انسداد صفراوی یا ترومبوز شریان کبدی؛ مرکز پیوند."}],"ch":"99","name":"Transplant rejection and organ-specific complications (heart, lung, kidney, liver)","name_fa":"رد پیوند و عوارض اختصاصی عضو (قلب، ریه، کلیه، کبد)","cc":["dyspnea","abdominal-pain","urinary-symptoms","palpitations"],"keywords":"acute rejection, heart transplant, denervated heart, isoproterenol, lung transplant rejection, renal transplant rejection, liver transplant biliary complication, hepatic artery thrombosis, methylprednisolone 1 g, رد پیوند","status":"draft","features":["قلب: قلب دناروه: تاکی‌کاردی مرکزی در استرس/ورزش ندارد (ولی به کاتکولامین پاسخ می‌دهد)؛ خستگی/تنگی نفس در شروع ورزش؛ ضربان طبیعی 90 تا 100؛ ECG دو موج P (گره سینوسی دهنده با رابطه 1:1 با QRS و بومی مستقل)؛ ایسکمی بدون آنژین؛ نارسایی قلبی از MI خاموش؛ ECG و تروپونین سریال؛ رد حاد معمولاً بدون علامت: آریتمی و خستگی؛ کودکان: تب خفیف، گریه و تغذیه ضعیف","ریه: رد: سرفه، گرفتگی سینه، تب و هیپوکسمی؛ عفونت (پنومونیت بینابینی) مشابه؛ ممکن است سریع و تنها تب؛ اسپیرومتری افت > 10٪ FEV1؛ CXR انفیلتره بینابینی دوطرفه یا افیوژن (ممکن است نرمال، به‌ویژه > 6 هفته)؛ برونکوسکوپی با بیوپسی برای تأیید","کلیه: تندرنس مبهم روی آلوگرافت (حفره ایلیاک)، کاهش ادرار، افزایش وزن سریع، تب خفیف، ناخوشی؛ فشار بدتر، ادم؛ حتی تغییر کوچک کراتینین مهم؛ UA، سونوگرافی کلیه، سطح داروی ایمنوساپرسیو؛ افتراق: دهیدراتاسیون، سمیت cyclosporine؛ MRI؛ قبل از gadolinium با تیم پیوند صحبت کن","کبد: رد: تب، تندرنس کبد، لنفوسیتوز، ائوزینوفیلی، آنزیم کبدی بالا، تغییر صفرا؛ افتراق: عفونت، انسداد صفراوی، نارسایی عروقی؛ تشخیص قطعی سونو و بیوپسی؛ عوارض: انسداد صفراوی (تب متناوب و LFT نوسانی، بدتر شدن بی‌علامت LFT، یا کولانژیت باکتریال حاد)، نشت صفراوی (50٪ مرگ؛ هفته 3 تا 4؛ ممکن است علائم صفاقی با استروئید پنهان شود)، ترومبوز شریان کبدی؛ بررسی: CXR، CBC، شیمی، LFT، انعقاد، لیپاز، کشت خون/ادرار/صفرا/آسیت، سونوگرافی شکم یا CT؛ cholangiography/ERCP"],"ddx":[{"n":"Acute allograft rejection |","cm":1},{"n":"Silent myocardial infarction (heart transplant) |","cm":1},{"n":"Biliary leak / hepatic artery thrombosis |","cm":1},{"n":"Infection mimicking rejection (pneumonitis, CMV) |"},{"n":"Calcineurin inhibitor nephrotoxicity / dehydration |"}],"redflags":["هیپوتانسیون یا آریتمی در قلب پیوندی، تب با هیپوکسمی در ریه، افزایش کراتینین، علائم صفاقی در کبد"],"guide":"رد حاد: methylprednisolone 1 g IV پس از مشاوره با مرکز پیوند (معمولاً پس از تأیید بیوپسی مگر ناپایدار). قلب: آتروپین بی‌اثر در قلب دناروه: isoproterenol 2 تا 10 μg/min IV؛ هیپوتانسیون: dopamine 2 تا 20 μg/kg/min یا dobutamine 2 تا 20 μg/kg/min. ریه: آنتی‌بیوتیک تجربی (بالا) و methylprednisolone 1 g؛ آزمایش: CXR، SpO2، ABG، اسپیرومتری، CBC، الکترولیت، کراتینین، منیزیم، سطح دارو. کبد: انسداد صفراوی: balloon dilatation و آنتی‌بیوتیک وسیع‌الطیف: metronidazole 500 mg IV هر 12 ساعت + imipenem 500 mg هر 6 ساعت یا piperacillin/tazobactam 3.375 g هر 6 ساعت؛ نشت صفراوی: جراحی؛ ترومبوز شریان کبدی: ممکن است پیوند مجدد. همه: انتقال به مرکز پیوند در صورت امکان.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 99: The Transplant Patient, pp. 546–554"},"graft-versus-host-disease":{"id":"graft-versus-host-disease","variants":[{"id":"gvhd-main","o":{"L":[{"t":"CBC (thrombocytopenia), coagulation, liver function tests (hyperbilirubinemia); stool studies to exclude infection","fl":[{"k":"note","v":"not detailed in the chapter"}]}],"T":[{"t":"Prednisone 60 mg PO daily, or Methylprednisolone 1 to 2 mg/kg IV daily"},{"t":"Reinstitute or increase other immunosuppressants if recently tapered or discontinued"},{"t":"Supportive care"}],"Co":[{"t":"Transplant team consultation; possible admission or transfer to the transplant center"}]},"name":"Suspected graft-versus-host disease","level":"II","imp":"Graft-versus-host disease","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مرد ۳۵ ساله ۶ هفته پس از پیوند مغز استخوان با راش ماکولوپاپولار کف دست‌ها، اسهال و موکوزیت.","why":"GVHD بالینی: استروئید و مشاوره تیم پیوند."}],"ch":"99","name":"Graft-versus-host disease (hematopoietic stem cell transplant)","name_fa":"بیماری پیوند علیه میزبان (GVHD) پس از پیوند سلول بنیادی","cc":["rash","diarrhea","gi-bleeding"],"keywords":"graft-versus-host disease, GVHD, HSCT, hematopoietic stem cell transplant, methylprednisolone, prednisone, mucositis, GVHD","status":"draft","features":["HSCT برای بدخیمی‌های هماتوپوئتیک، آنمی شدید و غیره؛ شایع‌ترین عارضه GVHD (حدود 50٪)","راش ماکولوپاپولار غیراختصاصی (ممکن است خارش‌دار یا دردناک؛ رنگ قهوه‌ای با پوسته‌ریزی ظریف)؛ اغلب ابتدا کف دست/پا سپس گونه، گوش، گردن، تنه و پشت؛ شدید: اریترودرمی یا بول؛ موکوزیت 35٪ تا 70٪","دومین تظاهر: اسهال؛ علائم GI فوقانی (بی‌اشتهایی، تهوع، استفراغ)، کرامپ دردناک، ایلئوس و گاهی خونریزی تهدیدکننده حیات کولون؛ درگیری کبد: هیپربیلی‌روبینمی و LFT بالا","تشخیص اولیه بالینی؛ خونریزی GI زودهنگام ممکن است با ترومبوسیتوپنی/کواگولوپاتی همراه باشد؛ افتراق خونریزی GI: همه علل معمول به‌علاوه عفونت"],"ddx":[{"n":"Life-threatening GI hemorrhage from GVHD |","cm":1},{"n":"Infection (CMV, drug eruption) |","cm":1},{"n":"Drug rash / viral exanthem |"},{"n":"Infectious colitis |"}],"redflags":["خونریزی GI، اریترودرمی/بول، هیپربیلی‌روبینمی"],"guide":"بیشتر بیماران درمان حمایتی با تیم پیوند (بستری یا انتقال به مرکز). prednisone 60 mg PO روزانه یا methylprednisolone 1 تا 2 mg/kg IV روزانه. اگر سایر ایمنوساپرسان اخیراً کاهش/قطع شده‌اند معمولاً افزایش یا از سر گرفته می‌شوند.","section":"infectious-immunologic","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 99: The Transplant Patient, pp. 546–554"}});
